export const TESTWHAT_R_SOURCES: Record<string, string> = {
  "aaa-s3-definitions.R": "#' S3 definitions\n#'\n#' @param state State to start from\n#' @param ... Additional arguments passed to implementations of the S3 method\n#'\n#' @name s3defs\n\n#' @rdname s3defs\n#' @export\ncheck_equal <- function(state, ...) {\n  UseMethod(\"check_equal\", state)\n}\n\n#' @rdname s3defs\n#' @export\ncheck_equal.default <- function(state, ...) {\n  stop(\"Can't run check_equal() with a \", class(state)[1], \" as input state.\", call. = FALSE)  \n}\n\n#' @rdname s3defs\n#' @export\ncheck_result <- function(state, ...) {\n  UseMethod(\"check_result\", state)\n}\n\n#' @rdname s3defs\n#' @export\ncheck_result.default <- function(state, ...) {\n  stop(\"Can't run check_result() with a \", class(state)[1], \" as input state.\", call. = FALSE)\n}\n\n#' @rdname s3defs\n#' @export\ncheck_body <- function(state, ...) {\n  UseMethod(\"check_body\", state) \n}\n\n#' @rdname s3defs\n#' @export\ncheck_body.default <- function(state, ...) {\n  stop(\"Can't run check_body() with a \", class(state)[1], \" as input state.\", call. = FALSE)\n}\n\n#' @rdname s3defs\n#' @export\ncheck_option <- function(state, ...) {\n  UseMethod(\"check_option\", state) \n}\n\n#' @rdname s3defs\n#' @export\ncheck_option.default <- function(state, ...) {\n  stop(\"Can't run check_option() with a \", class(state)[1], \" as input state.\", call. = FALSE)  \n}\n",
  "check-code.R": "#' Test the student's code as text\n#'\n#' Some rudimentary string cleaning is performed to allow for different ways of\n#' saying the same things (removing spaces, changing single quotes to double\n#' quotes, changing TRUE to T ...).\n#'\n#' Using these function should be a last resort, as there are myriad ways of\n#' solving the same problem with R!\n#'\n#' @param regex A set of strings/regexes that should be in the student code.\n#' @param fixed if TRUE, strings are treated literally. If FALSE, strings are\n#'   treated as regex patterns.\n#' @param times how often should any of the strings be matched?\n#' @param state the state to start from\n#' @param missing_msg Custom feedback in case the pattern is not contained often\n#'   enough in the student's submission.\n#' @param append Whether or not to append the feedback to feedback built in\n#'   previous states\n#' @param drop_comments Logical value indicating whether or not to remove\n#'   comments from these student code before looking for the pattern. Defaults\n#'   to FALSE for backwards compatibility reasons.\n#' @examples\n#' \\dontrun{\n#' # Example 1\n#' TRUE & FALSE\n#'\n#' # SCT\n#' ex() %>% check_code(c(\"TRUE & FALSE\", \"FALSE & TRUE\"), fixed = TRUE)\n#'\n#' # Example 2:\n#' \"Hello, world!\"\n#'\n#' # SCT, robust to small typos\n#' ex() %>% check_code(\"[H|h]ello,*\\\\s*[W|w]orld\\\\!*\")\n#' }\n#'\n#' @export\ncheck_code <- function(state, regex,\n                       fixed = FALSE, times = 1,\n                       missing_msg = NULL, append = TRUE,\n                       drop_comments = FALSE) {\n  assert_state(state)\n  regex_state <- RegexState$new(state)\n  regex_state$add_details(type = \"typed\",\n                          regex = regex,\n                          fixed = fixed,\n                          times = times,\n                          message = missing_msg,\n                          append = append,\n                          pd = NULL)\n  student_code <- state$get(\"student_code\")\n  if (isTRUE(drop_comments)) {\n    student_code <- remove_comments(student_code)\n  }\n  if (isTRUE(fixed)) {\n    student_code <- clean_up(student_code)\n    regex <- clean_up(regex)\n  }\n  num_hits <- get_num_hits(regex = regex, x = student_code, fixed = fixed)\n  check_that(is_gte(num_hits, times), feedback = regex_state$details)\n  return(state)\n}\n\n# deprecated test_student_typed\ntest_student_typed <- function(strings,\n                               fixed = TRUE,\n                               times = 1,\n                               not_typed_msg = NULL) {\n  fail_if_v2_only()\n  ex() %>% check_code(strings, fixed = fixed, times = times, missing_msg = not_typed_msg, append = is.null(not_typed_msg))\n}\n\n",
  "check-control.R": "#' Check whether student coded a control statement correctly\n#' \n#' @param state state to start from (for \\code{check_} functions)\n#' @param index Number of that particular control statement to check\n#' @param not_found_msg Custom message in case the control statement was not found\n#' @param append Whether or not to append the feedback to feedback built in previous states\n#' @param ... S3 stuff\n#' \n#' @examples\n#' \\dontrun{\n#' # Example 1: if else\n#' vec <- c(\"a\", \"b\", \"c\")\n#' if(\"a\" %in% vec) {\n#'  print(\"a in here\")\n#' } else if(any(\"b\" > vec)) {\n#'  cat(\"b not smallest\")\n#' } else {\n#'  str(vec)\n#' }\n#'                                            \n#' # SCT\n#' check_if_else(1) %>%  {\n#'   check_cond(.) %>% {\n#'     check_code(., \"%in%\")\n#'     check_code(., \"vec\")\n#'   }\n#'   check_if(.) %>% check_function(., \"print\")\n#'   check_else(.) %>% check_if_else() %>% {\n#'     check_cond(.) %>% check_code(\">\")\n#'     check_if(.) %>% check_function(\"cat\")\n#'     check_else(.) %>% check_function(\"str\")\n#'   }\n#' }\n#' \n#' # Example 2: while loop\n#' while(x < 18) {\n#'  x <- x + 5\n#'  print(x)\n#' }\n#' \n#' # SCT\n#' check_while(1) %>% {\n#'   check_cond(.) %>% check_code(c(\"< 18\", \"18 >\"))\n#'   check_body(.) %>% {\n#'     check_code(., c(\"x + 5\", \"5 + x\"))\n#'     check_function(., \"print\") %>% test_arg(\"x\")\n#'   }\n#' }\n#' \n#' # Example 3: for loop\n#' for(i in 1:5) {\n#'  print(\"hurray!\") \n#' }\n#' \n#' # SCT\n#' ex() %>% check_for() %>% {\n#'   check_cond(.) %>% {\n#'     check_code(., \"in\")\n#'     check_code(., \"1\")\n#'     check_code(., \"5\")\n#'   }\n#'   check_body(.) %>% check_function(\"print\") %>% check_arg(\"x\") %>% check_equal()\n#' }\n#' }\n#' @name check_control\n\n#' @rdname check_control\n#' @export\ncheck_if_else <- function(state, index = 1, not_found_msg = NULL, append = TRUE) {\n  assert_state(state)\n  check_control(state, index, not_found_msg, append = append, type = \"if\")\n}\n\n#' @rdname check_control\n#' @export\ncheck_while <- function(state, index = 1, not_found_msg = NULL, append = TRUE) {\n  assert_state(state)\n  check_control(state, index, not_found_msg, append = append, type = \"while\")\n}\n\n#' @rdname check_control\n#' @export\ncheck_for <- function(state, index = 1, not_found_msg = NULL, append = TRUE) {\n  assert_state(state)\n  check_control(state, index, not_found_msg, append = append, type = \"for\")\n}\n\n\ncheck_control <- function(state, index, not_found_msg, append, type = c(\"if\", \"while\", \"for\")) {\n  type <- match.arg(type)\n  student_pd <- state$get(\"student_pd\")\n  solution_pd <- state$get(\"solution_pd\")\n  student_code <- state$get(\"student_code\")\n  solution_code <- state$get(\"solution_code\")\n  \n  control_state <- ControlState$new(state)\n  control_state$add_details(type = type,\n                            case = \"defined\",\n                            index = index,\n                            message = not_found_msg,\n                            append = append,\n                            pd = NULL)\n\n  extract_fun <- switch(type,\n                        `if` = extract_if,\n                        `for` = extract_for,\n                        `while` = extract_while)\n  student_structs <- extract_fun(student_pd)\n  solution_structs <- extract_fun(solution_pd)\n  \n  if (length(solution_structs) < index) {\n    stop(sprintf(\"The solution doesn't contain %s %s statements itself.\", index, type))\n  }\n  \n  check_that(is_true(length(student_structs) >= index), \n             feedback = control_state$details)\n  \n  sol_str <- solution_structs[[index]]\n  stud_str <- student_structs[[index]]\n  \n  control_state$set_details(case = \"correct\",\n                            message = NULL,\n                            pd = NULL)\n  \n  control_state$set(student_struct = stud_str,\n                    solution_struct = sol_str)\n  return(control_state)\n}\n\n#' @rdname check_control\n#' @export\ncheck_cond <- function(state) {\n  assert_state(state)\n  student_struct <- state$get(\"student_struct\")\n  solution_struct <- state$get(\"solution_struct\")\n  cond_state <- SubState$new(state)\n  cond_state$add_details(type = \"condition\", pd = student_struct[[\"cond_part\"]]$pd, append = TRUE)\n  decorate_state(cond_state, student_struct, solution_struct, \"cond_part\")\n  return(cond_state)\n}\n\n#' @rdname check_control\n#' @export\ncheck_body.ControlState <- function(state, ...) {\n  assert_state(state)\n  student_struct <- state$get(\"student_struct\")\n  solution_struct <- state$get(\"solution_struct\")\n  body_state <- SubState$new(state)\n  body_state$add_details(type = \"body\", pd = student_struct[[\"expr_part\"]]$pd, append = TRUE)\n  decorate_state(body_state, student_struct, solution_struct, \"expr_part\")\n  return(body_state)\n}\n\n#' @rdname check_control\n#' @export\ncheck_if <- function(state) {\n  assert_state(state)\n  student_struct <- state$get(\"student_struct\")\n  solution_struct <- state$get(\"solution_struct\")\n  if_state <- SubState$new(state)\n  if_state$add_details(type = \"ifexpression\", pd = student_struct[[\"if_part\"]]$pd, append = TRUE)\n  decorate_state(if_state, student_struct, solution_struct, \"if_part\")\n  return(if_state)\n}\n\n#' @rdname check_control\n#' @export\ncheck_else <- function(state, not_found_msg = NULL, append = TRUE) {\n  assert_state(state)\n  student_struct <- state$get(\"student_struct\")\n  solution_struct <- state$get(\"solution_struct\")\n  else_state <- SubState$new(state)\n  else_state$add_details(type = \"elseexpression\",\n                         case = \"defined\",\n                         message = not_found_msg,\n                         append = append,\n                         pd = state$get(\"student_pd\"))\n  \n  if (is.null(solution_struct[[\"else_part\"]])) {\n    stop(sprintf(\"The control construct in the solution doesn't contain an else part itself.\"))\n  }\n  \n  check_that(is_false(is.null(student_struct[[\"else_part\"]])), \n             feedback = else_state$details)\n  \n  else_state$set_details(case = \"correct\",\n                         message = NULL,\n                         pd = student_struct[[\"else_part\"]]$pd)\n  decorate_state(else_state, student_struct, solution_struct, \"else_part\")\n  return(else_state)\n}\n\n# Deprecated functions\n\ntest_if_else <- function(index = 1, \n                         if_cond_test = NULL, \n                         if_expr_test = NULL, \n                         else_expr_test = NULL,\n                         not_found_msg = NULL,\n                         missing_else_msg = NULL) {\n  fail_if_v2_only()\n  old_state <- ex()  \n  test_env <- old_state$get(\"test_env\")\n  on.exit(tw$set(state = old_state))\n  \n  testif <- old_state %>% check_if_else(index = index, not_found_msg = not_found_msg, append = is.null(not_found_msg))\n  \n  if_cond_test <- substitute(if_cond_test)\n  if (!is.null(if_cond_test)) {\n    cond_state <- testif %>% check_cond()\n    tw$set(state = cond_state)\n    eval(if_cond_test, envir = test_env)\n  }\n  \n  if_expr_test <- substitute(if_expr_test)\n  if (!is.null(if_expr_test)) {\n    ifexprstate <- testif %>% check_if()\n    tw$set(state = ifexprstate)\n    eval(if_expr_test, envir = test_env)\n  }\n  \n  else_expr_test <- substitute(else_expr_test)\n  if (!is.null(else_expr_test)) {\n    elseexprstate <- testif %>% check_else(not_found_msg = missing_else_msg, append = is.null(missing_else_msg))\n    tw$set(state = elseexprstate)\n    eval(else_expr_test, envir = test_env)\n  }\n}\n\ntest_while_loop <- function(index = 1, \n                            cond_test = NULL, \n                            expr_test = NULL,                          \n                            not_found_msg = NULL) {\n  fail_if_v2_only()\n  cond_test <- substitute(cond_test)\n  expr_test <- substitute(expr_test)\n  test_loop(index = index, \n            cond_test = cond_test,\n            expr_test = expr_test,\n            not_found_msg = not_found_msg,\n            fun = check_while)\n}\n\ntest_for_loop <- function(index = 1, \n                          cond_test = NULL,\n                          expr_test = NULL,\n                          not_found_msg = NULL) {\n  fail_if_v2_only()\n  cond_test <- substitute(cond_test)\n  expr_test <- substitute(expr_test)\n  test_loop(index = index, \n            cond_test = cond_test,\n            expr_test = expr_test,\n            not_found_msg = not_found_msg,\n            fun = check_for)\n}\n\ntest_loop <- function(index, cond_test, expr_test, not_found_msg, fun) {\n  old_state <- ex()\n  test_env <- old_state$get(\"test_env\")\n  on.exit(tw$set(state = old_state))\n  \n  testloop <- old_state %>% fun(index = index, not_found_msg = not_found_msg, append = is.null(not_found_msg))\n  \n  if (!is.null(cond_test)) {\n    cond_state <- testloop %>% check_cond()\n    tw$set(state = cond_state)\n    eval(cond_test, envir = test_env)\n  }\n  \n  if (!is.null(expr_test)) {\n    body_state <- testloop %>% check_body()\n    tw$set(state = body_state)\n    eval(expr_test, envir = test_env)\n  }\n}\n\n\n\n",
  "check-error.R": "#' Explicitly check whether the student's submission threw an error.\n#'\n#' With information gathered from the R Backend, testwhat can detect whether the\n#' student's submission generated an error.\n#'\n#' If all SCTs for an exercise pass, before marking the submission as correct\n#' testwhat will automatically check whether the student submission generated an\n#' error, unless the exercise explicitly allows for errors. This means it is not\n#' needed to use \\code{check_error} explicitly. However, in some cases,\n#' using \\code{check_error} explicitly somewhere\n#' throughout your SCT execution can be helpful:\n#'\n#' \\itemize{\n#' \\item{If you want to make sure people didn't write typos when\n#' writing a long function name.}\n#' \\item{If you want to first verify whether a\n#' function call actually runs,before checking whether the arguments were\n#' specified correctly.}\n#' \\item{More generally, if, because of the content, it's\n#' instrumental that the script runs without errors before doing any other\n#' verifications.}\n#' }\n#'\n#' @param state State to start from (for \\code{check_error})\n#' @param incorrect_msg additional message that is appended to the automatically\n#'   generated feedback message.\n#' @param ... S3 stuff\n#'\n#' @examples\n#' \\dontrun{\n#' # Example student code: x <- 4 + \"a\"\n#'\n#' # SCT that explicitly checks for an error first\n#' ex() %>% check_error()\n#' ex() %>% check_object('x') %>% check_equal()\n#' \n#' # SCT that does not have to check for an error\n#' # testwhat will verify for an error implicitly\n#' ex() %>% check_object('x') %>% check_equal()\n#' }\n#'\n#' @name check_error\n\n#' @rdname check_error\n#' @export\ncheck_error <- function(state, ...) {\n  UseMethod(\"check_error\", state)\n}\n\n#' @rdname check_error\n#' @export\ncheck_error.default <- function(state, incorrect_msg = NULL, ...) {\n  assert_state(state)\n  output_list <- state$get(\"output_list\")\n  student_pd <- state$get(\"student_pd\")\n  \n  error_state <- ErrorState$new(state)\n\n  error_indices <- which(sapply(output_list, `[[`, \"type\") == \"r-error\")\n  if(length(error_indices) == 0) {\n    fb_msg <- \"ok\"\n    pd <- NULL\n  } else {\n    error_index <- error_indices[1]\n    error <- output_list[[error_index]]$payload\n    fb_msg <- paste(\"Your code contains an error that you should fix:\",\n                    \"```\",\n                    error,\n                    \"```\",\n                    ifelse(is.null(incorrect_msg), \"\", incorrect_msg),\n                    sep = \"\\n\")\n    \n    line_info <- NULL\n    call_index <- error_indices[1] - 1\n    if(call_index > 0) {\n      call <- output_list[[call_index]]$payload\n      hits <- student_pd$text == call\n      if(!any(hits)) {\n        pd <- NULL\n      } else if (sum(hits) == 1) {\n        pd <- student_pd[hits, ]\n      } else {\n        # more than 1 hit - select the code that actually generated the error\n        hit_indices <- which(sapply(output_list, function(x) {\n          x$type == \"code\" && x$payload == call\n        }))\n        pd <- student_pd[which(hits)[call_index == hit_indices], ]\n      }\n    } else {\n      pd <- NULL\n    }\n  }\n  error_state$add_details(type = \"error\", message = fb_msg, pd = pd, append = TRUE)\n  check_that(is_true(length(error_indices) == 0), feedback = error_state$details)\n  return(error_state)\n}\n\n# Deprecated\ntest_error <- function(incorrect_msg = NULL) {\n  fail_if_v2_only()\n  ex() %>% check_error(incorrect_msg = incorrect_msg)\n}\n",
  "check-expr.R": "#' Check the result, output or errors thrown by an expression\n#'\n#' Run an expression in student and solution environment and compare the result,\n#' output or error that is thrown by it.\n#'\n#' @param state state to start from (only for \\code{check_} functions)\n#' @param expr the expression to run\n#' @param eq_condition character string indicating how to compare. See\n#'   \\code{\\link{is_equal}}.\n#' @param eq_fun optional argument to specify a custom equality function. The\n#'   function should take two arguments and always return a single boolean\n#'   value: \\code{TRUE} or \\code{FALSE}.\n#' @param error_msg custom message in case the expression throws an error while\n#'   it shouldn't\n#' @param no_error_msg custom message in case the expression doesn't throw an\n#'   error while it should\n#' @param incorrect_msg custom message in case the result, output or error of\n#'   the expression does not correspond with the solution\n#' @param append Whether or not to append the feedback to feedback built in\n#'   previous states\n#' @param ... S3 stuff\n#'\n#' @rdname test_expr\n#' @examples\n#' \\dontrun{\n#' # Example 1\n#' a <- c(1, 2, 3, 4, 5, 6)\n#'\n#' # SCT\n#' ex() %>% check_expr(\"a[c(2, 4)]\") %>% check_result() %>% check_equal()\n#'\n#' # Example 2\n#' my_fun <- function() { print('hello') }\n#'\n#' # SCT\n#' ex() %>% check_expr(\"my_fun()\") %>% check_output() %>% check_equal()\n#' }\n\n#' @rdname test_expr\n#' @export\ncheck_expr <- function(state, expr) {\n  assert_state(state)\n  expr_state <- ExprState$new(state)\n  expr_state$set(expr = parse(text = expr))\n  return(expr_state)\n}\n\n#' @rdname test_expr\n#' @export\ncheck_result.ExprState <- function(state, error_msg = NULL, append = TRUE, ...) {\n  assert_state(state)\n  expr <- state$get(\"expr\")\n  run_expr_helper(state, \n                  expr = expr,\n                  expr_str = as.character(expr),\n                  error_msg = error_msg,\n                  append = append,\n                  case = \"result\")\n}\n\n\n#' @rdname test_expr\n#' @export\ncheck_output.ExprState <- function(state, error_msg = NULL, append = TRUE, ...) {\n  assert_state(state)\n  expr <- state$get(\"expr\")\n  run_expr_helper(state, \n                  expr = expr,\n                  expr_str = as.character(expr),\n                  error_msg = error_msg,\n                  append = append,\n                  case = \"output\")\n}\n\n#' @rdname test_expr\n#' @export\ncheck_error.ExprState <- function(state, no_error_msg = NULL, append = TRUE, ...) {\n  assert_state(state)\n  expr <- state$get(\"expr\")\n  run_expr_error_helper(state, \n                        expr = expr,\n                        expr_str = as.character(expr),\n                        no_error_msg = no_error_msg,\n                        append = append)\n}\n\n#' @rdname test_expr\n#' @export\ncheck_equal.ExprResultState <- function(state, eq_condition = \"equivalent\", eq_fun = NULL, incorrect_msg = NULL, append = TRUE, ...) {\n  assert_state(state)\n  expr_check_equal_helper(state, incorrect_msg, eq_condition, eq_fun = eq_fun, append = append, type = \"result\")\n}\n\n#' @rdname test_expr\n#' @export\ncheck_equal.ExprOutputState <- function(state, eq_fun = NULL, incorrect_msg = NULL, append = TRUE, ...) {\n  assert_state(state)\n  expr_check_equal_helper(state, incorrect_msg, eq_fun = eq_fun, append = append, type = \"output\")\n}\n\n#' @rdname test_expr\n#' @export\ncheck_equal.ExprErrorState <- function(state, eq_fun = NULL, incorrect_msg = NULL, append = TRUE, ...) {\n  assert_state(state)\n  expr_check_equal_helper(state, incorrect_msg, eq_fun = eq_fun, append = append, type = \"error\")\n}\n\nrun_expr_helper <- function(state, expr, expr_str, error_msg, append, case = c(\"result\", \"output\")) {\n  case <- match.arg(case)\n  converter <- switch(case, result = identity, output = capture.output)\n  StateType <- switch(case, result = ExprResultState, output = ExprOutputState)\n  \n  expreval_state <- StateType$new(state)\n  expreval_state$add_details(type = \"expr\",\n                             case = sprintf(\"%s_runs\", case),\n                             expr_str = expr_str,\n                             message = error_msg,\n                             append = append,\n                             pd = NULL)\n  \n  set.seed(tw$get(\"seed\"))\n  sol_res <- tryCatch(converter(eval(expr, envir = state$get(\"solution_env\"))), error = function(e) e)\n  if (inherits(sol_res, 'error')) {\n    stop(sprintf(\"Running %s gave an error\", expr_str))\n  }\n  \n  set.seed(tw$get(\"seed\"))\n  stud_res <- tryCatch(converter(eval(expr, envir = state$get(\"student_env\"))), error = function(e) e)\n  check_that(is_false(inherits(stud_res, 'error')), feedback = expreval_state$details)\n  \n  expreval_state$set_details(type = \"expr\",\n                             case = sprintf(\"%s_correct\", case),\n                             message = NULL,\n                             pd = NULL)\n  expreval_state$set(student_object = stud_res, solution_object = sol_res)\n  return(expreval_state)\n}\n\n# Deprecated functions\n\ntest_expression_result <- function(expr, \n                                   eq_condition = \"equivalent\",\n                                   incorrect_msg = NULL) {\n  fail_if_v2_only()\n  ex() %>% \n    check_expr(expr) %>% \n    check_result() %>% \n    check_equal(eq_condition = eq_condition, incorrect_msg = incorrect_msg, append = is.null(incorrect_msg))\n}\n\n#' @importFrom utils capture.output\ntest_expression_output <- function(expr, incorrect_msg = NULL) {\n  fail_if_v2_only()\n  ex() %>% \n    check_expr(expr) %>% \n    check_output() %>% \n    check_equal(incorrect_msg = incorrect_msg, append = is.null(incorrect_msg))\n}\n\ntest_expression_error <- function(expr, no_error_msg = NULL, incorrect_msg = NULL) {\n  fail_if_v2_only()\n  ex() %>% \n    check_expr(expr) %>% \n    check_error(no_error_msg = no_error_msg, append = is.null(no_error_msg)) %>% \n    check_equal(incorrect_msg = incorrect_msg, append = is.null(incorrect_msg))\n}\n\n\n\nrun_expr_error_helper <- function(state, expr, expr_str, no_error_msg, append) {\n\n  exprerror_state <- ExprErrorState$new(state)\n  exprerror_state$add_details(type = \"expr\",\n                              case = \"error_fails\",\n                              expr_str = expr_str,\n                              message = no_error_msg,\n                              append = append,\n                              pd = NULL)\n  \n  set.seed(tw$get(\"seed\"))\n  sol_res <- tryCatch(eval(expr, envir = state$get(\"solution_env\")), error = function(e) e)\n  if (!inherits(sol_res, 'error')) {\n    stop(sprintf(\"Running %s didn't give an error, while it should.\", expr_str))\n  }\n  \n  set.seed(tw$get(\"seed\"))\n  stud_res <- tryCatch(eval(expr, envir = state$get(\"student_env\")), error = function(e) e)\n  check_that(is_true(inherits(stud_res, 'error')), feedback = exprerror_state$details)\n  \n  exprerror_state$set_details(type = \"expr\",\n                              case = \"error_correct\",\n                              message = NULL,\n                              pd = NULL)\n  exprerror_state$set(student_object = stud_res$message, solution_object = sol_res$message)\n  return(exprerror_state)\n}\n\n\nexpr_check_equal_helper <- function(state, incorrect_msg, eq_condition = \"equivalent\", eq_fun = NULL, append, type = c(\"result\", \"output\", \"error\")) {\n  type <- match.arg(type)\n  student_obj <- state$get(\"student_object\")\n  solution_obj <- state$get(\"solution_object\")\n  state$add_details(type = \"expr\",\n                    case = sprintf(\"%s_equal\", type),\n                    eq_condition = eq_condition,\n                    student = student_obj,\n                    solution = solution_obj,\n                    message = incorrect_msg,\n                    append = append)\n  \n  if (is.null(eq_fun)) {\n    eq_fun <- function(x, y) is_equal(x, y, eq_condition)\n  }\n\n  check_that(eq_fun(student_obj, solution_obj),\n             feedback = state$details)\n  return(state)\n}\n\n",
  "check-fun-def.R": "#' Check whether the student defined a function correctly\n#' \n#' \\code{check_fun_def} checks whether an object is defined in the student enviornment, and returns a state that can be piped to:\n#' \\itemize{\n#'   \\item{\\code{check_arguments}, to check whether the correct arguments where specified.}\n#'   \\item{\\code{check_call}, to call the function with the provided arguments, and produces a state that can be piped to \\code{check_output}, \\code{check_result} and \\code{check_error} to compare the output, result or error from calling the function between student and solution.}\n#'   \\item{\\code{check_body}, that returns a state that focuses on the body that defines the function. Note that you cannot use \\code{\\link{check_object}} to compare variables that are limited to the function scope.}\n#' }\n#'\n#' @param name  The name of the function to test\n#' @param undefined_msg Custom message in case the specified function\n#'   was not defined\n#' @param no_fundef_msg Custom message in case the function specified in \\code{name} is not a function.\n#' @param not_found_msg Custom feedback message if function definition was not\n#'   found.\n#' @param incorrect_number_arguments_msg Optional feedback message in case the \n#'   function does not have the correct number of arguments.\n#' @param ... arguments to pass to the user-defined function to test result, output or error in a later stage\n#' @param state the state to start from\n#' @param append Whether or not to append the feedback to feedback built in previous states\n#' \n#' @examples\n#' \\dontrun{\n#' # Example:\n#' my_op <- function(a, b) {\n#'   stopifnot(length(a) == length(b))\n#'   return(abs(a) + abs(b))\n#' }\n#' \n#' # Robust SCT\n#' ex() %>% check_fun_def('my_op') %>% check_correct(\n#'   {\n#'     check_call(., c(1, 2), c(3, 4)) %>% check_result() %>% check_equal()\n#'     check_call(., c(1, -2), c(3, -4)) %>% check_result() %>% check_equal()\n#'     check_call(., c(-1, 2), c(-3, 4)) %>% check_result() %>% check_equal()\n#'     check_call(., 1, c(3, 4)) %>% check_error()\n#'     check_call(., c(1, -2), 3) %>% check_error()\n#'   },\n#'   {\n#'     check_arguments(.)\n#'     check_body(.) %>% {\n#'       check_function(., 'stopifnot') %>% check_arg('...') %>% {\n#'         check_function(., 'length', index = 1) %>% check_arg('x') %>% check_equal(eval = FALSE)\n#'         check_function(., 'length', index = 2) %>% check_arg('x') %>% check_equal(eval = FALSE)\n#'         check_code(., '==')\n#'       }\n#'       check_function(., 'abs', index = 1) %>% check_arg('x') %>% check_equal(eval = FALSE)\n#'       check_function(., 'abs', index = 2) %>% check_arg('x') %>% check_equal(eval = FALSE)\n#'     }\n#'   }\n#' )\n#' }\n#' \n#' @name check_fun_def\n\n#' @rdname check_fun_def\n#' @export\ncheck_fun_def <- function(state, name, undefined_msg = NULL, no_fundef_msg = NULL, append = TRUE) {\n  assert_state(state)\n  student_env <- state$get(\"student_env\")\n  solution_env <- state$get(\"solution_env\")\n  \n  fundef_state <- FunDefState$new(state)\n  fundef_state$add_details(type = \"fundef\",\n                          case = \"defined\",\n                          name = name,\n                          message = undefined_msg,\n                          append = append,\n                          pd = NULL)\n  \n  check_defined(name, solution_env)\n  solution_object <- get(name, envir = solution_env, inherits = FALSE)\n  if (!is.function(solution_object)) {\n    stop(sprintf(\"%s is not a user-defined function in the solution code.\", name))\n  }\n  \n  check_that(is_true(exists(name, envir = student_env, inherits = FALSE)), feedback = fundef_state$details)\n  student_object <- get(name, envir = student_env, inherits = FALSE)\n  \n  fundef_state$set_details(case = \"correcttype\",\n                           message = no_fundef_msg\n                           #pd = extract_function_definition(state$get(\"student_pd\"), name))\n                           )\n  \n  check_that(is_true(inherits(student_object, \"function\")),\n             feedback = fundef_state$details)\n  \n  fundef_state$set_details(case = \"correct\",\n                           message = NULL)\n  \n  fundef_state$set(name = name,\n                   student_object = student_object,\n                   solution_object = solution_object)\n  \n  return(fundef_state)\n}\n\n#' @rdname check_fun_def\n#' @export\ncheck_arguments <- function(state, incorrect_number_arguments_msg = NULL, append = TRUE) {\n  assert_state(state)\n  stud_arguments <- as.list(formals(state$get(\"student_object\")))\n  sol_arguments <- as.list(formals(state$get(\"solution_object\")))\n  \n  fundefargs_state <- FunDefArgsState$new(state)\n  \n  fundefargs_state$add_details(type = \"fundef\",\n                               case = \"arguments\",\n                               message = incorrect_number_arguments_msg,\n                               append = append,\n                               pd = NULL)\n  \n  check_that(is_equal(length(stud_arguments), length(sol_arguments)), \n             feedback = fundefargs_state$details)\n  return(fundefargs_state)\n}\n\n#' @rdname check_fun_def\n#' @export\ncheck_body.FunDefState <- function(state, not_found_msg = NULL, append = TRUE, ...) {\n  assert_state(state)\n  name <- state$get(\"name\")\n  student_pd <- state$get(\"student_pd\")\n  solution_pd <- state$get(\"solution_pd\")\n  \n  body_state <- SubState$new(state)\n  \n  body_state$add_details(type = \"fundef\",\n                         case = \"coded\",\n                         message = not_found_msg,\n                         append = append,\n                         pd = NULL)\n  \n  solution_fun_def <- extract_function_definition(solution_pd, name)\n  if (is.null(solution_fun_def)) {\n    stop(sprintf(\"The function definition of %s was not found in the solution code\", name))\n  }\n  \n  student_fun_def <- extract_function_definition(student_pd, name)\n  check_that(is_false(is.null(student_fun_def)), feedback = body_state$details)\n  \n  body_state$set_details(type = \"body\", pd = student_fun_def$pd)\n  decorate_state(body_state, student_fun_def, solution_fun_def)\n  return(body_state)\n}\n\n#' @rdname check_fun_def\n#' @export\ncheck_call <- function(state, ...) {\n  assert_state(state)\n  state$assert_is(\"FunDefState\", \"check_fun_def\")\n  expr_state <- ExprState$new(state)\n  fn_name <- state$get(\"name\")\n  fn_call <- substitute(list(...))\n  fn_call[1] <- call(fn_name)\n  expr_state$set(expr = as.expression(fn_call))\n  return(expr_state)\n}\n\n# Deprecated functions\n\ntest_function_definition <- function(name, \n                                     function_test = NULL,\n                                     body_test = NULL,\n                                     undefined_msg = NULL, \n                                     incorrect_number_arguments_msg = NULL) {\n  fail_if_v2_only()\n  body_test <- substitute(body_test)\n  function_test <- substitute(function_test)\n  fundef <- ex() %>% check_fun_def(name, \n                                   undefined_msg = undefined_msg, \n                                   append = is.null(undefined_msg))\n  \n  if (!is.null(function_test)) {\n    fun_res <- run_until_fail(function_test)\n\n    if (!fun_res$correct) {\n      fundef %>% check_arguments(incorrect_number_arguments_msg = incorrect_number_arguments_msg,\n                                 append = is.null(incorrect_number_arguments_msg))\n    }\n  }\n  \n  body_passed <- TRUE\n  if (!is.null(body_test)) {\n    oldstate <- ex()\n    on.exit(tw$set(state = oldstate))\n    body_state <- check_body(fundef)\n    tw$set(state = body_state)\n    body_res <- run_until_fail(body_test)\n  }\n  \n  if (is.null(function_test) || fun_res$correct) {\n    # all good\n  } else {\n    if (is.null(body_test) || body_res$correct) {\n      check_that(failure(), feedback = fun_res$feedback)\n    } else {\n      check_that(failure(), feedback = body_res$feedback)\n    }\n  }\n}\n\n\n\n",
  "check-function-result.R": "#' Check the result of a function call/operation\n#'\n#' @param error_msg feedback message in case the student function call at the\n#'   mentioned index generated an error.\n#' @param incorrect_msg  feedback message in case the evaluation was not the\n#'   same as in the solution.\n#' @param eq_condition character string indicating how to compare. See\n#'   \\code{\\link{is_equal}}.\n#' @param eq_fun optional argument to specify a custom equality function. The\n#'   function should take two arguments and always return a single boolean\n#'   value: \\code{TRUE} or \\code{FALSE}.\n#' @param state the state to start from (for \\code{check_} functions)\n#' @param append Whether or not to append the feedback to feedback built in\n#'   previous states\n#' @param ... S3 stuff\n#'\n#' @examples\n#' \\dontrun{\n#' # Example 1\n#' mean(1:3)\n#'\n#' # SCT\n#' ex() %>% check_function(\"mean\") %>% check_result() %>% check_equal()\n#' }\n#' @name check_function_result\n\n#' @rdname check_function_result\n#' @export\ncheck_result.OperationState <- function(state, error_msg = NULL, append = TRUE, ...) {\n  check_call_result(state, error_msg = error_msg, append = append, type = \"operator\")\n}\n\n#' @rdname check_function_result\n#' @export\ncheck_result.FunctionState <- function(state, error_msg = NULL, append = TRUE, ...) {\n  check_call_result(state, error_msg = error_msg, append = append, type = \"function\")\n}\n\n#' @rdname check_function_result\n#' @export\ncheck_equal.FunctionResultState <- function(state, eq_condition = \"equivalent\", eq_fun = NULL, incorrect_msg = NULL, append = TRUE, ...) {\n  check_call_result_equal(state, eq_condition = eq_condition, eq_fun = eq_fun, incorrect_msg = incorrect_msg, append = append, type = \"function\")\n}\n\n#' @rdname check_function_result\n#' @export\ncheck_equal.OperationResultState <- function(state, eq_condition = \"equivalent\", eq_fun = NULL, incorrect_msg = NULL, append = TRUE, ...) {\n  check_call_result_equal(state, eq_condition = eq_condition, eq_fun = eq_fun, incorrect_msg = incorrect_msg, append = append, type = \"operator\")\n}\n\ncheck_call_result <- function(state, error_msg, append, type = c(\"function\", \"operator\")) {\n  type <- match.arg(type)\n  CallResultState <- switch(type, `function` = FunctionResultState, operator = OperationResultState)\n  \n  solution_call <- state$get(\"solution_call\")\n  student_call <- state$get(\"student_call\")\n  student_env <- state$get(\"student_env\")\n  solution_env <- state$get(\"solution_env\")\n  \n  callresult_state <- CallResultState$new(state)\n  callresult_state$add_details(type = type,\n                               case = \"result_runs\",\n                               message = error_msg,\n                               pd = student_call$pd,\n                               append = append)\n  \n  sol_res <- tryCatch(base::eval(solution_call$call, envir = solution_env), error = function(e) e)\n  if (inherits(sol_res, 'error')) {\n    stop(sprintf(\"Running %s gave an error: %s\", deparse(solution_call$call), sol_res$message))\n  }\n\n  stud_res <- tryCatch(base::eval(student_call$call, envir = student_env), error = function(e) e)\n  \n  check_that(is_false(inherits(stud_res, 'error')), feedback = callresult_state$details)\n  \n  callresult_state$set(student_call_result = stud_res,\n                       solution_call_result = sol_res)\n  callresult_state$set_details(case = \"result_correct\",\n                               message = NULL)\n  return(callresult_state)\n}\n\n\n\ncheck_call_result_equal <- function(state, eq_condition, eq_fun, incorrect_msg, append, type = c(\"function\", \"operator\")) {\n  type <- match.arg(type)\n  sol_res <- state$get(\"solution_call_result\")\n  stud_res <- state$get(\"student_call_result\")\n  state$add_details(type = type,\n                    case = \"result_equal\",\n                    eq_condition = eq_condition,\n                    message = incorrect_msg,\n                    student = stud_res,\n                    solution = sol_res,\n                    append = append)\n  \n  if (is.null(eq_fun)) {\n    eq_fun <- function(x, y) is_equal(x, y, eq_condition)\n  }\n\n  check_that(is_true(eq_fun(stud_res, sol_res)), feedback = state$details)\n  \n  return(state)\n}\n\n# Deprecated\n\ntest_function_result <- function(name = NULL,\n                                 index = 1,\n                                 eq_condition = \"equivalent\",\n                                 not_called_msg = NULL,\n                                 error_msg = NULL,\n                                 incorrect_msg = NULL) {\n  fail_if_v2_only()\n  ex() %>% \n    check_function(name, index = index, not_called_msg = not_called_msg, append = is.null(not_called_msg)) %>% \n    check_result(error_msg = error_msg, append = is.null(error_msg)) %>%\n    check_equal(eq_condition = eq_condition, incorrect_msg = incorrect_msg, append = is.null(incorrect_msg))\n}\n\n\n",
  "check-function.R": "#' Check whether a student correctly called a function/operator\n#'\n#' Check whether a student called a function correctly. Note:\n#' \\code{test_function} and \\code{test_function_v2} are now identical and either\n#' can be used.\n#'\n#' @param state state to start from\n#' @param name  name of the function/operator as a string, e.g. \\code{\"mean\"} or\n#'   \\code{\"+\"}\n#' @param index  integer that specifies which call of \\code{name} in the\n#'   solution code will be checked.\n#' @param eval  logical vector indicating whether and how to compare arguments.\n#'   If \\code{eval} is \\code{NA}, student and solution argument are not\n#'   compared. If \\code{eval} is \\code{FALSE}, the string versions of the\n#'   arguments are compared. If \\code{eval} is \\code{TRUE}, the argument in the\n#'   student code is evaluated in the student environment and the argument in\n#'   the solution code is evaluated in the solution environment, and their\n#'   results are compared. Setting this to \\code{FALSE} can be useful, e.g., to\n#'   check whether the student supplied a large predefined object, or when\n#'   you're in a sub-SCT where the environments are not unambiguously available.\n#' @param eq_condition  character vector indicating how to perform the\n#'   comparison for each argument. See \\code{\\link{is_equal}}.\n#' @param eq_fun optional argument to specify a custom equality function. The\n#'   function should take two arguments and always return a single boolean\n#'   value: \\code{TRUE} or \\code{FALSE}.\n#' @param not_called_msg custom feedback message in case the student did not\n#'   call the function often enough.\n#' @param incorrect_msg custom feedback message in case the student did not call\n#'   the function with the same argument values as in the sample solution. You\n#'   can specify a vector of arguments with the same length as \\code{args}, to\n#'   have argument-specific custom feedback.\n#' @param append Whether or not to append the feedback to feedback built in\n#'   previous states\n#' @param ... S3 stuff\n#' @param arg_not_specified_msg custom message in case argument was not\n#'   specified (for \\code{check_arg})\n#' @param arg name or position of argument to specify\n#'   ... Arguments can be accessed using '..<INDEX>' (see example 5) (for \\code{check_arg})\n#'\n#' @examples\n#' \\dontrun{\n#' # Example 1\n#' mean(1:3)\n#'\n#' # SCT\n#' ex() %>% check_function(\"mean\") %>% check_arg(\"x\") %>% check_equal()\n#'\n#' # Example 2\n#' mean(c(NA, 1, 2), na.rm = TRUE)\n#'\n#' # SCT\n#' ex() %>% check_function(\"mean\") %>% {\n#'   check_arg(., \"x\") %>% check_equal()\n#'   check_arg(., \"na.rm\") %>% check_equal()\n#' }\n#'\n#' # Example 3\n#' 5 + 4\n#'\n#' # SCT\n#' ex() %>% check_operator(\"+\") %>% check_result() %>% check_equal()\n#' \n#' # Example 4: Positional argument check\n#' cor(rnorm(10), rnorm(10))\n#' \n#' # SCT\n#' ex() %>% check_function(\"cor\") %>% {\n#'   check_arg(., 1) %>% check_equal()\n#'   check_arg(., 2) %>% check_equal()\n#' }\n#'\n#' # Example 5: ... in check_args\n#'\n#' soln <- \"std_dev <- purrr::compose(sqrt, var, .dir='forward')\"\n#' state <- setup_state(soln, soln)\n#' state %>% check_function(., \"compose\") %>% {\n#'   check_arg(., '..1') %>% check_equal() # sqrt\n#'   check_arg(., '..2') %>% check_equal() # var\n#'   check_arg(., '.dir') %>% check_equal()\n#' }\n#'\n#' }\n#' @name check_function\n\n#' @rdname check_function\n#' @export\ncheck_function <- function(state, name, index = 1, not_called_msg = NULL, append = TRUE) {\n  assert_state(state)\n  state$assert_is_not(\"ObjectState\", \"check_object\")\n  check_fun_op_helper(state, name = name, index = index, not_called_msg = not_called_msg, append = append, type = \"function\")\n}\n\n#' @rdname check_function\n#' @export\ncheck_operator <- function(state, name, index = 1, append = TRUE, not_called_msg = NULL) {\n  assert_state(state)\n  state$assert_is_not(\"ObjectState\", \"check_object\")\n  check_fun_op_helper(state, name = name, index = index, not_called_msg = not_called_msg, append = append, type = \"operator\")\n}\n\ncheck_fun_op_helper <- function(state, name, index, not_called_msg, append, type = c(\"function\", \"operator\")) {\n\n  type <- match.arg(type)\n  finder <- switch(type, `function` = find_function_calls, operator = find_operators)\n  CallState <- switch(type, `function` = FunctionState, operator = OperationState)\n\n  call_state <- CallState$new(state)\n  call_state$add_details(type = type,\n                         case = \"called\",\n                         name = name,\n                         index = index,\n                         message = not_called_msg,\n                         append = append,\n                         pd = NULL)\n\n  student_calls <- finder(pd = state$get(\"student_pd\"),\n                          name = name,\n                          env = state$get(\"student_env\"))\n  solution_calls <- finder(pd = state$get(\"solution_pd\"),\n                           name = name,\n                           env = state$get(\"solution_env\"))\n\n  check_sufficient(solution_calls, index, name)\n  solution_call <- solution_calls[[index]]\n\n  check_that(is_true(length(student_calls) >= index), feedback = call_state$details)\n  student_call <- student_calls[[index]]\n\n  # update the case for future tests\n  call_state$set_details(case = \"correct\",\n                         message = NULL)\n\n  call_state$set(solution_call = solution_call)\n  call_state$set(student_call = student_call)\n  return(call_state)\n}\n\n#' @rdname check_function\n#' @export\ncheck_arg <- function(state, arg, arg_not_specified_msg = NULL, append = TRUE) {\n  assert_state(state)\n  state$assert_is(\"CallState\", \"check_function\")\n\n  solution_call <- state$get(\"solution_call\")\n  student_call <- state$get(\"student_call\")\n\n  arg_state <- ArgumentState$new(state)\n  arg_state$add_details(type = \"argument\",\n                        case = \"specified\",\n                        name = arg,\n                        message = arg_not_specified_msg,\n                        pd = student_call$pd,\n                        append = append)\n\n  if(is.numeric(arg)) {\n    if(!arg %in% seq_along(solution_call$args)) {\n      msg <- sprintf(\n        \"A numeric 'arg' should be between 1 and the number of arguments (%d). You specified %d.\",\n        length(solution_call$args),\n        arg\n      )\n      stop(msg)\n    }\n    arg <- names(solution_call$args)[arg]\n  }\n\n  index = NULL\n  if (!arg %in% names(solution_call$args)) {\n    index = as.integer(substr(arg, 3, nchar(arg)))\n    if (substr(arg, 1, 2) == \"..\" &\n        index %in% seq_along(solution_call$args[[\"...\"]])) {\n      arg <- \"...\"\n    } else {\n      stop(\" Make sure that the arguments you specify are actually specified\",\n           \" by the corresponding function call in the solution code.\")\n    }\n  }\n\n  # Check if the function is called with the right arg\n  check_that(is_true(arg %in% names(student_call$args)), feedback = arg_state$details)\n  if (!is.null(index)) {\n    check_that(is_true(index %in% seq_along(student_call$args[[\"...\"]])), feedback = arg_state$details)\n  }\n\n  sol_arg = solution_call$args[[arg]]\n  stu_arg = student_call$args[[arg]]\n  if (!is.null(index)) {\n    sol_arg = sol_arg[[index]]\n    stu_arg = stu_arg[[index]]\n  }\n\n  arg_state$set(solution_arg = sol_arg)\n  arg_state$set(solution_pd = sol_arg$pd)\n  arg_state$set(solution_code = deparse(sol_arg$expr))\n  arg_state$set(student_arg = stu_arg)\n  arg_state$set(student_pd = stu_arg$pd)\n  arg_state$set(student_code = deparse(stu_arg$expr))\n  arg_state$set_details(case = \"correct\",\n                        message = NULL)\n\n  return(arg_state)\n}\n\n\n#' @rdname check_function\n#' @export\ncheck_equal.ArgumentState <- function(state, incorrect_msg = NULL, eval = TRUE, eq_condition = \"equivalent\", eq_fun = NULL, append = TRUE, ...) {\n  assert_state(state)\n  solution_arg <- state$get(\"solution_arg\")\n  student_arg <- state$get(\"student_arg\")\n\n  state$add_details(type = \"argument\",\n                    case = \"equal\",\n                    eval = eval,\n                    eq_condition = eq_condition,\n                    message = incorrect_msg,\n                    pd = student_arg$pd,\n                    append = append)\n\n  # Evaluate the solution argument and see if no error\n  solution_obj <- eval_argument(solution_arg,\n                                eval = eval,\n                                env = state$get(\"solution_env\"))\n\n  if (isTRUE(try(all.equal(solution_obj, tryerrorstring), silent = TRUE))) {\n    stop(\"check_equal() found an argument that causes an error when evaluated.\")\n  }\n\n  if (is.null(eq_fun)) {\n    eq_fun <- function(x, y) is_equal(x, y, eq_condition)\n  }\n\n  # Evaluate the student argument\n  student_obj <- eval_argument(student_arg,\n                               eval = eval,\n                               env = state$get(\"student_env\"))\n\n  state$set_details(student = student_obj,\n                    solution = solution_obj,\n                    is_dots = is_dots(student_arg))\n\n  check_that(is_true(eq_fun(student_obj, solution_obj)), feedback = state$details)\n\n  return(state)\n}\n\ntryerrorstring <- \"try-error-in-evaluation\"\n\neval_argument <- function(arg, eval, env) {\n  if (is_dots(arg)) {\n    return(lapply(arg, eval_argument, eval, env))\n  }\n  if (eval) {\n    obj <- try(eval(arg$expr, envir = env), silent = TRUE)\n    if (inherits(obj, \"try-error\")) {\n      obj <- tryerrorstring\n    }\n  } else {\n    obj <- stringify(arg$expr)\n  }\n  return(obj)\n}\n\nis_dots <- function(arg) {\n  is.list(arg) && ! \"expr\" %in% names(arg)\n}\n\nstringify <- function(arg) {\n  x <- deparse(arg)\n  x <- gsub(\"\\\\s|;\", \"\", x)\n  x <- gsub(\"'\", \"\\\"\", x)\n  x <- gsub(\"FALSE\", \"F\", x)\n  x <- gsub(\"TRUE\", \"T\", x)\n  return(x)\n}\n\n## Deprecated functions\n\ntest_function <- function(name,\n                          args = NULL,\n                          index = 1,\n                          eval = TRUE,\n                          eq_condition = \"equivalent\",\n                          not_called_msg = NULL,\n                          args_not_specified_msg = NULL,\n                          incorrect_msg = NULL) {\n  fail_if_v2_only()\n  n_args <- length(args)\n  if (!is.null(args_not_specified_msg) && length(args_not_specified_msg) < n_args) {\n    args_not_specified_msg <- rep(args_not_specified_msg[1], n_args)\n  }\n  if (!is.null(incorrect_msg) && length(incorrect_msg) < n_args) {\n    incorrect_msg <- rep(incorrect_msg[1], n_args)\n  }\n  eval <- rep(eval, length.out = n_args)\n  eq_condition <- rep(eq_condition, length.out = n_args)\n\n  fun_state <- check_function(ex(), name, index = index,\n                              not_called_msg = not_called_msg,\n                              append = is.null(not_called_msg))\n  for (i in seq_along(args)) {\n    arg_state <- check_arg(fun_state,\n                           arg = args[i],\n                           arg_not_specified_msg = args_not_specified_msg[i],\n                           append = is.null(args_not_specified_msg))\n    if (!is.na(eval[i])) {\n      check_equal(arg_state,\n                  incorrect_msg = incorrect_msg[i],\n                  eval = eval[i],\n                  eq_condition = eq_condition[i],\n                  append = is.null(incorrect_msg[i]))\n    }\n  }\n}\n\ntest_function_v2 <- test_function\n",
  "check-ggplot.R": "#' Test ggplot call\n#'\n#' @param state the state to start from\n#' @param index which call to check\n#' @param all_fail_msg Message if all fails\n#' \n#' @param check_data Whether or not to check data layer\n#' @param data_fail_msg Message in case data layer fails\n#' \n#' @param check_aes Whether or not to check aes layer\n#' @param aes_fail_msg Message in case aes layer fails\n#' @param exact_aes Should the aesthetics be exact?\n#' \n#' @param check_geom Whether or not to check geom layer\n#' @param geom_fail_msg Message in case geom layer fails\n#' @param exact_geom Should the geoms be exact?\n#' @param check_geom_params Should the geom parameters be checked?\n#' \n#' @param check_facet Whether or not to check facet layer\n#' @param facet_fail_msg Message in case facet layer fails\n#' @param check_scale Whether or not to check scale layer\n#' \n#' @param scale_fail_msg Message in case scale layer fails\n#' @param exact_scale Whether or not scales should be defined exactly\n#' \n#' @param check_coord Whether or not to check coord layer\n#' @param coord_fail_msg Message in case coord layer fails\n#' @param exact_coord Whether or not coords should be defined exactly\n#' \n#' @param check_stat Whether or not to check stat layer\n#' @param stat_fail_msg Message in case stat layer fails\n#' @param exact_stat Whether or not stats should be defined exactly\n#' \n#' @param check_extra Whether to check extra stuff\n#' @param extra_fail_msg Message in case extra stuff fails\n#' @param exact_extra Whether or not extra info should be exactly specified.\n#' \n#' @param check Which layers to check\n#' \n#' @keywords internal\ncheck_ggplot <- function(state,\n                         index = 1,\n                         all_fail_msg = NULL,\n                         check_data = TRUE, data_fail_msg = NULL,\n                         check_aes = TRUE, aes_fail_msg = NULL, exact_aes = FALSE,\n                         check_geom = TRUE, geom_fail_msg = NULL, exact_geom = FALSE, check_geom_params = NULL,\n                         check_facet = TRUE, facet_fail_msg = NULL,\n                         check_scale = TRUE, scale_fail_msg = NULL, exact_scale = FALSE,\n                         check_coord = TRUE, coord_fail_msg = NULL, exact_coord = FALSE,\n                         check_stat = TRUE, stat_fail_msg = NULL, exact_stat = FALSE,\n                         check_extra = NULL, extra_fail_msg = NULL, exact_extra = NULL,\n                         check = NULL) {\n  assert_state(state)\n  fail_if_v2_only(err_msg)\n  student_env <- state$get(\"student_env\")\n  solution_env <- state$get(\"solution_env\")\n  student_code <- state$get(\"student_code\")\n  solution_code <- state$get(\"solution_code\")\n  predefined_code <- state$get(\"pec\")\n  \n  layers <- c(\"data\", \"aes\", \"geom\", \"facet\", \"scale\", \"coord\", \"stat\")\n  \n  sol_ggplot_info <- get_ggplot_solution_info(solution_code, predefined_code, solution_env)\n  sol_ggplot_objects <- sol_ggplot_info$objects\n  sol_ggplot_commands <- sol_ggplot_info$commands\n  \n  if (!is.null(check)) {\n    for (layer in layers) {\n      if (layer %in% check) {\n        assign(paste0(\"check_\", layer), TRUE)\n      } else {\n        assign(paste0(\"check_\", layer), FALSE)\n      }\n    }\n  }\n  \n  if (!is.null(all_fail_msg)) {\n    for (layer in layers) {\n      assign(paste0(layer, \"_fail_msg\"), all_fail_msg)\n    }\n    extra_fail_msg = all_fail_msg\n  }\n  \n  sol_selected <- try(sol_ggplot_objects[[index]], silent = TRUE)\n  if (inherits(sol_selected, \"try-error\")) {\n    stop(sprintf(\"Could not find ggplot command %d in your solution environment.\", index))\n  }\n  \n  stud_ggplot_info <- get_ggplot_student_info(student_code, predefined_code, student_env)\n  stud_ggplot_objects <- stud_ggplot_info$objects\n  stud_ggplot_commands <- stud_ggplot_info$commands\n  len <- length(stud_ggplot_objects)\n  \n  if (len < index) {\n    check_that(failure(), feedback = \"You didn't define enough `ggplot` commands.\")\n  }\n  \n  feedback <- sprintf(\"In your %s `ggplot` command,\", get_ord(index))\n  \n  stud_selected <- stud_ggplot_objects[[index]]\n  \n  check_that(is_false(inherits(stud_selected, \"try-error\")), feedback = paste(feedback, \"you got an error. Make sure you use the correct `ggplot` syntax. Have another look at the instructions.\"))\n  \n  sol_selected_command <- sol_ggplot_commands[[index]]\n  stud_selected_command <- stud_ggplot_commands[[index]]\n  \n  if (check_data) {\n    # Check the data\n    test_data_layer(list(base = sol_selected$data), list(base = stud_selected$data), feedback, data_fail_msg)\n  }\n  \n  if (check_aes) {\n    # Check the mapping\n    test_aes_layer(list(base = sol_selected$mapping), list(base = stud_selected$mapping), feedback, aes_fail_msg, exact_aes)\n  }\n  \n  if (check_geom) {\n    # Check the geom layer\n    test_geom_layer(sol_selected_command, stud_selected_command, sol_selected$layers, stud_selected$layers, feedback, geom_fail_msg, exact_geom, check_geom_params)\n  }\n  \n  if (check_stat) {\n    # Check the stat layer\n    test_stat_layer(sol_selected_command, stud_selected_command, feedback, stat_fail_msg, exact_coord, student_env, solution_env)\n  }\n  \n  if (check_facet) {\n    # Check the facet layer\n    test_facet_layer(sol_selected$facet, stud_selected$facet, feedback, facet_fail_msg)\n  }\n  \n  if (check_scale) {\n    # Check the scale layer\n    test_scale_layer(sol_selected_command, stud_selected_command, feedback, scale_fail_msg, exact_scale, student_env, solution_env)\n  }\n  \n  if (check_coord) {\n    # Check the coord layer\n    test_coord_layer(sol_selected_command, stud_selected_command, feedback, coord_fail_msg, exact_coord, student_env, solution_env)\n  }\n  \n  if (!is.null(check_extra)) {\n    # Check extra layers\n    for (i in 1:length(check_extra)) {\n      extra <- check_extra[i]\n      \n      fail_msg <- try(extra_fail_msg[[i]], silent = TRUE)\n      if (inherits(fail_msg, \"try-error\")) {\n        fail_msg <- NULL\n      }\n      \n      exact <- try(exact_extra[i], silent = TRUE)\n      if (inherits(exact, \"try-error\")) {\n        exact <- FALSE\n      } else if (!is.logical(exact)) {\n        exact <- FALSE\n      }\n      \n      test_generic_part(type = extra, sol_selected_command, stud_selected_command, feedback, fail_msg, exact,\n                        student_env, solution_env)\n    }\n  }\n\n  return(state)\n}\n\ntest_ggplot <- function(index = 1,\n                        all_fail_msg = NULL,\n                        check_data = TRUE, data_fail_msg = NULL,\n                        check_aes = TRUE, aes_fail_msg = NULL, exact_aes = FALSE,\n                        check_geom = TRUE, geom_fail_msg = NULL, exact_geom = FALSE, check_geom_params = NULL,\n                        check_facet = TRUE, facet_fail_msg = NULL,\n                        check_scale = TRUE, scale_fail_msg = NULL, exact_scale = FALSE,\n                        check_coord = TRUE, coord_fail_msg = NULL, exact_coord = FALSE,\n                        check_stat = TRUE, stat_fail_msg = NULL, exact_stat = FALSE,\n                        check_extra = NULL, extra_fail_msg = NULL, exact_extra = NULL,\n                        check = NULL) {\n  fail_if_v2_only(err_msg)\n  ex() %>% check_ggplot(index = index,\n                        all_fail_msg = all_fail_msg,\n                        check_data = check_data, data_fail_msg = data_fail_msg,\n                        check_aes = check_aes, aes_fail_msg = aes_fail_msg, exact_aes = exact_aes,\n                        check_geom = check_geom, geom_fail_msg = geom_fail_msg, exact_geom = exact_geom, check_geom_params = check_geom_params,\n                        check_facet = check_facet, facet_fail_msg = facet_fail_msg,\n                        check_scale = check_scale, scale_fail_msg = scale_fail_msg, exact_scale = exact_scale,\n                        check_coord = check_coord, coord_fail_msg = coord_fail_msg, exact_coord = exact_coord,\n                        check_stat = check_stat, stat_fail_msg = stat_fail_msg, exact_stat = exact_stat,\n                        check_extra = check_extra, extra_fail_msg = extra_fail_msg, exact_extra = exact_extra,\n                        check = check)\n}\n\ntest_data_layer <- function(sol_data, stud_data, feedback, data_fail_msg) {\n  if (!is.null(data_fail_msg)) {\n    feedback_msg <- data_fail_msg\n  } else {\n    feedback_msg <- paste(feedback, \"you didn't get the data layer right.\")\n  }\n  \n  check_that(is_equal(sol_data$base, stud_data$base), feedback = feedback_msg)\n}\n\ntest_aes_layer <- function(sol_mapping, stud_mapping, feedback, aes_fail_msg, exact_aes) {\n  for (map in names(sol_mapping$base)) {\n    if (!is.null(aes_fail_msg)) {\n      feedback_msg <- rep_len(aes_fail_msg, 3)\n    } else {\n      feedback_msg <- c(paste0(feedback, \" have you mapped something on the `\", map, \"` aesthetic?\"),\n                        paste0(feedback, \" have you mapped `\", sol_mapping$base[map] ,\"` on the `\", map, \"` aesthetic? Instead, you got `\", stud_mapping$base[map], \"`.\"),\n                        paste0(feedback, \" have you mapped exactly what is asked on the aesthetics layer, no more and no less?\"))\n    }\n    \n    check_that(is_false(is.null(stud_mapping$base[map][[1]])), feedback = feedback_msg[1])\n    check_that(is_equal(stud_mapping$base[map], sol_mapping$base[map]), feedback = feedback_msg[2])\n    if (exact_aes) {\n      check_that(is_equal(length(stud_mapping), length(sol_mapping)), feedback = feedback_msg[3])\n    }\n  }\n}\n\n#' @importFrom stats na.omit\ntest_geom_layer <- function(sol_command, stud_command, sol_layers, stud_layers, feedback, geom_fail_msg, exact_geom, check_geom_params) {\n  nb_sol_layers <- length(sol_layers)\n  \n  exact_geom <- rep_len(exact_geom, nb_sol_layers)\n  \n  sol_geom_parts <- extract_parts(sol_command, \"stat|geom_\")\n  stud_geom_parts <- extract_parts(stud_command, \"stat|geom_\")\n  \n  if (!(nb_sol_layers > 0)) {\n    return()\n  }\n  \n  if (!is.null(geom_fail_msg)) {\n    geom_fail_msg <- rep_len(geom_fail_msg, 5)\n  }\n  \n  for (i in 1:nb_sol_layers) {\n    sol_layer <- sol_layers[[i]]\n    sol_geom_part <- sol_geom_parts[[i]]\n    \n    found_geom_name <- FALSE\n    found_geom_with_params <- FALSE\n    found_geom_with_exact_params <- FALSE\n    found_geom_with_correct_position <- FALSE\n    \n    sol_params <- get_geom_params(sol_layer)\n    if (!is.null(check_geom_params)) {\n      sol_params <- sol_params[check_geom_params]\n      sol_params <- sol_params[na.omit(names(sol_params))]\n    }\n    \n    sol_position <- extract_type_from_object(sol_layer$position)\n    \n    \n    nb_stud_layers <- length(stud_layers)\n    if (nb_stud_layers > 0) {\n      for (j in 1:nb_stud_layers) {\n        stud_layer <- stud_layers[[j]]\n        stud_geom_part <- stud_geom_parts[[j]]\n        \n        sol_geom_type <- extract_type_from_object(sol_layer$geom)\n        stud_geom_type <- extract_type_from_object(stud_layer$geom)\n        if (sol_geom_type == stud_geom_type) {\n          found_geom_name <- TRUE\n          found_params <- TRUE\n          \n          stud_params <- get_geom_params(stud_layer)\n          if (!is.null(check_geom_params)) {\n            stud_params <- stud_params[check_geom_params]\n            stud_params <- stud_params[na.omit(names(stud_params))]\n          }\n          \n          stud_position <- extract_type_from_object(stud_layer$position)\n          \n          for (sol_param in names(sol_params)) {\n            if (!(sol_param %in% names(stud_params))) {\n              found_params <- FALSE\n              break\n            } else {\n              sol_value <- sol_params[[sol_param]]\n              stud_value <- stud_params[[sol_param]]\n              \n              if (!is_equal(sol_value, stud_value)) {\n                found_params <- FALSE\n                break\n              }\n            }\n          }\n          \n          if (found_params) {\n            found_geom_with_params <- TRUE\n          }\n          \n          if (found_geom_with_params && (!exact_geom[i] || length(sol_params) == length(stud_params))) {\n            found_geom_with_exact_params <- TRUE\n          }\n          \n          if (found_geom_with_exact_params && compare_positions(sol_layer, stud_layer)) {\n            found_geom_with_correct_position <- TRUE\n          }\n          \n          if (found_geom_with_correct_position) {\n            stud_layers[[j]] <- NULL\n            stud_geom_parts[[j]] <- NULL\n            break\n          }\n        }\n        \n      }\n    }\n    \n    if (!is.null(geom_fail_msg)) {\n      feedback_msg <- geom_fail_msg\n    } else {\n      geom_base_feedback <- paste0(feedback, \" have you correctly added a `\", as.character(sol_geom_part[[1]]),\"()` layer\")\n      if (!is.null(check_geom_params)) {\n        filtered_geom_params <- names(sol_params)\n      } else {\n        filtered_geom_params <- names(filter_standard_geom_params(as.character(sol_geom_part[[1]]), sol_params))\n      }\n      param_strings <- vapply(filtered_geom_params, \n                              function(x) {\n                                gen_fb <- \"\"\n                                if (isTRUE(attr(sol_params[[x]], \"aes\"))) {\n                                  attr(sol_params[[x]], \"aes\") <- NULL\n                                  gen_fb <- \"aesthetic \"\n                                }\n                                return(paste0(gen_fb,\"`\", x, \"` set to `\", paste0(deparse(sol_params[[x]]), collapse = \" \"), \"`\"))\n                              }, character(1))\n      nb_param_strings <- length(param_strings)\n      if (nb_param_strings > 1) {\n        param_feedback <- paste0(paste(param_strings[1:(nb_param_strings - 1)], collapse = \", \"), \" and \", param_strings[nb_param_strings])\n      } else {\n        param_feedback <- param_strings\n      }\n      feedback_msg <- c(paste0(geom_base_feedback, \" with a `+` operator?\"),\n                        paste0(geom_base_feedback, \" with \", param_feedback, \"?\"),\n                        paste0(geom_base_feedback, \" with \", param_feedback, \"?\", \" It seems like you have defined too much attributes or aesthetics for this geom.\"),\n                        paste0(geom_base_feedback, \" with the `position` set correctly? Have another look at the instructions.\"))\n      \n    }\n    \n    check_that(is_true(found_geom_name), feedback = feedback_msg[1])\n    check_that(is_true(found_geom_with_params), feedback = feedback_msg[2])\n    check_that(is_true(found_geom_with_exact_params), feedback = feedback_msg[3])\n    check_that(is_true(found_geom_with_correct_position), feedback = feedback_msg[4])\n  }\n  \n  if (isTRUE(exact_geom)) {\n    if (!is.null(geom_fail_msg)) {\n      feedback_msg <- geom_fail_msg[5]\n    } else {\n      feedback_msg <- paste0(feedback, \" have you added only the geom layers that are asked for? Nothing more.\")\n    }\n    check_that(is_equal(length(stud_layers), 0), feedback = feedback_msg)\n  }\n}\n\ntest_facet_layer <- function(sol_facet, stud_facet, feedback, facet_fail_msg) {\n\n  sol_type <- class(sol_facet)[1]\n  stud_type <- class(stud_facet)[1]\n\n  if (sol_type == \"FacetGrid\") {\n\n    sol_cols <- names(sol_facet$params$cols)\n    sol_rows <- names(sol_facet$params$rows)\n\n    if (!is.null(facet_fail_msg)) {\n      feedback_msg <- rep_len(facet_fail_msg, 3)\n    } else {\n      form_left <- ifelse(length(sol_rows > 0), paste(sol_rows, collapse = \"+\"), \".\")\n      form_right <- ifelse(length(sol_cols > 0), paste(sol_cols, collapse = \"+\"), \".\")\n      form_facet <- paste0(form_left, \" ~ \", form_right)\n      feedback_incorrect <- paste0(feedback, \" did you set the correct formula for the facet: `\", form_facet, \"`?\")\n      feedback_msg <- c(paste0(feedback, \" did you add the correct facet, `facet_\", sol_type, \"()`, using the `+` operator?\"),\n                        feedback_incorrect,\n                        feedback_incorrect)\n    }\n\n    check_that(is_equal(sol_type, stud_type), feedback = feedback_msg[1])\n\n    stud_cols <- names(stud_facet$params$cols)\n    check_that(is_gte(length(base::intersect(sol_cols, stud_cols)), length(sol_cols)), feedback = feedback_msg[2])\n\n    stud_rows <- names(stud_facet$params$rows)\n    check_that(is_gte(length(base::intersect(sol_rows, stud_rows)), length(sol_rows)), feedback = feedback_msg[3])\n  }\n\n  if (sol_type == \"FacetWrap\") {\n    \n    sol_facets <- names(sol_facet$params$facets)\n\n    if (!is.null(facet_fail_msg)) {\n      feedback_msg <- rep_len(facet_fail_msg, 2)\n    } else {\n      feedback_msg <- c(paste0(feedback, \" did you add the correct facet, `facet_\", sol_type, \"()`, using the `+` operator?\"),\n                        paste0(feedback, \" did you correctly specify the facets: `\", paste(sol_facets, collapse = \"+\"), \"`?\"))\n    }\n\n    check_that(is_equal(sol_type, stud_type), feedback = feedback_msg[1])\n\n    stud_facets <- names(stud_facet$params$facets)\n    check_that(is_gte(length(base::intersect(sol_facets, stud_facets)), length(sol_facets)), feedback = feedback_msg[2])\n  }\n}\n\ntest_scale_layer <- function(sol_command, stud_command, feedback, scale_fail_msg, exact_scale,\n                             student_env, solution_env) {\n  test_generic_part(type = \"scale_\", sol_command, stud_command, feedback, scale_fail_msg, exact_scale,\n                    student_env, solution_env)\n}\n\ntest_coord_layer <- function(sol_command, stud_command, feedback, coord_fail_msg, exact_coord,\n                             student_env, solution_env) {\n  test_generic_part(type = \"coord_\", sol_command, stud_command, feedback, coord_fail_msg, exact_coord,\n                    student_env, solution_env)\n}\n\ntest_stat_layer <- function(sol_command, stud_command, feedback, stat_fail_msg, exact_stat,\n                            student_env, solution_env) {\n  test_generic_part(type = \"stat_\", sol_command, stud_command, feedback, stat_fail_msg, exact_stat,\n                    student_env, solution_env)\n}\n\ntest_generic_part <- function(type, sol_command, stud_command, feedback, fail_msg, exact,\n                              student_env, solution_env) {\n\n  sol_parts <- extract_parts(sol_command, type)\n  stud_parts <- extract_parts(stud_command, type)\n  \n  nb_sol_parts <- length(sol_parts)\n  \n  if (!(nb_sol_parts > 0)) {\n    return()\n  }\n  \n  exact <- rep_len(exact, nb_sol_parts)\n  \n  for (i in 1:nb_sol_parts) {\n    sol_part <- sol_parts[[i]]\n    if (is.call(sol_part)) {\n      sol_func_name <- sol_part[[1]]\n    } else {\n      sol_func_name <- sol_part\n    }\n    \n    found_name <- FALSE\n    found_with_params <- FALSE\n    found_with_exact_params <- FALSE\n    \n    sol_params <- extract_params(sol_part)\n    \n    nb_stud_parts <- length(stud_parts)\n    if (nb_stud_parts > 0) {\n      for (j in 1:nb_stud_parts) {\n        stud_part <- stud_parts[[j]]\n        if (is.call(stud_part)) {\n          stud_func_name <- stud_part[[1]]\n        } else {\n          stud_func_name <- stud_part\n        }\n        \n        if (map_synonyms(stud_func_name) == map_synonyms(sol_func_name)) {\n          found_name <- TRUE\n          found_params <- TRUE\n          \n          stud_params <- extract_params(stud_part)\n          \n          for (sol_param in names(sol_params)) {\n            if (!(sol_param %in% names(stud_params))) {\n              found_params <- FALSE\n              break\n            } else {\n              sol_value <- sol_params[[sol_param]]\n              stud_value <- stud_params[[sol_param]]\n              \n              eval_sol <- without_args(eval(sol_value, envir = solution_env))\n              eval_stud <- without_args(try(eval(stud_value, envir = student_env), silent = TRUE))\n              if (inherits(eval_stud, \"try-error\") ||\n                  !is_equal(eval_sol, eval_stud)) {\n                found_params <- FALSE\n                break\n              }\n            }\n          }\n          \n          if (found_params) {\n            found_with_params <- TRUE\n          }\n          \n          if (found_with_params && (!exact[i] || length(sol_params) == length(stud_params))) {\n            found_with_exact_params <- TRUE\n          }\n          \n          if (found_with_exact_params) {\n            stud_parts[[j]] <- NULL\n            break\n          }\n        }\n        \n      }\n    }\n    \n    if (!is.null(fail_msg)) {\n      feedback_msg <- rep_len(fail_msg, 3)\n    } else {\n      base_feedback <- paste0(feedback, \" have you correctly added a `\", sol_func_name,\"()` layer\")\n      param_strings <- vapply(names(sol_params), \n                              function(x) {\n                                if (isTRUE(attr(sol_params[[x]], \"dot\"))) {\n                                  attr(sol_params[[x]], \"dot\") <- NULL\n                                  return(paste0(\"the \", x, \" set to `\", deparse(sol_params[[x]]), \"`\")) \n                                } else {\n                                  return(paste0(\"`\", x, \"` set to `\", deparse(sol_params[[x]]), \"`\"))\n                                }\n                              }, character(1))\n      nb_param_strings <- length(param_strings)\n      if (nb_param_strings > 1) {\n        param_feedback <- paste0(paste(param_strings[1:(nb_param_strings - 1)], collapse = \", \"), \" and \", param_strings[nb_param_strings])\n      } else {\n        param_feedback <- param_strings\n      }\n      feedback_msg <- c(paste0(base_feedback, \" with a `+` operator?\"),\n                        paste0(base_feedback, \" with \", param_feedback, \"?\"),\n                        paste0(base_feedback, \" with \", param_feedback, \"?\", \" It seems like you have defined too much attributes.\"))\n      \n    }\n    \n    check_that(is_true(found_name), feedback = feedback_msg[1])\n    check_that(is_true(found_with_params), feedback = feedback_msg[2])\n    check_that(is_true(found_with_exact_params), feedback = feedback_msg[3])\n  }\n}\n\nwithout_args <- function(x) {\n  copy <- x\n  for (a in names(attributes(copy))) {\n    attr(copy, a) <- NULL\n  }\n  return(copy)\n}\n\n#' @importFrom utils argsAnywhere\nextract_params <- function(command) {\n  if (!is.call(command)) {\n    return(NULL)\n  }\n  func_def <- try(argsAnywhere(as.character(command[[1]])), silent = TRUE)\n  if (!inherits(func_def, \"try-error\")) {\n    param_list <- as.list(match.call(func_def, command))[-1]\n    if (!length(param_list) > 0) {\n      return(NULL)\n    }\n    param_names <- names(param_list)\n    if (is.null(param_names)) {\n      for (i in 1:length(param_list)) {\n        attr(param_list[[i]], \"dot\") <- TRUE\n        param_names[i] <- paste(get_ord(i), \"argument\")\n      }\n    } else {\n      for (i in 1:length(param_names)) {\n        if (is_equal(param_names[i], \"\")) {\n          attr(param_list[[i]], \"dot\") <- TRUE\n          param_names[i] <- paste(get_ord(i), \"argument\")\n        }\n      }\n    }\n    names(param_list) <- param_names\n    return(param_list)\n  } else {\n    return(NULL)\n  }\n}\n\nextract_parts <- function(command, type) {\n  if (is.name(command)) {\n    if (grepl(paste0(\"^\", type), command)) {\n      return(list(command))\n    } else {\n      return(list())\n    }\n  } else if (command[[1]] == \"+\") {\n    return(c(extract_parts(command[[2]], type), extract_parts(command[[3]], type)))\n  } else if (is.call(command)) {\n    if (grepl(paste0(\"^\", type), command[[1]])) {\n      return(list(command))\n    } else {\n      return(list())\n    }\n  } else {\n    return(list())\n  }\n}\n\nextract_type_from_object <- function(object) {\n  return(sub(\"^_\", \"\", tolower(gsub(\"([A-Z])\", \"_\\\\1\", class(object)[1]))))\n}\n\ncompare_positions <- function(sol_layer, stud_layer) {\n   sol_position <- sol_layer$position\n   stud_position <- stud_layer$position\n\n   return(is_equal(sol_position, stud_position))\n}\n\nget_geom_params <- function(geom_layer) {\n  params <- geom_layer$geom_params\n  stat_params <- geom_layer$stat_params\n  params[names(stat_params)] <- stat_params\n  mapping_params <- lapply(geom_layer$mapping, function(x) structure(x, aes = TRUE))\n  params[names(mapping_params)] <- mapping_params\n  aes_params <- geom_layer$aes_params\n  params[names(aes_params)] <- aes_params\n  return(params)\n}\n\nfilter_standard_geom_params <- function(geom_call, params) {\n  standard_layer <- eval(call(geom_call))\n  standard_params <- get_geom_params(standard_layer)\n  ov <- base::intersect(names(params), names(standard_params))\n  eq <- mapply(is_equal, standard_params[ov], params[ov])\n  if (any(eq)) {\n    params[names(eq[eq])] <- NULL\n  } \n  return(params)\n}\n\nget_ggplot_solution_info <- function(code, predefined_code, envir) { \n  saved_solution_code <- tw$get(\"saved_solution_code\")\n  if (is.null(saved_solution_code)) saved_solution_code <- \"\"\n  saved_solution_ggplot_info <- tw$get(\"saved_solution_ggplot_info\")\n  \n  if (code != saved_solution_code || is.null(saved_solution_ggplot_info)) {\n    ggplot_info <- get_ggplot_info(code, predefined_code, envir)\n    tw$set(saved_solution_code = code)\n    tw$set(saved_solution_ggplot_info = ggplot_info)\n  }\n  return(tw$get(\"saved_solution_ggplot_info\"))\n}\n\nget_ggplot_student_info <- function(code, predefined_code, envir) {\n  saved_student_code <- tw$get(\"saved_student_code\")\n  if (is.null(saved_student_code)) saved_student_code <- \"\"\n  saved_student_ggplot_info <- tw$get(\"saved_student_ggplot_info\")\n  \n  if (code != saved_student_code || is.null(saved_student_ggplot_info)) {\n    ggplot_info <- get_ggplot_info(code, predefined_code, envir)\n    tw$set(saved_student_code = code)\n    tw$set(saved_student_ggplot_info = ggplot_info)\n  }\n  return(tw$get(\"saved_student_ggplot_info\"))\n}\n\nget_ggplot_info <- function(code, predefined_code, envir) { \n  ggplot_env <- new.env()\n  commands <- get_ggplot_commands(code, predefined_code, ggplot_env)\n  return(list(commands = commands,\n              objects = lapply(commands, function(x) try(eval(x, envir), silent = TRUE))))\n}\n\nget_ggplot_commands <- function(code, predefined_code, envir) {\n  pre_parsed <- try(parse(text = predefined_code), silent = TRUE)\n  parsed <- try(parse(text = code), silent = TRUE)\n  \n  if (inherits(pre_parsed, \"try-error\") || inherits(parsed, \"try-error\")) {\n    return(list())\n  }\n  \n  lapply(pre_parsed, extract_ggplot_command, envir = envir)\n  \n  extracted <- lapply(parsed, extract_ggplot_command, envir = envir)\n  return(extracted[!as.logical(vapply(extracted, is.null, logical(1)))])\n}\n\nextract_ggplot_command <- function(code, envir) {\n  if (any(grepl(\"%>%\", deparse(code), fixed = TRUE))) {\n    code <- unpipe(code)\n  }\n\n  if (is_ggplot_command(code, envir)) {\n    return(replace_saved_ggplot_commands(code, envir))\n  } else if (is.name(code)) {\n    return(NULL)\n  } else if (code[[1]] == \"=\" || code[[1]] == \"<-\") {\n    code_is_ggplot_command <- is_ggplot_command(code[[3]], envir)\n    if (code_is_ggplot_command || is_geom_command(code[[3]], envir)) {\n      extract_def <- replace_saved_ggplot_commands(code[[3]], envir)\n      assign(as.character(code[[2]]), extract_def, envir = envir)\n      if (isTRUE(code_is_ggplot_command)) {\n        return(extract_def)\n      } else {\n        return(NULL)\n      }\n    } else {\n      return(NULL)\n    }\n  } else {\n    return(NULL)\n  }\n}\n\nreplace_saved_ggplot_commands <- function(code, envir) {\n  len <- length(code)\n  if (len > 1) {\n    for (i in 1:len) {\n      if (length(code[[i]]) > 1 && code[[i]][[1]] == \"+\") {\n        code[[i]] = replace_saved_ggplot_commands(code[[i]], envir)\n      } else if (exists(as.character(code[[i]]), envir = envir, inherits = FALSE)) {\n        code[[i]] = get(as.character(code[[i]]), envir = envir, inherits = FALSE)  \n      }\n    }\n  } else {\n    if (exists(as.character(code), envir = envir, inherits = FALSE)) {\n      code =  get(as.character(code), envir = envir, inherits = FALSE) \n    }\n  }\n  return(code)\n}\n\nis_ggplot_command <- function(code, envir) {\n  if (is.null(code)) {\n    return(FALSE)\n  } else if (is.name(code)) {\n    get_command <- try(get(as.character(code), envir = envir, inherits = FALSE))\n    return(ifelse(inherits(get_command, \"try-error\"), FALSE, is_ggplot_command(get_command, envir)))\n  } else if (code[[1]] == \"ggplot\") {\n    return(TRUE)\n  } else if (code[[1]] == \"+\") {\n    return(is_ggplot_command(code[[2]], envir))\n  } else {\n    return(FALSE)\n  }\n}\n\nis_geom_command <- function(code, envir) {\n  if (is.name(code)) {\n    get_command <- try(get(as.character(code), envir = envir, inherits = FALSE))\n    return(ifelse(inherits(get_command, \"try-error\"), FALSE, is_geom_command(get_command, envir)))\n  } else {\n    return(isTRUE(grepl(\"^geom_\", code[[1]])))\n  }\n}\n\nmap_synonyms <- function(fun) {\n  gsub(\"scale_colour_\", \"scale_color_\", fun, fixed = TRUE)\n}\n\nerr_msg <- \"test_ggplot() and check_ggplot() should not be used anymore. Use check_function() instead. Visit the glossary for examples.\"\n",
  "check-library-function.R": "#' Check whether the library function was called correctly\n#' \n#' Convenience function to test in a very hacky way whether \n#' the library function was called correctly in its most simple form.\n#' There is support for the different ways to call the library function\n#' \n#' @param state state to start from\n#' @param package package name for which the library()\n#' function should've been called\n#' @param not_called_msg optional feedback message in case the library\n#' function wasn't called a single time\n#' @param incorrect_msg optional feedback message in case the library\n#' function wasn't called for the specified package.\n#' @inheritParams test_function\n#' \n#' @examples\n#' \\dontrun{\n#' # example solution\n#' library(ggvis)\n#' \n#' # sct to test whether ggvis was loaded\n#' ex() %>% check_library(\"ggvis\")\n#' }\n#' \n#' @export\ncheck_library <- function(state, package, not_called_msg = NULL, incorrect_msg = NULL) {\n  assert_state(state)\n  if(is.null(not_called_msg)) {\n    not_called_msg <- sprintf(\"Make sure to call the `library()` function to load the `%s` package.\", package)\n  }\n  \n  if(is.null(incorrect_msg)) {\n    incorrect_msg <- sprintf(\"Have you correctly called the `library()` function to load the `%s` package?\", package)\n  }\n  \n  state %>% check_code(regex = \"(library|require)\\\\(\", missing_msg = not_called_msg,\n                       append = is.null(not_called_msg), drop_comments = TRUE)\n  state %>% check_code(regex = sprintf(\"(library|require)\\\\s*\\\\(\\\\s*[\\\"']?%s[\\\"']?\\\\s*\\\\)\",package),\n                       missing_msg = incorrect_msg, append = is.null(incorrect_msg), drop_comments = TRUE)\n  return(state)\n}\n\ntest_library_function <- function(package,\n                          not_called_msg = NULL, \n                          incorrect_msg = NULL) {\n  fail_if_v2_only()\n  ex() %>% check_library(package, not_called_msg = not_called_msg, incorrect_msg = incorrect_msg)\n}\n",
  "check-logic.R": "#' Combine tests\n#'\n#' \\code{check_correct} checks whether a set of tests passes, and does\n#' additional, more precise tests if these tests fail. In addition to the state,\n#' it takes two code chunks; \\itemize{\\item{\\code{check_code}: specifies the\n#' code that checks on the (typically, final results of the) student's code.\n#' These tests are executed silently, without the reporter generating\n#' information for these.} \\item{\\code{diagnose_code}: Set of tests that gets\n#' executed if the tests in \\code{check_code} fail. These tests contain more\n#' detailed tests, to pinpoint the problem.} }\n#'\n#' \\code{check_correct} increases the flexibility for the student: if the tests\n#' in \\code{check_code} pass, the results of the tests in \\code{diagnose_code}\n#' are not considered. If you test for the end result in \\code{check_code}, and\n#' only do more rigorous testing in \\code{diagnose_code}, you can allow for\n#' multiple solutions to a challenge.\n#'\n#' Similarly, \\code{check_or} checks whether one of many test sets pass. That\n#' way, you can allow for multiple solutions.\n#'\n#' Both \\code{check_or} and \\code{check_correct} makes the state you feed it to\n#' its subtests available as \\code{.} (the dot), similar to how magrittr does\n#' it.\n#'\n#' @param state The state. Typically \\code{\\link{ex}} but can also be a\n#'   lower-level state if you're using nested \\code{check_or}s or\n#'   \\code{check_correct}s\n#' @param ... sets of tests. In the case of \\code{check_correct}, the first set\n#'   is the \\code{check_code}, the second set is the \\code{diagnose_code}. For\n#'   \\code{check_or}, an unrestricted number of sets of tests: only one of these\n#'   tests has to pass for the \\code{check_or} to pass.\n#'\n#' @examples\n#' \\dontrun{\n#' # Example 1 solution code\n#' x <- mean(1:3)\n#'\n#' # Example SCT\n#' ex() %>% check_correct(\n#'   check_object(., \"x\") %>% check_equal(),\n#'   check_fun(., \"mean\") %>% check_arg(\"x\") %>% check_equal()\n#' )\n#'\n#' # Following submissions will all be accepted:\n#' x <- mean(1:3)\n#' x <- 2\n#' x <- mean(-1:5)\n#'\n#' # Example 2 solution code\n#' # a <- 3; b <- 4\n#'\n#' # Example SCT\n#' ex() %>% check_or(\n#'   check_object(., 'a') %>% check_equal(),\n#'   check_object(., 'b') %>% check-equal()\n#' )\n#'\n#' # Following submissions will all be accepted:\n#' a <- 3; b <- 4\n#' a <- 3\n#' b <- 4\n#' }\n#'\n#' @rdname check_logic\n\n\n#' @name check_logic\n#' @export\ncheck_correct <- function(state, ...) {\n  if (nargs() == 3) {\n    # If three inputs, the first one must be a state\n    set_dot(state)\n    test_correct(..., v2_check = FALSE)\n  } else {\n    fail_if_v2_only(errmsg = 'check_correct() can only be used with a state as the first argument, e.g. ex() %>% check_correct(...).')\n    # Else, fall back on old behavior\n    input <- as.list(substitute(list(...)))\n    test_correct(substitute(state), input[[2]], sub = FALSE)\n  }\n}\n\n#' @name check_logic\n#' @export\ncheck_or <- function(state, ...) {\n  if (class(substitute(state)) == \"name\") {\n    # If something was piped in, it will be a . (class name, done by magrittr)\n    set_dot(state)\n    test_or(..., v2_check = FALSE)\n  } else {\n    fail_if_v2_only(errmsg = 'check_or() can only be used with a state as the first argument, e.g. ex() %>% check_or(...).')\n    # Else, fall back on previous behavior\n    tests <- as.list(substitute(list(...)))\n    tests[[1]] <- substitute(state)\n    do.call(test_or, c(tests))\n  }\n}\n\nset_dot <- function(x) {\n  assign(\".\", x, envir = tw$get(\"state\")$get(\"test_env\"))\n}\n\ntest_correct <- function(check_code, diagnose_code, sub = TRUE, v2_check = TRUE) {\n  force_diagnose <- ex()$get('force_diagnose')\n  if(v2_check) {\n    fail_if_v2_only(errmsg = 'test_correct() can no longer be used in SCTs. Use ex() %>% check_correct() instead.')\n  }\n  if(sub) {\n    check_code <- substitute(check_code)\n    diagnose_code <- substitute(diagnose_code)\n  }\n  check_res <- run_until_fail(check_code)\n  diagnose_res <- run_until_fail(diagnose_code)\n  if (check_res$correct && !force_diagnose) {\n    # all good\n  } else {\n    if (!diagnose_res$correct) {\n      check_that(failure(), feedback = diagnose_res$feedback)\n    } else if (!check_res$correct) {\n      check_that(failure(), feedback = check_res$feedback)\n    }\n  }\n  return(invisible(NULL))\n}\n\ntest_or <- function(..., incorrect_msg = NULL, choose_feedback = 1, v2_check = TRUE) {\n  if(v2_check) {\n    fail_if_v2_only(errmsg = 'test_or() can no longer be used in SCTs. Use ex() %>% check_or() instead.')\n  }\n  input <- as.list(substitute(list(...)))\n  input[[1]] <- NULL\n  \n  passes <- logical(length(input) )\n  feedback <- list()\n  \n  for (i in seq_along(input)) {\n    code <- input[[i]]\n    res <- run_until_fail(code)\n    passes[i] <- res$correct\n    feedback[[i]] <- res$feedback\n  }\n  \n  if (!any(passes)) {\n    if (is.null(incorrect_msg)) {\n      check_that(failure(), feedback = feedback[[choose_feedback]])\n    } else {\n      check_that(failure(), feedback = incorrect_msg)\n    }\n  }\n  return(invisible(NULL))\n}",
  "check-mc.R": "#' Test a multiple choice exercise\n#'\n#' This code expects the DM.result variable to be defined by the DataCamp frontend. \n#' There is need to define the success_msg seperately, since it is defined inside the function.\n#'\n#' @param state the state passed to it. Use \\code{ex()} at all times.\n#' @param correct number of the correct answer (or vector of numbers, if several options are fine)\n#' @param no_selection_msg feedback message in case the student did not select an answer.\n#' @param feedback_msgs vector of feedback messages for both the incorrect exercises as the correct exercise.\n#' Order the messages according to how they are listed in the instructions. For example, if there are four options,\n#' the second of which is correct, a vector of four feedback messages should be provided. The first message corresponds\n#' to feedback on the incorrect selection of the first option, the second message corresponds to the feedback message for\n#' the correct collection. The third and fourth messages correspond to feedback on the incorrect selection of the third and\n#' fourth option.\n#' \n#' @examples\n#' \\dontrun{\n#' # Example solution: second instruction correct out of three options.\n#' \n#' # Corresponding SCT:\n#' msg1 <- \"Not good, try again!\"\n#' msg2 <- \"Nice one!\"\n#' msg3 <- \"Not quite, give it another shot.\"\n#' ex() %>% check_mc(2, feedback_msgs = c(msg1, msg2, msg3))\n#' }\n#'\n#' @export\ncheck_mc <- function(state, correct, no_selection_msg = NULL, feedback_msgs = NULL) {\n  assert_state(state)\n  # see if DM.result exists\n  if (is.null(no_selection_msg)) {\n    no_selection_msg <- \"Please select one of the options!\"\n  }\n\n  check_that(is_true(exists(\"DM.result\", envir = state$get(\"student_env\"))), feedback = no_selection_msg)\n  result <- get(\"DM.result\", envir = state$get(\"student_env\"))\n\n  # see if result is correct\n  if (!is.null(feedback_msgs) && is.na(feedback_msgs[result])) {\n    stop(\"There is no feedback message available for this user input! Make sure you define enough feedback messages.\")\n  }\n\n  check_that(is_true(result %in% correct),\n             feedback = ifelse(is.null(feedback_msgs), \"Your answer is incorrect. Try again.\", feedback_msgs[result]))\n\n  success_msg(ifelse(is.null(feedback_msgs), \"Good job! Continue to the next exercise.\", feedback_msgs[correct]))\n}\n\ntest_mc <- function(correct, no_selection_msg = NULL, feedback_msgs = NULL) {\n  fail_if_v2_only()\n  ex() %>% check_mc(correct, no_selection_msg = no_selection_msg, feedback_msgs = feedback_msgs)\n}\n",
  "check-object.R": "#' Check R object existence and value\n#'\n#' Check whether a student defined a certain object (correctly)\n#'\n#' @param state the state to start from\n#' @param name name of the object to test.\n#' @param eq_condition character string indicating how to compare. See\n#'   \\code{\\link{is_equal}}.\n#' @param eq_fun optional argument to specify a custom equality function. The\n#'   function should take two arguments and always return a single boolean\n#'   value: \\code{TRUE} or \\code{FALSE}.\n#' @param undefined_msg Optional feedback message in case the student did not\n#'   define the object. A meaningful message is automatically generated if not\n#'   supplied.\n#' @param incorrect_msg Custom feedback message in case the student's object is\n#'   not the same as in the sample solution.\n#' @param col_missing_msg Custom message in case data frame column is missing\n#' @param col name of column to check\n#' @param el_missing_msg Custom message in case element is messing.\n#' @param el name of element to check\n#' @param append Whether or not to append the feedback to feedback built in\n#'   previous states\n#' @param ... S3 stuff\n#'\n#' @examples\n#' \\dontrun{\n#'\n#' # Example 1\n#' x <- mean(1:3, na.rm = TRUE)\n#'\n#' # sct to only check existence of x\n#' ex() %>%\n#'   check_object(\"x\")\n#'\n#' # sct to check existence and equality\n#' ex() %>%\n#'   check_object(\"x\") %>%\n#'   check_equal()\n#'\n#' # Example 2\n#' df <- data.frame(a = 1:3, b = LETTERS[1:3])\n#'\n#' # sct to test column a\n#' ex() %>%\n#'   check_object(\"df\") %>%\n#'   check_column(\"a\") %>%\n#'   check_equal()\n#'\n#' # Example 3\n#' lst <- list(a = 1, b = 2)\n#'\n#' # sct to test only element b\n#' ex() %>%\n#'   check_object(\"lst\") %>%\n#'   check_element(\"b\") %>%\n#'   check_equal()\n#'\n#' # Example 4\n#' today <- Sys.Date()\n#'\n#' # sct to check if classes are equal\n#' ex() %>%\n#'   check_object(\"today\") %>%\n#'   check_equal(eq_fun = function(x, y) { all.equal(class(x), class(y)) })\n#' }\n#' @name test_object\n\n#' @rdname test_object\n#' @export\ncheck_object <- function(state, name, undefined_msg = NULL, append = TRUE) {\n  assert_state(state)\n  # This check fails for quite a lot of old exercises,\n  # so currently doing the verification only if V2_ONLY is set.\n  # See https://github.com/datacamp/testwhat/issues/197\n  if(v2_only()) {\n    state$verify_root()\n  }\n\n  student_env <- state$get(\"student_env\")\n  solution_env <- state$get(\"solution_env\")\n  \n  assert_is_string(name)\n  \n  obj_state <- ObjectState$new(state)\n  obj_state$add_details(type = \"object\",\n                        case = \"defined\",\n                        name = name,\n                        message = undefined_msg,\n                        append = append,\n                        pd = NULL)\n  \n  check_defined(name, solution_env)\n  check_that(is_true(exists(name, envir = student_env, inherits = FALSE)),\n             feedback = obj_state$details)\n\n  obj_state$set_details(case = \"correct\",\n                        message = NULL,\n                        pd = extract_object_assignment(state$get(\"student_pd\"), name))\n  \n  obj_state$set(student_object = get(name, envir = student_env, inherits = FALSE),\n                solution_object = get(name, envir = solution_env, inherits = FALSE))\n  \n  return(obj_state)\n}\n\n#' @rdname test_object\n#' @export\ncheck_column <- function(state, col, col_missing_msg = NULL, append = TRUE) {\n  check_sub_helper(state, sub = col, sub_missing_msg = col_missing_msg, append = append, type = \"column\")\n}\n\n#' @rdname test_object \n#' @export\ncheck_element <- function(state, el, el_missing_msg = NULL, append = TRUE) {\n  check_sub_helper(state, sub = el, sub_missing_msg = el_missing_msg, append = append, type = \"element\")\n}\n\n\ncheck_sub_helper <- function(state, sub, sub_missing_msg, append, type = c(\"column\", \"element\")) {\n  assert_is_string(sub)\n  type <- match.arg(type)\n  ObjectSubState <- switch(type, column = ObjectColumnState, element = ObjectElementState)\n  student_object <- state$get(\"student_object\")\n  solution_object <- state$get(\"solution_object\")\n  \n  if (!sub %in% names(solution_object)) {\n    stop(sprintf(\"The %s %s is not available\", type, sub))\n  }\n  \n  object_sub_state <- ObjectSubState$new(state)\n  object_sub_state$add_details(type = type,\n                               case = \"defined\",\n                               name = sub,\n                               message = sub_missing_msg,\n                               append = append)\n  \n  check_that(is_true(sub %in% names(student_object)), feedback = object_sub_state$details)\n  \n  object_sub_state$set_details(case = \"correct\",\n                               message = NULL)\n  \n  object_sub_state$set(student_object = student_object[[sub]],\n                       solution_object = solution_object[[sub]])\n  \n  return(object_sub_state)\n}\n\n#' @rdname test_object\n#' @export\ncheck_equal.ObjectState <- function(state, incorrect_msg = NULL, append = TRUE, eq_condition = \"equivalent\", eq_fun = NULL, ...) {\n  check_equal_helper(state, incorrect_msg = incorrect_msg, append = append, eq_condition = eq_condition, eq_fun = eq_fun, type = \"object\")\n}\n\n#' @rdname test_object\n#' @export\ncheck_equal.ObjectColumnState <- function(state, incorrect_msg = NULL, append = TRUE, eq_condition = \"equivalent\", eq_fun = NULL, ...) {\n  check_equal_helper(state, incorrect_msg = incorrect_msg, append = append, eq_condition = eq_condition, eq_fun = eq_fun, type = \"column\")\n}\n\n#' @rdname test_object\n#' @export\ncheck_equal.ObjectElementState <- function(state, incorrect_msg = NULL, append = TRUE, eq_condition = \"equivalent\", eq_fun = NULL, ...) {\n  check_equal_helper(state, incorrect_msg = incorrect_msg, append = append, eq_condition = eq_condition, eq_fun = eq_fun, type = \"element\")\n}\n\ncheck_equal_helper <- function(state, incorrect_msg, eq_condition, append, eq_fun, type = c(\"object\", \"column\", \"element\"), ...) {\n  type <- match.arg(type)\n  student_obj <- state$get(\"student_object\")\n  solution_obj <- state$get(\"solution_object\")\n  state$add_details(type = type,\n                    case = \"equal\",\n                    student = student_obj,\n                    solution = solution_obj,\n                    eq_condition = eq_condition,\n                    message = incorrect_msg,\n                    append = append)\n  \n  if (is.null(eq_fun)) {\n    eq_fun <- function(x, y) is_equal(x, y, eq_condition)\n  }\n  check_that(eq_fun(student_obj, solution_obj), feedback = state$details)\n  return(state)\n}\n\n# Deprecated test functions\n\ntest_object <- function(name, eq_condition = \"equivalent\",\n                        eval = TRUE,\n                        undefined_msg = NULL, incorrect_msg = NULL) {\n  fail_if_v2_only()\n  obj_state <- ex() %>% check_object(name, \n                                     undefined_msg = undefined_msg,\n                                     append = is.null(undefined_msg))\n  if (eval) {\n    obj_state %>% check_equal(incorrect_msg = incorrect_msg, \n                              eq_condition = eq_condition,\n                              append = is.null(incorrect_msg))\n  }\n}\n\ntest_data_frame <- function(name, columns = NULL, \n                            eq_condition = \"equivalent\",\n                            undefined_msg = NULL,\n                            undefined_cols_msg = NULL, \n                            incorrect_msg = NULL) {\n  fail_if_v2_only()\n  obj_state <- ex() %>% check_object(name = name, \n                                     undefined_msg = undefined_msg,\n                                     append = is.null(undefined_msg))\n  \n  if (is.null(columns)) {\n    columns <- names(obj_state$get(\"solution_object\"))\n  }\n  \n  for (col in columns) {\n    obj_state %>% \n      check_column(col, col_missing_msg = undefined_cols_msg, append = is.null(undefined_cols_msg)) %>% \n      check_equal(eq_condition = eq_condition, incorrect_msg = incorrect_msg, append = is.null(incorrect_msg))\n  }\n}",
  "check-output.R": "#' Check whether the student printed something to the console\n#'\n#' Check the output of the submission to see if it contains certain elements.\n#'\n#' With \\code{check_output}, you can simply specify a regular expression or\n#' pattern (depending on the value of \\code{fixed}) that is looked for in the\n#' student's output. By default, regular output, messages, warnings and errors\n#' are considered.\n#'\n#' With \\code{test_output_contains} and \\code{check_output_expr} you can pass an\n#' expression, that is executed in the student environment, and whose output is \n#' compared to the output the student generated. If the generated output is found\n#' in the student's output, the check passes. By default, only regular output is\n#' considered.\n#'\n#' @param state the state to start from\n#' @param regex the regular expression or pattern to look for\n#' @param fixed if fixed is TRUE, \\code{regex} will be sought for 'as is' in the\n#'   output, if fixed = FALSE (the default), \\code{regex} will be treated as\n#'   actual regular expression.\n#' @param trim should the student output be trimmed, so that all newlines and\n#'   spaces are removed, before checking?\n#' @param times how often should the pattern/expression output be found?\n#' @param output_only Consider only regular output, or also messages, warnings\n#'   and error? \\code{FALSE} by default for \\code{check_output} (so it considers\n#'   all kinds of output). You cannot specify this argument for\n#'   \\code{check_output_expr} and \\code{test_output_contains}.\n#' @param missing_msg Custom message in case the pattern or output wasn't found\n#'   often enough.\n#' @param ... S3 stuff\n#' @param append Whether or not to append the feedback to feedback built in\n#'   previous states\n#' @param expr The expression (as string) for which the output should be in the\n#'   student's console output.\n#'\n#' @examples\n#' \\dontrun{\n#' # Example 1\n#' mtcars\n#'\n#' # SCT\n#' ex() %>% check_output_expr(\"mtcars\")\n#'\n#' # Example 2\n#' print(\"hello!\")\n#'\n#' # SCT (robust)\n#' ex() %>% check_output(\"[H|h]ello\\\\!*\")\n#' }\n#'\n#' @name check_output\n\n#' @rdname check_output\n#' @export\ncheck_output <- function(state, ...) {\n  UseMethod(\"check_output\", state)\n}\n\n#' @rdname check_output\n#' @export\ncheck_output.default <- function(state, regex, fixed = FALSE, trim = FALSE, times = 1, output_only = FALSE, missing_msg = NULL, append = TRUE, ...) {\n  assert_state(state)\n  regex_state <- RegexState$new(state)\n  regex_state$add_details(type = \"output\",\n                          case = \"regex\",\n                          regex = regex,\n                          times = times,\n                          message = missing_msg,\n                          append = append,\n                          pd = NULL)\n  console_output <- convert_output_list(state$get(\"output_list\"), output_only = output_only)\n  if (trim) {\n    console_output <- trim_output(console_output)\n  }\n  num_hits <- get_num_hits(regex = regex, x = console_output, fixed = fixed)\n  check_that(is_gte(num_hits, times), feedback = regex_state$details)\n  return(regex_state)\n}\n\n#' @rdname check_output\n#' @export\ncheck_output_expr <- function(state, expr, times = 1, missing_msg = NULL, append = TRUE) {\n  assert_state(state)\n  state$verify_root()\n\n  expr_output <- try(capture.output(base::eval(parse(text = expr), envir = ex()$get(\"student_env\"))), silent = TRUE)\n  if (inherits(expr_output, \"try-error\")) {\n    expr_output <- \"\"\n  }\n  expr_output <- paste(expr_output, collapse = \"\\n\")\n\n  regex_state <- RegexState$new(state)\n  regex_state$add_details(type = \"output\",\n                          case = \"expr\",\n                          expr = expr,\n                          times = times,\n                          message = missing_msg,\n                          append = append,\n                          pd = NULL)\n\n  console_output <- trim_output(convert_output_list(state$get(\"output_list\"), output_only = TRUE))\n  num_hits <- get_num_hits(regex = trim_output(expr_output), x = console_output, fixed = TRUE)\n  check_that(is_gte(num_hits, times), feedback = regex_state$details)\n  return(regex_state)\n}\n\n# Helper functions\n\nconvert_output_list <- function(x, output_only = FALSE) {\n  types <- if(output_only) \"output\" else c(\"output\", \"r-message\", \"r-warning\", \"r-error\")\n  output_indices <- which(sapply(x, `[[`, \"type\") %in% types)\n  paste(sapply(x[output_indices], `[[`, \"payload\"), collapse = \"\\n\")\n}\n\ntrim_output <- function(x) {\n  gsub(\"\\n|[[:space:]]\", \"\", x)\n}\n\nclean_up <- function(x) {\n  x <- gsub(\"[[:space:]]|;|\\n\", \"\", x)\n  x <- gsub(\"=\", \"<-\", x)\n  x <- gsub(\"FALSE\", \"F\", x)\n  x <- gsub(\"TRUE\", \"T\", x)\n  x <- gsub(\"\\\"\", \"'\", x)\n  return(x)\n}\n\n# Deprecated\n\ntest_output_contains <- function(expr, times = 1, incorrect_msg = NULL) {\n  fail_if_v2_only()\n  ex() %>% check_output_expr(expr = expr, times = times, missing_msg = incorrect_msg, append = is.null(incorrect_msg))\n}\n\n",
  "check-predefined-objects.R": "#' Test predefined R objects\n#'\n#' At the start of your SCT, you typically want to check whether some predefined\n#' variables are still correct. \\code{test_predefined_object} allows you to\n#' specify a vector of object names, together with a vector of equivalence\n#' conditions, evaluation specifications, undefined an incorrect messages.\n#'\n#' @param state the state to start from\n#' @param name vector of names of the objects to check\n#' @param eq_condition character vector indicating how to compare. See\n#'   \\code{\\link{is_equal}}.\n#' @param eval logical vector indicating whether or not you want to check only\n#'   the objects' existence or also whether their values match the solution.\n#' @param undefined_msg vector version of \\code{undefined_msg} of\n#'   \\code{\\link{check_object}}\n#' @param incorrect_msg vector version of \\code{incorrect_msg} of\n#'   \\code{\\link{check_object}}\n#'\n#' @examples\n#' \\dontrun{\n#' # Suppose the sample code specifies the variables a, b and c,\n#' # and you want to check that a, b and c haven't changed.\n#' ex() %>% check_predefined_objects(c(\"a\", \"b\", \"c\"))\n#' }\n#'\n#' @export\ncheck_predefined_objects <- function(state,\n                                     name, \n                                     eq_condition = \"equivalent\",\n                                     eval = TRUE,\n                                     undefined_msg = NULL, \n                                     incorrect_msg = NULL) {\n  assert_state(state)\n  n_names <- length(name)\n  eq_condition <- rep(eq_condition, n_names, length.out = n_names)\n  eval <- rep(eval, n_names, length.out = n_names)\n  \n  already <- \"it has already been coded for you! You can use the arrow to the left of 'Run Code' to reset your code.\"\n  \n  if (is.null(undefined_msg)) {\n    undefined_msg <- sprintf(\"Don't remove the predefined variable `%s`; %s\", name, already)\n  }\n  \n  if (is.null(incorrect_msg)) {\n    incorrect_msg <- sprintf(\"Don't change the contents of the predefined variable `%s`; %s\", name, already)\n  }\n  \n  undefined_msg <- rep(undefined_msg, n_names, length.out = n_names)\n  incorrect_msg <- rep(incorrect_msg, n_names, length.out = n_names)\n  \n  for (i in 1:n_names) {\n    obj <- ex() %>% check_object(name[i], undefined_msg = undefined_msg[i])\n    if (isTRUE(eval[i])) {\n      obj %>% check_equal(eq_condition = eq_condition[i], incorrect_msg = incorrect_msg[i])\n    }\n  }\n}\n\ntest_predefined_objects <- function(name, \n                                    eq_condition = \"equivalent\",\n                                    eval = TRUE,\n                                    undefined_msg = NULL, \n                                    incorrect_msg = NULL) {\n  fail_if_v2_only()\n  ex() %>% check_predefined_objects(name = name,\n                                    eq_condition = eq_condition,\n                                    eval = eval,\n                                    undefined_msg = undefined_msg,\n                                    incorrect_msg = incorrect_msg)\n}\n",
  "check-rmd-utils.R": "find_same_line <- function(lines, patt) {\n  hits <- which(grepl(patt, lines))\n  return(hits)\n}\n\nfind_prev_line <- function(lines, patt) {\n  candidates <- which(grepl(patt, lines)) - 1\n  # previous row must contain code\n  return(candidates[!grepl(\"^\\\\s*$\", lines[candidates])])\n}\n\nget_header_hits <- function(lines, level) {\n  all_hits <- list(\n    h1 = sort(c(length(lines) + 1,\n                find_same_line(patt = \"^#\\\\s+.*?\", lines = lines),\n                find_prev_line(patt = \"^={5,}$\", lines = lines))),\n    h2 = sort(c(length(lines) + 1,\n                find_same_line(patt = \"^##\\\\s+.*?\", lines = lines),\n                find_prev_line(patt = \"^-{5,}$\", lines = lines))),\n    h3 = sort(c(length(lines) + 1, find_same_line(patt = \"^###\\\\s+.*?\", lines = lines)))\n  )\n  \n  hits <- all_hits[[paste0('h', level)]]\n  if(is.null(hits)) stop(sprintf(\"No pattern matching available for level %i.\", level))\n  return(hits)\n}\n\nget_header_elements <- function(lines, hits, index) {\n  title <- lines[hits[index]]\n  contents <- lines[(hits[index] + 1): (hits[index+1] - 1)]\n  contents <- contents[!grepl(\"^-{5,}$\", contents)]\n  contents <- contents[!grepl(\"^={5,}$\", contents)]\n  contents <- paste0(contents, collapse = \"\\n\")\n  \n  return(list(contents = contents, title = title))\n}\n\nget_chunks <- function(code, index = index) {\n  doc_structure <- build_doc_structure(code)\n  chunks <- doc_structure[sapply(doc_structure, class) == \"block\"]\n  return(chunks)\n}\n\nselect_chunk <- function(chunks, index) {\n  payload = list(params = chunks[[index]]$params,\n                 code = chunks[[index]]$input,\n                 pd = build_pd(chunks[[index]]$input))\n  return(payload)\n}\n\nparse_yaml <- function(code) {\n  rmarkdown:::parse_yaml_front_matter(strsplit(code, split = \"\\n\")[[1]])\n}\n\n\ncheck_equal_option_helper <- function(state, type, incorrect_msg, append) {\n  student_option <- state$get(\"student_option\")\n  solution_option <- state$get(\"solution_option\")\n  state$add_details(type = type,\n                    case = \"equal\",\n                    student = student_option,\n                    solution = solution_option,\n                    message = incorrect_msg,\n                    append = append)\n  \n  check_that(is_equal(student_option, solution_option, \"equal\"),\n             feedback = state$details)\n  \n  return(state)\n}",
  "check-rmd.R": "#' Check markdown file\n#' \n#' Zoom in on contents of R Markdown code submission.\n#' \n#' @param state the state to start from\n#' \n#' @export\ncheck_rmd <- function(state) {\n  assert_state(state)\n  student_code <- state$get(\"student_code\")\n  solution_code <- state$get(\"solution_code\")\n\n  student_file <- names(student_code)[grepl(\".rmd|.Rmd\", names(student_code))]\n  stopifnot(length(student_file) == 1)\n  \n  solution_file <- names(solution_code)[grepl(\".rmd|.Rmd\", names(solution_code))]\n  stopifnot(length(solution_file) == 1)\n\n  file_state <- SubState$new(state)\n  \n  file_state$set(student_code = unname(student_code[student_file]),\n                 solution_code = unname(solution_code[solution_file]))\n  return(file_state)\n}\n\n# Deprecated:\ntest_rmd_file <- function(code) {\n  fail_if_v2_only()\n  old_state <- ex()\n  on.exit(tw$set(state = old_state))\n  test_env <- old_state$get(\"test_env\")\n  tw$set(state = check_rmd(old_state))\n  eval(substitute(code), envir = test_env)\n}\n\n#' Check markdown header\n#'\n#' Checks if a markdown header with a certain level exists. If not, generates a\n#' feedback message. If yes, zooms in on the entire header section.\n#'\n#' @param state the state to start from.\n#' @param level the level of the header to check\n#' @param index which h<level> header to check\n#' @param not_found_msg If specified, this overrides the automatically generated\n#'   message in case not enough headers of the specified level were found.\n#' @param append Whether or not to append the feedback to feedback built in\n#'   previous states\n#'\n#' @return A state that zooms in on the section under the header until the next\n#'   same-level header.\n#'\n#' @export\ncheck_header <- function(state, level, index = 1, not_found_msg = NULL, append = TRUE) {\n  assert_state(state)\n  student_lines <- strsplit(state$get(\"student_code\"), split = \"\\n\")[[1]]\n  solution_lines <- strsplit(state$get(\"solution_code\"), split = \"\\n\")[[1]]\n\n  markdown_header_state <- MarkdownHeaderState$new(state)\n  markdown_header_state$add_details(type = 'markdown_header',\n                                    case = 'defined',\n                                    index = index,\n                                    level = level,\n                                    message = not_found_msg,\n                                    append = append,\n                                    pd = NULL)\n  \n  student_header_hits <- get_header_hits(student_lines, level = level)\n  solution_header_hits <- get_header_hits(solution_lines, level = level)\n  \n  if (index >= length(solution_header_hits)) {\n    stop(sprintf(\"The solution doesn't contain %i headers of level %i itself.\", index, level))\n  }\n  \n  check_that(is_lt(index, length(student_header_hits)), feedback = markdown_header_state$details)\n  \n  student_header <- get_header_elements(student_lines, student_header_hits, index = index)\n  solution_header <- get_header_elements(solution_lines, solution_header_hits, index = index)\n  \n  markdown_header_state$set_details(case = 'correct', message = NULL)\n  markdown_header_state$set(student_code = student_header$contents,\n                            solution_code = solution_header$contents,\n                            student_title = student_header$title,\n                            solution_title = solution_header$title)\n  return(markdown_header_state)\n}\n\n#' Check markdown header title\n#'\n#' Checks if a title was specified for a markdown header. If not, generates a\n#' feedback message. If yes, zooms in on the title so you can use\n#' \\code{check_equal}.\n#'\n#' @param state the state to start from. Should be a state produced by\n#'   \\code{\\link{check_header}}.\n#' @param not_found_msg If specified, this overrides the automatically generated\n#'   message in case no title was specified.\n#' @param append Whether or not to append the feedback to feedback built in\n#'   previous states.\n#'\n#' @return A state that zooms in on the title of the header.\n#'\n#' @export\ncheck_title <- function(state, not_found_msg = NULL, append = TRUE) {\n  assert_state(state)\n  stopifnot(inherits(state, \"MarkdownHeaderState\"))\n  student_title <- state$get(\"student_title\")\n  solution_title <- state$get(\"solution_title\")\n  \n  markdown_title_state <- ChildState$new(state)\n  markdown_title_state$add_details(type = 'markdown_title',\n                                   case = 'defined',\n                                   message = not_found_msg,\n                                   pd = NULL,\n                                   append = append)\n  \n  if (is.null(solution_title) || solution_title == \"character(0)\") {\n    stop(\"check_title couldn't retrieve the header title. Make sure you pass it a state coming from check_header.\")\n  }\n  \n  check_that(is_false(is.null(student_title) || student_title == \"character(0)\"),\n             feedback = markdown_title_state$details)\n  \n  markdown_title_state$set_details(case = \"correct\", message = NULL, pd = NULL)\n  markdown_title_state$set(student_code = student_title,\n                           solution_code = solution_title)\n  \n  return(markdown_title_state)\n}\n\n\n#' Check markdown code chunk\n#'\n#' Checks if a code chunk was specified. If not, generates a feedback message.\n#' If yes, zooms in on the code chunk so you can use functions like\n#' \\code{\\link{check_function}} as for any regular R exercise.\n#'\n#' @param state the state to start from. This state can be produced by\n#'   \\code{\\link{check_rmd}}, but can also follow on \\code{\\link{check_header}}\n#'   to look for a chunk in a specific header section.\n#' @param index number that specifies which code chunk to check in the student\n#'   and solution code that is zoomed in on.\n#' @param not_found_msg If specified, this overrides the automatically generated\n#'   message in case no index'th chunk was found.\n#' @param append Whether or not to append the feedback to feedback built in\n#'   previous states.\n#'\n#' @return A state that zooms in on the code chunk.\n#'\n#' @export\ncheck_chunk <- function(state, index = 1, not_found_msg = NULL, append = TRUE) {\n  assert_state(state)\n  student_code <- state$get(\"student_code\")\n  solution_code <- state$get(\"solution_code\")\n  \n  student_chunks <- get_chunks(student_code)\n  solution_chunks <- get_chunks(solution_code)\n  \n  markdown_chunk_state <- MarkdownChunkState$new(state)\n  \n  markdown_chunk_state$add_details(type = 'markdown_chunk',\n                                   case = 'defined',\n                                   index = index,\n                                   message = not_found_msg,\n                                   append = append,\n                                   pd = NULL)\n  \n  if (index > length(solution_chunks)) {\n    stop(sprintf(\"The solution doesn't contain %i code chunks in the piece of code that is zoomed in on.\", index))\n  }\n  \n  check_that(is_gte(length(student_chunks), index),\n             feedback = markdown_chunk_state$details)\n  \n  student_chunk <- select_chunk(student_chunks, index = index)\n  solution_chunk <- select_chunk(solution_chunks, index = index)\n  markdown_chunk_state$set(student_code = student_chunk$code,\n                           solution_code = solution_chunk$code,\n                           student_pd = student_chunk$pd,\n                           solution_pd = solution_chunk$pd,\n                           student_options = student_chunk$params,\n                           solution_options = solution_chunk$params)\n  markdown_chunk_state$set_details(case = 'correct', message = NULL)\n  return(markdown_chunk_state)\n}\n\n#' Check markdown code chunk option\n#'\n#' Checks if a code chunk option was specified. If not, generates a feedback\n#' message. If yes, zooms in on the code chunk option so you can use\n#' \\code{\\link{check_equal}} to verify equality.\n#'\n#' @param state the state to start from. Should be a state produced by\n#'   \\code{\\link{check_chunk}}.\n#' @param name name of the chunk option to zoom in on.\n#' @param not_found_msg If specified, this overrides the automatically generated\n#'   message in case the option wasn't specified.\n#' @param append Whether or not to append the feedback to feedback built in\n#'   previous states.\n#' @param ... S3 stuff\n#'\n#' @return A state that zooms in on the code chunk option.\n#'\n#' @export\ncheck_option.MarkdownChunkState <- function(state, name, not_found_msg = NULL, append = TRUE, ...) {\n  assert_state(state)\n  student_options <- state$get(\"student_options\")\n  solution_options <- state$get(\"solution_options\")\n  markdown_chunk_option_state <- MarkdownChunkOptionState$new(state)\n  markdown_chunk_option_state$add_details(type = 'markdown_chunk_option',\n                                          case = 'defined',\n                                          name = name,\n                                          message = not_found_msg,\n                                          append = append,\n                                          pd = NULL)\n  if (!name %in% names(solution_options)) {\n    stop(sprintf('check_option() tries to check the option %s of a code chunk, but it\\'s not specified in the solution', name))\n  }\n  \n  check_that(is_true(name %in% names(student_options)),\n             feedback = markdown_chunk_option_state$details)\n  \n  markdown_chunk_option_state$set(student_option = student_options[[name]],\n                                  solution_option = solution_options[[name]])\n  markdown_chunk_option_state$set_details(case = 'correct', message = NULL)\n  return(markdown_chunk_option_state)\n}\n\n#' Check equality of markdown code chunk option\n#'\n#' @param state the state to start from. Should be a state produced by \\code{\\link{check_option}}.\n#' @param incorrect_msg If specified, this overrides the automatically generated message in case the options don't match between student and solution.\n#' @param append Whether or not to append the feedback to feedback built in previous states.\n#' @param ... S3 stuff\n#'\n#' @export\ncheck_equal.MarkdownChunkOptionState <- function(state, incorrect_msg = NULL, append = FALSE, ...) {\n  assert_state(state)\n  check_equal_option_helper(state, \"markdown_yaml_option\", incorrect_msg = incorrect_msg, append = append)\n}\n\n#' Check markdown YAML header\n#'\n#' Checks if a YAML header was specified and can be parsed. If not, generates a\n#' feedback message. If yes, parses the YAML header and zooms in on its options\n#' so you can use \\code{\\link{check_option}} to verify the options.\n#'\n#' @param state the state to start from. This state should be produced by\n#'   \\code{\\link{check_rmd}}.\n#' @param error_msg If specified, this overrides the automatically generated\n#'   message in case the YAML header couldn't be parsed.\n#' @param append Whether or not to append the feedback to feedback built in\n#'   previous states.\n#'\n#' @return A state that zooms in on the YAML header options.\n#'\n#' @export\ncheck_yaml <- function(state, error_msg = NULL, append = TRUE) {\n  assert_state(state)\n  student_code <- state$get(\"student_code\")\n  solution_code <- state$get(\"solution_code\")\n  \n  markdown_yaml_state <- MarkdownYamlState$new(state)\n  \n  markdown_yaml_state$add_details(type = 'markdown_yaml',\n                                  case = 'parsing_error',\n                                  message = error_msg,\n                                  append = append,\n                                  pd = NULL)\n  \n  solution_yaml <- tryCatch(parse_yaml(solution_code), error = function(e) {\n    stop(sprintf(\"check_yaml() coudn't parse the solution's YAML header: %s\", e$message))\n  })\n  \n  student_yaml <- tryCatch(parse_yaml(student_code), error = function(e) {\n    check_that(failure(), feedback = markdown_yaml_state$details)  \n  })\n  \n  markdown_yaml_state$set(student_yaml = student_yaml,\n                          solution_yaml = solution_yaml)\n  markdown_yaml_state$set_details(case = 'correct', message = NULL)\n  return(markdown_yaml_state)\n}\n\n#' Check markdown YAML header option\n#'\n#' Checks if a yaml header option was specified. If not, generates a feedback\n#' message. If yes, zooms in on the YAML header option so you can use\n#' \\code{\\link{check_equal}} to verify equality.\n#'\n#' @param state the state to start from. Should be a state produced by\n#'   \\code{\\link{check_yaml}}.\n#' @param name name of the YAML header option to zoom in on. If you want to\n#'   check a nested option, use \\code{c()} to chain together the different\n#'   names.\n#' @param not_found_msg If specified, this overrides the automatically generated\n#'   message in case the option wasn't specified.\n#' @param append Whether or not to append the feedback to feedback built in\n#'   previous states.\n#' @param ... S3 stuff\n#'\n#' @return A state that zooms in on the YAML header option.\n#'\n#' @export\ncheck_option.MarkdownYamlState <- function(state, name, not_found_msg = NULL, append = TRUE, ...) {\n  assert_state(state)\n  student_yaml <- state$get(\"student_yaml\")\n  solution_yaml <- state$get(\"solution_yaml\")\n  markdown_yaml_option_state <- MarkdownYamlOptionState$new(state)\n  markdown_yaml_option_state$add_details(type = 'markdown_yaml_option',\n                                         case = 'defined',\n                                         name = name,\n                                         message = not_found_msg,\n                                         append = append,\n                                         pd = NULL)\n  \n  solution_option <- try(solution_yaml[[name]], silent = TRUE)\n  if (inherits(solution_option, \"try-error\") || is.null(solution_option)) {\n    stop(sprintf('check_option() tries to check the option %s of the yaml, but it is not specified in the solution',\n                 yaml_option_desc(name)))\n  }\n  \n  student_option <- try(student_yaml[[name]], silent = TRUE)\n  check_that(is_false(inherits(student_option, \"try-error\") || is.null(student_option)),\n             feedback = markdown_yaml_option_state$details)\n  \n  markdown_yaml_option_state$set(student_option = student_option,\n                                 solution_option = solution_option)\n  markdown_yaml_option_state$set_details(case = 'correct', message = NULL)\n  return(markdown_yaml_option_state)\n}\n\n#' Check equality of markdown YAML header option\n#'\n#' @param state the state to start from. Should be a state produced by\n#'   \\code{\\link{check_option}}.\n#' @param incorrect_msg If specified, this overrides the automatically generated\n#'   message in case the options don't match between student and solution.\n#' @param append Whether or not to append the feedback to feedback built in\n#'   previous states.\n#' @param ... S3 stuff\n#'\n#' @export\ncheck_equal.MarkdownYamlOptionState <- function(state, incorrect_msg = NULL, append = TRUE, ...) {\n  assert_state(state)\n  check_equal_option_helper(state, \"markdown_chunk_option\", incorrect_msg = incorrect_msg, append = append)\n}\n\n",
  "check-that.R": "#' Expectation wrapper\n#'\n#' This function wraps around an is_... function. When the expectation fails to\n#' be met, the feedback message is sent to the reporter. You can use\n#' \\code{\\link{is_true}}, \\code{\\link{is_false}}, \\code{\\link{is_gte}} or\n#' \\code{\\link{is_equal}}\n#'\n#' @param code The expectation that should be wrapped\n#' @param feedback A character string with feedback when the expection is not\n#'   met OR a list object, containing multiple pieces of information. This list\n#'   should at least contain an element named \\code{message}\n#' @param env environment in which the test should be evaluated; defaults to \\code{parent.frame()}\n#'\n#' @examples\n#' \\dontrun{\n#' check_that(is_true(3 == 3))\n#' check_that(is_false(3 == 4))\n#' check_that(is_gte(4, 3))\n#' check_that(is_equal(4, 4))\n#' }\n#' @name check_that\n\n#' @rdname check_that\n#' @export\ncheck_that <- function(code, feedback, env = parent.frame()) {\n  \n  # feedback can be a character string\n  if (is.character(feedback)) {\n    feedback <- list(list(message = feedback))\n  }\n  \n  stopifnot(is.list(feedback), is.list(feedback[[1]]))\n  \n  res <- try(eval(code, envir = env), silent = TRUE)\n  if (!isTRUE(res)) {\n    throw_sct_failure(feedback = feedback,\n                      message = build_feedback_message(feedback))\n  }\n}\n\nthrow_sct_failure <- function(message, feedback, call = sys.call(-1)) {\n  sct_failed_msg <-\n    c <- structure(\n      class = c(\"sct_failure\", \"error\", \"condition\"),\n      list(message = message, call = call),\n      feedback = feedback)\n  stop(c)\n}\n\n#' @rdname check_that\n#' @export\ntest_what <- function(code, feedback) {\n  fail_if_v2_only()\n  lut <- list(expect_true = call(\"is_true\"),\n              expect_false = call(\"is_false\"),\n              expect_equal = call(\"is_equal\"))\n  call <- substitute(code)\n  call[1] <- lut[[as.character(call[[1]])]]\n  check_that(call, feedback, env = parent.frame())\n}",
  "check-wd.R": "#' Check whether a file exists\n#' \n#' @param path Path to the file you want to check\n#' @param missing_msg Custom feedback message in case the file is missing\n#' @param state the state to start from\n#' \n#' @examples\n#' \\dontrun{\n#' # Example 1 solution code:\n#' # write(\"hello\", file = \"test.txt\")\n#' \n#' # SCT\n#' ex() %>% check_wd(\"test.txt\")\n#' }\n#' @export\ncheck_wd <- function(state, path, missing_msg = NULL) {\n  assert_state(state)\n  file_state <- FileState$new(state)\n  file_state$add_details(type = 'file',\n                         case = 'available',\n                         file = basename(path),\n                         folder = dirname(path),\n                         message = missing_msg)\n  check_that(is_true(file.exists(path)), feedback = file_state$details)\n  return(state)\n}\n\ntest_file_exists <- function(path, incorrect_msg = NULL) {\n  fail_if_v2_only()\n  ex() %>% check_wd(path = path, missing_msg = incorrect_msg)\n}\n",
  "comparison.R": "#' Check if object is true, false, >= or <.\n#'\n#' Utility functions to use inside \\code{\\link{check_that}}.\n#'\n#' @param x object to test\n#' @param y single numeric value to compare\n#' @name compare\n\n#' @rdname compare\n#' @export\nis_true <- function(x) {\n  identical(as.vector(x), TRUE)\n}\n\n#' @rdname compare\n#' @export\nis_false <- function(x) {\n  identical(as.vector(x), FALSE)\n}\n\n#' @rdname compare\n#' @export\nis_gte <- function(x, y) {\n  stopifnot(is.numeric(x), length(x) == 1)\n  stopifnot(is.numeric(y), length(y) == 1)\n  x >= y\n}\n\n#' @rdname compare\n#' @export\nis_lt <- function(x, y) {\n  stopifnot(is.numeric(x), length(x) == 1)\n  stopifnot(is.numeric(y), length(y) == 1)\n  x < y\n}\n",
  "diff.R": "build_diff <- function(sol, stud, ...) {\n  if (isTRUE(try(all.equal(stud, tryerrorstring), silent = TRUE))) {\n    return(\"evaluating the expression you specified caused an error.\")\n  }\n  get_diff(sol, stud, ...)\n}\n\nget_diff <- function(sol, ...) {\n  UseMethod(\"get_diff\", sol)\n}\n\nget_diff.default <- function(sol, ...) {\n  return(NULL)\n}\n\n## Class-specific diffs\n\nget_diff.logical <- function(sol, stud, eq_condition, id) {\n  if (!typeof(stud) %in% c(\"logical\", \"integer\", \"double\")) {\n    return(diff_type(sol, stud, id))\n  }\n  if (!same_class(sol, stud)) {\n    return(diff_class(sol, stud, id))\n  }\n  if (!same_length(sol, stud)) {\n    return(diff_length(sol, stud, id))\n  }\n  if (check_attr(eq_condition) && !same_attr(sol, stud)) {\n    return(diff_attr(sol, stud, id))\n  }\n  return(NULL)\n}\n\nget_diff.numeric <- function(sol, stud, eq_condition, id) {\n  if (!typeof(stud) %in% c(\"integer\", \"double\")) {\n    return(diff_type(sol, stud, id))\n  }\n  if (!same_class(sol, stud)) {\n    return(diff_class(sol, stud, id))\n  }\n  if (!same_length(sol, stud)) {\n    return(diff_length(sol, stud, id))\n  }\n  if (check_attr(eq_condition) && !same_attr(sol, stud)) {\n    return(diff_attr(sol, stud, id))\n  }\n  return(NULL)\n}\n\n#' @importFrom stringdist stringdist\nget_diff.character <- function(sol, stud, eq_condition, id) {\n  if (!same_type(sol, stud)) {\n    return(diff_type(sol, stud, id))\n  }\n  if (!same_class(sol, stud)) {\n    return(diff_class(sol, stud, id))\n  }\n  if (!same_length(sol, stud)) {\n    return(diff_length(sol, stud, id))\n  }\n  if (check_attr(eq_condition) && !same_attr(sol, stud)) {\n    return(diff_attr(sol, stud, id))\n  }\n  if (length(sol) == 1) { # stud is also length 1\n    if (tolower(sol) == tolower(stud)) {\n      return(\"note that R is case-sensitive!\")\n    }\n    if (gsub(\"\\\\s\", \"\", sol) == gsub(\"\\\\s\", \"\", stud)) {\n      return(\"make sure to use the correct spacing!\")\n    }\n    patt <- \"[!\\\\?\\\\.\\\\;\\\\,\\\\:]\"\n    if (gsub(patt, \"\", sol) == gsub(patt, \"\", stud)) {\n      return(\"make sure to use the correct punctuation marks!\")\n    }\n    # If number of edits required is below a fifth of the character length: typo?\n    if (stringdist(sol, stud, nthread = 1, method = \"dl\") < round(nchar(sol)/5 + 1)) {\n      return(\"there might be a typo in there.\")\n    }\n  }\n  return(NULL)\n}\n\nget_diff.data.frame <- function(sol, stud, eq_condition, id) {\n  if (!same_type(sol, stud)) {\n    return(diff_type(sol, stud, id))\n  }\n  if (!same_class(sol, stud)) {\n    return(diff_class(sol, stud, id))\n  }\n  if (!same_dim(sol, stud)) {\n    return(diff_dim(sol, stud, id))\n  }\n  if (check_attr(eq_condition) && !same_attr(sol, stud)) {\n    return(diff_attr(sol, stud, id))\n  }\n}\n\n\nsame_length <- function(sol, stud) length(sol) == length(stud)\ndiff_length <- function(sol, stud, id) sprintf(\"%s has length %i, while it should have length %i.\",\n                                          id, length(stud), length(sol))\n\nsame_dim <- function(sol, stud) isTRUE(all.equal(dim(sol), dim(stud)))\ndiff_dim <- function(sol, stud, id) {\n  stud_rows <- dim(stud)[1]\n  stud_cols <- dim(stud)[2]\n  sol_rows <- dim(sol)[1]\n  sol_cols <- dim(sol)[2]\n  plural <- function(x) {\n    ifelse(x > 1, \"s\", \"\")\n  }\n  sprintf(\"%s has %i row%s and %i column%s, while it should have %i row%s and %i column%s.\",\n          id, stud_rows, plural(stud_rows), stud_cols, plural(stud_cols),\n          sol_rows, plural(sol_rows), sol_cols, plural(sol_cols))\n}\n\nklass <- function(sol) paste(class(sol), collapse = \"/\")\n\nsame_type <- function(sol, stud) identical(typeof(sol), typeof(stud))\ndiff_type <- function(sol, stud, id) sprintf(\"%s is a %s, while it should be a %s.\",\n                                        id, typeof2(stud), typeof2(sol))\n\nsame_class <- function(sol, stud) {\n  if (!is.object(sol) && !is.object(stud))\n    return(TRUE)\n  identical(class(sol), class(stud))\n}\ndiff_class <- function(sol, stud, id) sprintf(\"%s is of class `%s`, while it should be of class `%s`.\", id, klass(stud), klass(sol))\n\nsame_attr <- function(sol, stud) is.null(attr.all.equal(sol, stud))\ndiff_attr <- function(sol, stud, id) sprintf(\"are you sure the attributes (names, class, etc.) of %s are correct?\", id)\n\ntypeof2 <- function(x) {\n  if (typeof(x) == \"logical\") {\n    if (length(x) <= 1) {\n      return(\"logical\")\n    } else {\n      return(\"logical vector\")\n    }\n  } else if (typeof(x) %in% c(\"integer\", \"double\")) {\n    if (length(x) <= 1) {\n      return(\"number\")\n    } else {\n      return(\"numeric vector\")\n    }\n  } else if (typeof(x) == \"character\") {\n    if (length(x) <= 1) {\n      return(\"character string\")\n    } else {\n      return(\"character vector\")\n    }\n  } else if (typeof(x) == \"list\") {\n    if (class(x) == \"data.frame\") {\n      return(\"data frame\")\n    } else {\n      return(\"list\")\n    }\n  } else {\n    return(sprintf(\"`%s`\", typeof(x)))\n  }\n}\n\ncheck_attr <- function(eq_condition) {\n  switch(eq_condition,\n         equivalent = FALSE,\n         equal = TRUE,\n         identical = TRUE,\n         stop(invalid_eq_condition))\n}\n\n",
  "is-equal.R": "invalid_eq_condition <- \"eq_condition should be either 'equivalent', 'equal' or 'identical'.\"\n\n#' Check equality of two objects\n#'\n#' Utility function to use inside \\code{\\link{check_that}}.\n#'\n#' @param x object to test\n#' @param y object to compare\n#' @param eq_condition how to compare the objects: \\code{\"equivalent\"} (the default,\n#'   does not check attributes), \\code{\"equal\"} (checks attributes, but allows for\n#'   errors in machine precision), or \\code{\"identical\"} (exactly identical).\n#' @name is_equal\n\n#' @rdname is_equal\n#' @export\nis_equal <- function(x, y, eq_condition = \"equivalent\") {\n  UseMethod(\"is_equal\", x)\n}\n\n#' @rdname is_equal\n#' @export\nis_equal.default <- function(x, y, eq_condition = \"equivalent\") {\n  eq_fun <- switch(eq_condition,\n                   equivalent = function(x, y) isTRUE(try(all.equal(x, y, check.attributes = FALSE), silent = TRUE)),\n                   equal = function(x, y) isTRUE(try(all.equal(x, y), silent = TRUE)),\n                   identical = identical,\n                   stop(invalid_eq_condition))\n  eq_fun(x, y)\n}\n\n#' @rdname is_equal\n#' @export\nis_equal.formula <- function(x, y, eq_condition = \"equivalent\") {\n  tryCatch({\n    xlst <- convert_formula(x)\n    ylst <- convert_formula(y)\n    isTRUE(all.equal(xlst$target, ylst$target)) &&\n      isTRUE(all.equal(xlst$explan, ylst$explan))\n  }, error = function(e) {\n    # fallback to default equality\n    is_equal.default(x, y, eq_condition)\n  })\n}\n\nconvert_formula <- function(form) {\n  n <- length(form)\n  deparsed <- lapply(form, deparse)[2:n]\n  target <- deparsed[[1]]\n  explan <- deparsed[[2]]\n  trm <- function(x) gsub(\"^\\\\s+|\\\\s+$\", \"\", x)\n  explan <- sort(trm(strsplit(explan, \"\\\\+\")[[1]]))\n  return(list(target = target, explan = explan))\n}\n",
  "messages-utils.R": "trim <- function(x) {\n  gsub(\"^\\\\s+|\\\\s+$\", \"\", x)\n}\n\ncapitalize <- function(x) {\n  enders <- c(\".\", \"?\", \"!\")\n  for (e in enders) {\n    x <- strsplit(x, split = sprintf(\"\\\\%s\\\\s\", e))[[1]]\n    x <- paste0(toupper(substring(x, 1, 1)), substring(x, 2), collapse = sprintf(\"%s \", e))\n  }\n  return(x)\n}\n\n# Nicely collapse a character vector\ncollapse <- function(x, conn = \" and \") {\n  if (length(x) > 1) {\n    n <- length(x)\n    last <- c(n - 1, n)\n    collapsed <- paste(x[last], collapse = conn)\n    collapsed <- paste(c(x[-last], collapsed), collapse = \", \")\n  } else collapsed <- x\n  collapsed\n}\n\ncollapse_args <- function(x, conn = \" and \") {\n  collapse(paste0(\"`\",x,\"`\"), conn)\n}\n\ncollapse_props <- collapse_args\n\ncollapse_funs <- function(x, conn = \" and \") {\n  collapse(paste0(\"`\",x,\"()`\"), conn)\n}\n\nset_language <- function(lang) {\n  message(\"Different languages are no longer supported in testwhat\")\n}\n\nget_ord <- function(index) {\n  switch(index,\n         \"1\" = \"first\", \"2\" = \"second\",\n         \"3\" = \"third\", \"4\" = \"fourth\",\n         \"5\" = \"fifth\", \"6\" = \"sixth\",\n         \"7\" = \"seventh\", sprintf(\"%ith\", index))\n}\n\nget_num <- function(index) {\n  switch(index,\n         \"1\" = \"one\", \"2\" = \"two\",\n         \"3\" = \"three\", \"4\" = \"four\",\n         \"5\" = \"five\", sprintf(\"%i\", index)) \n}\n\nget_times <- function(index) {\n  switch(index,\n         \"1\" = \"\", \"2\" = \" twice\",\n         sprintf(\" %s times\", get_num(index)))\n}\n\nyaml_option_desc <- function(name) {\n  paste0(\"`\", paste0(name, collapse = \":\"), \"`\")\n}\n",
  "messages.R": "build_feedback_message <- function(details) {\n  if (is.character(details)) {\n    return(capitalize(trim(details)))\n  }\n  \n  total_msg <- \"\"\n  for (det in details) {\n    if (!is.null(det$message)) {\n      msg <- det$message\n    } else {\n      class(det) <- det$type\n      msg <- build_message(det)\n    }\n    \n    # only do something if msg is actually a message\n    if (!is.null(msg)) {\n      if (isTRUE(det$append)) {\n        total_msg <- paste(total_msg, msg)\n      } else {\n        total_msg <- msg\n      }\n    }\n  }\n  return(capitalize(trim(total_msg)))\n}\n\nbuild_message <- function(det) {\n  UseMethod(\"build_message\", det)\n}\n\nbuild_message.default <- function(det) {\n  return(NULL)\n}\n\nbuild_message.object <- function(det) {\n  switch(det$case,\n         defined = sprintf(\"Did you define the variable `%s` without errors?\", det$name),\n         correct = sprintf(\"The contents of the variable `%s` aren't correct.\", det$name),\n         equal = build_diff(sol = det$solution, stud = det$student,\n                            eq_condition = det$eq_condition,\n                            id = \"it\"),\n         NULL)\n}\n\nbuild_message.column <- function(det) {\n  switch(det$case,\n         defined = sprintf(\"Does it contain a column `%s`?\", det$name),\n         correct = sprintf(\"The column `%s` doesn't seem to be correct.\", det$name),\n         equal = NULL,\n         NULL)\n}\n\nbuild_message.element <- function(det) {\n  switch(det$case,\n         defined = sprintf(\"Does it contain an element `%s`?\", det$name),\n         correct = sprintf(\"The element `%s` doesn't seem to be correct.\", det$name),\n         equal = NULL,\n         NULL)\n}\n\n\nbuild_message.function <- function(det) {\n  switch(det$case,\n         called = sprintf(\"Have you called `%s()`%s?\", det$name, get_times(det$index)),\n         correct = sprintf(\"Check your call of `%s()`.\", det$name),\n         result_runs = \"Running it again threw an error.\",\n         result_correct = \"Running it again doesn't give the correct result.\",\n         result_equal = build_diff(sol = det$solution, stud = det$student,\n                                   eq_condition = det$eq_condition,\n                                   id = \"the result\"),\n         NULL)\n}\n\nbuild_message.operator <- function(det) {\n  switch(det$case,\n         called = sprintf(\"Have you used the `%s` operator%s?\", det$name, get_times(det$index)),\n         correct = sprintf(\"Have you correctly used the `%s` operator?\", det$name),\n         result_runs = \"Running the operation again threw an error.\",\n         result_correct = \"Running the operation again doesn't give the correct result.\",\n         result_equal = build_diff(sol = det$solution, stud = det$student,\n                                   eq_condition = det$eq_condition,\n                                   id = \"the result\"),\n         NULL)\n}\n\nbuild_message.argument <- function(det) {\n  msg <- NULL\n  if (det$case == \"specified\") {\n    if (det$name == \"...\") {\n      msg <- sprintf(\"Did you specify any arguments that are matched to `...`?\", det$name)\n    } else {\n      msg <- sprintf(\"Did you specify the argument `%s`?\", det$name)\n    }\n  }\n  if (det$case == \"correct\") {\n    if (det$name == \"...\") {\n      msg <- \"Did you correctly specify the arguments that are matched to `...`?\"\n    } else {\n      msg <- sprintf(\"Did you correctly specify the argument `%s`?\", det$name)\n    }\n  }\n  if (det$case == \"equal\") {\n    if (!det$is_dots) {\n      msg <- build_diff(sol = det$solution, stud = det$student,\n                        eq_condition = det$eq_condition,\n                        id = \"it\")  \n    }\n  }\n  return(msg)\n}\n\nbuild_message.if <- function(det) {\n  build_message_control(det, \"if\")\n}\n\nbuild_message.for <- function(det) {\n  build_message_control(det, \"for\")\n}\n\nbuild_message.while <- function(det) {\n  build_message_control(det, \"while\")\n}\n\nbuild_message_control <- function(det, type) {\n  switch(det$case,\n         defined = sprintf(\"Are you sure you coded %s %s statement%s?\", get_num(det$index), type, ifelse(det$index > 1, \"s\", \"\")),\n         correct = sprintf(\"Check the %s %s statement.\", get_ord(det$index), type),\n         NULL)\n}\n\nbuild_message.condition <- function(det) {\n  \"Check the condition.\"\n}\n\nbuild_message.body <- function(det) {\n  \"Check the body.\"\n}\n\nbuild_message.ifexpression <- function(det) {\n  \"Check the if part.\"\n}\n\nbuild_message.elseexpression <- function(det) {\n  switch(det$case,\n         defined = \"The else part is missing.\",\n         correct = \"Check the else part.\",\n         NULL)\n}\n\nbuild_message.typed <- function(det) {\n  if (det$type == \"typed\") {\n    if (det$fixed) {\n      msg <- sprintf(\"Have you typed %s%s?\", collapse_args(det$regex, conn = \" or \"), get_times(det$times))\n    } else {\n      msg <- sprintf(\"The system wanted to find the pattern %s%s but didn't.\", collapse_args(det$regex, conn = \" or \"), get_times(det$times))  \n    }\n  }\n  return(msg)\n}\n\nbuild_message.fundef <- function(det) {\n  switch(det$case,\n         defined = sprintf(\"Did you define the function `%s()`?\", det$name),\n         correcttype = sprintf(\"Are you sure that `%s` is a function?\", det$name),\n         correct = sprintf(\"Did you correctly define the function `%s()`?\", det$name),\n         arguments = \"Did you specify the correct number of arguments?\",\n         coded = sprintf(\"The system couldn't find the function definition of `%s()` in your code.\", det$name),\n         NULL)\n}\n\nbuild_message.expr <- function(det) {\n  switch(det$case, \n         result_runs = sprintf(\"Running `%s` generated an error.\", det$expr_str),\n         result_correct = sprintf(\"Running `%s` didn't give the correct result.\", det$expr_str),\n         result_equal = build_diff(sol = det$solution, stud = det$student,\n                                   eq_condition = det$eq_condition,\n                                   id = \"the result\"),\n         output_runs = sprintf(\"Running `%s` generated an error.\", det$expr_str),\n         output_correct = sprintf(\"Running `%s` didn't generate the correct output.\", det$expr_str),\n         output_equal = sprintf(\"Expected %s, but got %s\",\n                                ifelse(length(det$solution) == 0, \"no output\", sprintf(\"`%s`\", det$solution)),\n                                ifelse(length(det$student) == 0, \"no output\", sprintf(\"`%s`\", det$student))),\n         error_fails = sprintf(\"Running `%s` didn't generate an error, but it should.\", det$expr_str),\n         error_correct = sprintf(\"Running `%s` didn't generate the correct error.\", det$expr_str),\n         error_equal = sprintf(\"Expected the error `%s`, but instead got the error `%s`\",\n                               det$solution, det$student),\n         NULL)\n}\n\nbuild_message.file <- function(det) {\n  msg <- NULL\n  if (det$case == \"available\") {\n    if (det$folder == \".\") {\n      msg <- sprintf(\"The file `%s` does not appear to be in your working directory.\", det$file)\n    } else {\n      msg <- sprintf(\"The file `%s` does not appear to be inside the folder `%s` in your working directory.\", det$file, det$folder)\n    }\n  }\n  return(msg)\n}\n\nbuild_message.output <- function(det) {\n  switch(det$case, \n         regex = \"The output that your code generated doesn't contain the pattern we're looking for.\",\n         expr = sprintf(\"Did your code produce the same output as `%s`?\", det$expr),\n         NULL)\n}\n\n# Markdown Messaging ----------------------------------------------------------\n\nbuild_message.markdown_header <- function(det) {\n  switch(det$case,\n         defined = sprintf(\"Have you included %s level %i header%s in your code?\", get_num(det$index), det$level, if (det$index > 1) \"s\" else \"\"),\n         correct = sprintf(\"Check the %s level %i header.\", get_ord(det$index), det$level)\n  )\n}\n\nbuild_message.markdown_title <- function(det) {\n  switch(det$case,\n         defined = sprintf(\"The system couldn't find a title.\"),\n         correct = sprintf(\"Check the title.\")\n  )\n}\n\nbuild_message.markdown_chunk <- function(det) {\n  switch(det$case,\n         defined = sprintf(\"Have you included %s code chunk%s?\", get_num(det$index), if (det$index > 1) \"s\" else \"\"),\n         correct = sprintf(\"Have a look at the %s code chunk.\", get_ord(det$index))\n  )\n}\n\nbuild_message.markdown_chunk_option <- function(det) {\n  switch(det$case,\n         defined = sprintf(\"Have you specified the chunk option `%s`?\", det$name),\n         correct = sprintf(\"The chunk option `%s` isn't correct.\", det$name),\n         equal = build_diff(sol = det$solution, stud = det$student,\n                            eq_condition = \"equal\", id = \"it\")\n  )\n}\n\nbuild_message.markdown_yaml <- function(det) {\n  switch(det$case,\n         parsing_error = sprintf(\"Something went wrong when parsing the YAML header. Are you sure you indented everything properly?\"),\n         correct = \"Check your YAML header.\"\n  )\n}\n\nbuild_message.markdown_yaml_option <- function(det) {\n  switch(det$case,\n         defined = sprintf(\"Have you specified the YAML header option %s?\", yaml_option_desc(det$name)),\n         correct = sprintf(\"The option %s is not correct\", yaml_option_desc(det$name)),\n         equal = build_diff(sol = det$solution, stud = det$student, eq_condition = \"equal\", id = \"it\")\n  )\n}\n",
  "parse-status.R": "#' @importFrom R6 R6Class\nParseStatus <- R6::R6Class(\"ParseStatus\", \n  public = list(\n    initialize = function() {},\n#     push_state = function(state) {\n#       private$states <- c(private$states, list(state))\n#     },\n#     pop_state = function() {\n#       n <- length(private$states)\n#       if (n == 0) stop(\"no more states\")\n#       tail <- private$states[[n]]\n#       private$states <- private$states[-n]\n#       tail\n#     },\n    push_bracket = function(token) {\n      private$bracket_stack <- c(private$bracket_stack, list(token))\n    },\n    pop_bracket = function(rhs) {\n      n <- length(private$bracket_stack)\n      if (n == 0) {\n        self$add_lint(rhs, sprintf(\"This %s wasn't expected.\", human_name(rhs$type)))\n        return(NULL)\n      } \n      \n      lhs <- private$bracket_stack[[n]]\n      if (complement(lhs$type) != rhs$type) {\n        self$add_lint(lhs, sprintf(\"Make sure to correctly close this %s.\", human_name(lhs$type)))\n        return(NULL)\n      }\n  \n      private$bracket_stack <- private$bracket_stack[-n]\n    },\n\n    add_lint = function(token, message) {\n      private$lints <- c(private$lints, \n                         list(c(token$location, message = paste(fail_msg, message))))\n    },\n\n    lint_present = function() {\n      length(private$lints) > 0\n    },\n\n    get_lint = function(index = 1) {\n      private$lints[[index]]\n    },\n\n    get_finish_lint = function() {\n      n <- length(private$bracket_stack)\n      if (n > 0) {\n        token <- private$bracket_stack[[n]]\n        return(c(token$location, list(message = paste(fail_msg, sprintf(\"Don't forget to close this %s.\", human_name(token$type))))))\n      } else {\n        return(list(message = parse_fallback_msg))\n      }\n    }\n  ),\n  private = list(\n    states = list(),\n    bracket_stack = list(),\n    lints = list()\n  )\n)",
  "parse-token.R": "#' @importFrom R6 R6Class\nRToken <- R6::R6Class(\"RToken\", \n  public = list(\n    type = character(0),\n    location = list(),\n    initialize = function(type, line_start, column_start, line_end, column_end) {\n      self$type = type\n      self$location = list(line_start = line_start,\n                           column_start = column_start, \n                           line_end = line_end, \n                           column_end = column_end)\n    }\n  )\n)\n\n#' @importFrom R6 R6Class\nRTokenCursor <- R6::R6Class(\"RTokenCursor\",\n  public = list(\n    tokens = NULL,\n    initialize = function(code) {\n      tokenizer <- RTokenizer$new(code)\n      token <- tokenizer$next_token()\n      tokens <- list()\n      while (!is.null(token)) {\n        # do away with comments\n        if (token$type != \"COMMENT\") {\n          tokens <- c(tokens, list(token))\n        }\n        token <- tokenizer$next_token()\n      }\n      self$tokens <- tokens\n      private$offset <- 1\n      private$n <- length(tokens)\n    },\n    move_up = function() {\n      if (self$is_at_eod()) {\n        return(invisible(NULL))\n      } else {\n        private$offset <- private$offset + 1\n        return(invisible(self$current_token()))\n      }\n    },\n    move_to_next_token = function() {\n      current <- self$move_up()\n      while (current$type %in% c(\"OTHER\", \"WHITESPACE\", \"COMMENT\", \"STRING\") && !self$is_at_eod()) {\n        current <- self$move_up()\n      }\n    },\n    is_at_eod = function() {\n      private$offset == private$n\n      # TODO make more complete (borrow from RTokenCursor::isAtEndOfDocument)\n    },\n    current_token = function() {\n      self$tokens[[private$offset]]\n    },\n    is_type = function(types) {\n      self$current_token()$type %in% types\n    },\n    get_type = function() {\n      self$current_token()$type\n    }\n  ),\n  private = list(\n    offset = integer(0),\n    n = integer(0)\n  )\n)",
  "parse-tokenizer.R": "#' @importFrom R6 R6Class\nRTokenizer <- R6::R6Class(\"RTokenizer\",\n  public = list(\n    initialize = function(code) {\n      private$data <- strsplit(code, split = \"\")[[1]]\n      private$pos_df <- private$build_pos_df()\n    },\n    next_token = function() {\n      if (private$eol()) {\n        return(NULL)\n      }\n      current <- private$peek()\n      switch(current,\n             '_' = {\n               if (!isTRUE(grepl(\"[a-zA-Z0-9]\", private$peek(-1))) && \n                   isTRUE(private$peek(1) == '_') && \n                   isTRUE(private$peek(2) == \"_\")) {\n                 private$consume_token(\"FILL_IN\", 3)  \n               } else {\n                 private$consume_token(\"OTHER\", 1)\n               }\n             },\n             '(' = private$consume_token(\"LPAREN\", 1),\n             ')' = private$consume_token(\"RPAREN\", 1),\n             '{' = private$consume_token(\"LBRACE\", 1),\n             '}' = private$consume_token(\"RBRACE\", 1),\n             '[' = {\n               if (isTRUE(private$peek(1) == '[')) {\n                 private$push_brace(\"LDBRACKET\")\n                 token <- private$consume_token(\"LDBRACKET\", 2)\n               } else {\n                 private$push_brace(\"LBRACKET\")\n                 token <- private$consume_token(\"LBRACKET\", 1)\n               }\n               token\n             },\n             ']' = {\n               if (isTRUE(private$peek(1) == ']')) {\n                 top <- tail(private$brace_stack, 1)\n                 if (top == \"LDBRACKET\") {\n                   token <- private$consume_token(\"RDBRACKET\", 2)\n                 } else {\n                   token <- private$consume_token(\"RBRACKET\", 1)\n                 }\n               } else {\n                 token <- private$consume_token(\"RBRACKET\", 1)\n               }\n               return(token)\n             },\n             '\"' = private$match_string(),\n             '\\'' = private$match_string(),\n             ' ' = private$match_whitespace(),\n             '\\t' = private$match_whitespace(),\n             '\\r' = private$match_whitespace(),\n             '\\n' = private$match_whitespace(),\n             '#' = private$match_comment(),\n             private$consume_token(\"OTHER\", 1))\n    }\n  ),\n  private = list(\n    data = character(0),\n    pos = 1,\n    pos_df = NULL,\n    build_pos_df = function() {\n      n <- length(private$data)\n      df <- data.frame(line = integer(length(n)), column = integer(length(n)))\n      line <- 1\n      column <- 1\n      for (i in 1:(length(private$data) + 1)) {\n        df[i, 'line'] <- line\n        df[i, 'column'] <- column\n        if (isTRUE(private$data[i] == \"\\n\") || isTRUE(private$data[i] == \"\\r\")) {\n          column <- 1\n          line <- line + 1\n        } else {\n          column <- column + 1\n        }\n      }\n      df\n    },\n    eol = function() {\n      return(private$pos > length(private$data))\n    },\n    peek = function(lookahead = 0) {\n      loc <- private$pos + lookahead\n      if (loc < 0 || loc > length(private$data)) {\n        return(NA)\n      } else {\n        return(private$data[loc])  \n      }\n    },\n    brace_stack = character(0),\n    push_brace = function(el) {\n      private$brace_stack <- c(private$brace_stack, el)\n    },\n    pop_brace = function(el) {\n      n <- length(private$brace_stack)\n      if (n == 0) {\n        stop(\"Can't pop a brace!\")\n      }\n      private$brace_stack <- brace_stack[-n]\n    },\n    consume_token = function(type, len) {\n      if (len == 0 || private$pos - 1 + len > length(private$data)) {\n        return(NULL)\n      }\n      # -1 hack to make it work in the front end (front end is 'up to and including')\n      token <- RToken$new(type = type, \n                          line_start = private$pos_df[private$pos, 'line'],\n                          column_start = private$pos_df[private$pos, 'column'],\n                          line_end = private$pos_df[private$pos + len , 'line'],\n                          column_end = private$pos_df[private$pos + len, 'column'] - 1)\n      private$pos <- private$pos + len\n      return(token)\n    },\n    match_string = function() {\n      start <- private$pos\n      # borrow implementation from rstudio\n      quot <- private$eat()\n      \n      while (!private$eol()) {\n        hit <- private$eat_until(\"[\\'\\\"]\")\n        \n        if (!hit) {\n          break\n        }\n        \n        c <- private$eat()\n        if (c == quot) {\n          # -1 hack to make it work in the front end (front end is 'up to and including')\n          token <- RToken$new(type = \"STRING\", \n                              line_start = private$pos_df[start, 'line'],\n                              column_start = private$pos_df[start, 'column'],\n                              line_end = private$pos_df[private$pos - 1, 'line'],\n                              column_end = private$pos_df[private$pos, 'column'] - 1)\n          return(token)\n        }\n      }\n      line <- private$pos_df[start, 'line']\n      column <- private$pos_df[start, 'column']\n      token <- RToken$new(type = \"INCOMPLETE_STRING\", \n                          line_start = line,\n                          column_start = column,\n                          line_end = line,\n                          column_end = column)\n      return(token)\n    },\n    match_whitespace = function() {\n      private$consume_token(\"WHITESPACE\", len = private$get_match_length(\"\\\\s+\"))\n    },\n    match_comment = function() {\n      private$consume_token(\"COMMENT\", len = private$get_match_length(\"#[^\\n]*\"))\n    },\n    get_match_length = function(patt) {\n      the_str <- paste(private$data[private$pos:length(private$data)], collapse = \"\")\n      matches <- gregexpr(patt, the_str)[[1]]\n      if (any(matches == -1)) {\n        stop(\"Something went wrong in looking for that pattern...\")\n      }\n      if (matches[1] != 1) {\n        stop(\"Pattern match should be at the beginning...\")\n      }\n      attr(matches, \"match.length\")[1]\n    },\n    eat = function() {\n      char <- private$data[private$pos]\n      private$pos <- private$pos + 1\n      return(char)\n    },\n    eat_until = function(patt) {\n      the_str <- paste(private$data[private$pos:length(private$data)], collapse = \"\")\n      matches <- gregexpr(patt, the_str)[[1]]\n      if (any(matches == -1)) {\n        # eat all because no match found\n        private$pos <- length(private$data)\n        return(FALSE)\n      } else {\n        private$pos <- private$pos - 1 + matches[1]\n        return(TRUE)\n      }\n    }\n  )\n)",
  "parse-utils.R": "is_white_space_or_comment <- function(token) {\n  token$type == \"WHITESPACE\" || token$type == \"COMMENT\"\n}\n\ncomplement <- function(type) {\n  switch(type,\n         LPAREN = \"RPAREN\",\n         RPAREN = \"LPAREN\",\n         LBRACE = \"RBRACE\",\n         RBRACE = \"LBRACE\",\n         LDBRACKET = \"RDBRACKET\",\n         RDBRACKET = \"LDBRACKET\",\n         LBRACKET = \"RBRACKET\",\n         RBRACKET = \"LBRACKET\",\n         \"ERROR\")\n}\n\nhuman_name <- function(type) {\n  switch(type,\n         LPAREN = \"parenthesis\",\n         RPAREN = \"parenthesis\",\n         LBRACE = \"curly bracket\",\n         RBRACE = \"curly bracket\",\n         LDBRACKET = \"double bracket\",\n         RDBRACKET = \"double bracket\",\n         LBRACKET = \"bracket\",\n         RBRACKET = \"bracket\",\n         \"ERROR\")\n}\n\nfail_msg <- \"Have a look at the highlighted code in the editor.\"\nparse_fallback_msg <- \"Your code contains a syntax error. Check the console output and try to fix the issue.\"\n",
  "parse.R": "do_parse <- function(code) {\n  cursor <- RTokenCursor$new(code)\n  status <- ParseStatus$new()\n  \n  if (is.null(cursor$tokens)) {\n    return(status$get_finish_lint())\n  }\n  \n  start <- function() {\n  \n    if (cursor$is_type(\"INCOMPLETE_STRING\")) {\n      status$add_lint(cursor$current_token(), \"Make sure to close the string again!\")  \n    }\n    \n    if (cursor$is_type(\"FILL_IN\")) {\n      status$add_lint(cursor$current_token(), \"Replace it with valid R code!\")\n    }\n    \n    if (cursor$is_type(c(\"LPAREN\", \"LBRACE\", \"LBRACKET\", \"LDBRACKET\"))) {\n      status$push_bracket(cursor$current_token())\n      # type <- cursor$get_type()\n      # state <- paste0(\"WITHIN_\", substr(type, 2, nchar(type)), \"S\")\n      # status$push_state(state)\n    }\n    \n    if (cursor$is_type(c(\"RPAREN\", \"RBRACKET\", \"RDBRACKET\", \"RBRACE\"))) {\n      # Leave out the state stuff for now\n      status$pop_bracket(cursor$current_token())\n      # status$pop_state()\n    }\n  \n    if (status$lint_present()) {\n      return(status$get_lint())\n    }\n    \n    if (cursor$is_at_eod()) {\n      return(status$get_finish_lint())\n    }\n    \n    cursor$move_to_next_token()\n    start()\n  }\n  \n  start()\n}\n\n",
  "reporter.R": "get_line_info <- function(feedback) {\n  \n  # take 'highest pd' in list of feedback\n  pd <- NULL\n  disabled <- sapply(feedback, function(det) isTRUE(det$highlighting_disabled))\n  for (i in length(feedback):1) {\n    if (!is.null(feedback[[i]]$pd)) {\n      # if something found, check that it's not behind highlighting disabled\n      if (!any(disabled) || which(disabled) > i) {\n        pd <- feedback[[i]][[\"pd\"]]\n        break\n      }\n    }\n  }\n  \n  if (!isTRUE(try(is.data.frame(pd), silent = TRUE))) {\n    return(NULL)\n  }\n  \n  id <- pd$id[!(pd$parent %in% pd$id)]\n  if (length(id) > 1) {\n    return(list(line_start = min(pd$line1),\n                column_start = min(pd$col1),\n                line_end = max(pd$line2),\n                column_end = max(pd$col2)))\n  }\n  x <- as.list(pd[pd$id == id, c(\"line1\", \"col1\", \"line2\", \"col2\")])\n  names(x) <- c(\"line_start\", \"column_start\", \"line_end\", \"column_end\")\n  x\n}\n\n#' @importFrom markdown markdownToHTML\nto_html <- function(x) {\n  html <- markdownToHTML(text = x, fragment.only = TRUE)\n  gsub(\"<p>(.*?)</p>\", \"\\\\1\", html) #remove <p> tags, coded by front end.\n}\n",
  "rstudio-test-chunk-options.R": "#' Check whether the student defined the correct chunk options (R Markdown\n#' exercises)\n#' \n#' Check whether the student defined the correct chunk options in an R Markdown\n#' exercise\n#' \n#' This test can only be called inside a test_rmd_group() call!\n#' \n#' @param options  Set of options\n#' @param not_called_msg feedback message if option was not specified\n#' @param incorrect_msg  feedback message if option was incorrectly set\n#' @keywords internal\ntest_chunk_options <- function(options = NULL,\n                               not_called_msg = NULL,\n                               incorrect_msg = NULL) {\n  fail_if_v2_only()\n  state <- ex()\n  chunk_number <- state$get(\"chunk_number\")\n  student_chunk <- state$get(\"student_ds_part\")\n  solution_chunk <- state$get(\"solution_ds_part\")\n  \n  # First, check if both student and solution chunk are 'block' class (i.e. code chunks)\n  if (class(solution_chunk) != \"block\") {\n    stop(\"The specified rmd group is not of 'block' class.\")\n  }\n  \n  check_that(is_equal(class(student_chunk), \"block\"), \"Wrong class student chunk\")\n  \n  sol_options <- solution_chunk$params\n  stud_options <- student_chunk$params\n  \n  if (is.null(options)) {\n    options <- names(sol_options)\n    if (length(options) == 0) {\n      return(TRUE)\n    }\n  } \n  \n  # Set up default messages\n  # message if specified function was not called\n  if (is.null(not_called_msg)) {\n    not_called_msg = sprintf(\"Code chunk %i of your submission should contain the option%s %s.\", \n                             chunk_number, if (length(options) == 1) \"\" else \"s\", collapse_props(options))\n  }\n  \n  # message if the properties or not found or set incorrectly\n  if (is.null(incorrect_msg)) {\n    incorrect_msg = sprintf(\"In code chunk %i of your submission, make sure to correctly define the option%s %s.\",\n                            chunk_number, if (length(options) == 1) \"\" else \"s\", collapse_props(options))\n  }\n      \n  # select from sol_options and stud_props the ones to check on\n  #\n  # reverse the list, because in case options are defined multiple times,\n  # the last options are the ones that are seen as valid by RMarkdown\n  sol_options_select = rev(sol_options)[options]\n  stud_options_select = rev(stud_options)[options]\n  if (any(is.na(names(sol_options_select)))) {\n      stop(sprintf(\"You defined options that are not in code chunk %i of the solution\", chunk_number))\n  }\n  \n  no_nas <- any(is.na(names(stud_options_select)))\n  # check if all options available\n  check_that(is_false(no_nas), not_called_msg)\n  \n  \n  # check the equality of stud and solution options.\n  if (!no_nas) {\n    check_that(is_equal(sol_options_select, stud_options_select), incorrect_msg)\n  }\n}\n\n",
  "rstudio-test-pipe.R": "#' Check whether a student used the pipe operator sufficiently (ggvis and dplyr exercises)\n#'\n#' Check whether a student used the pipe sufficiently. By default, the function only checks if\n#' the pipe was used at least once. The user can also select the minimal\n#' number of occurrences of the pipe.\n#'\n#' @param num minimal number of times the pipe operator has to appear (default = 1)\n#' @param absent_msg feedback message in case the student did not use a single pipe.\n#' @param insuf_msg feeback message in case the student did not use the pipe operator sufficiently.\n#' @keywords internal\ntest_pipe <- function(num = 1, absent_msg = NULL, insuf_msg = NULL) {\n  fail_if_v2_only()\n  if (is.null(insuf_msg)) {\n    insuf_msg = sprintf(\"You should use the pipe operator at least %i times in total in your solution code\",num)\n  }\n  ex() %>% check_code(regex = \"%>%\", times = num, missing_msg = insuf_msg)\n}\n",
  "rstudio-test-rmd-group.R": "#' Test a single R Markdown file group (R Markdown exercises)\n#'\n#' Test a single R Markdown file group (R Markdown exercises) with arbitrary testwhat functions.\n#'\n#' @param group_number  Number of the group.\n#' @param code  SCT code to test the group (in curly braces)\n#' @keywords internal\ntest_rmd_group <- function(group_number, code) {\n  fail_if_v2_only()\n  old_state <- ex()\n  on.exit(tw$set(state = old_state))\n  test_env <- old_state$get(\"test_env\")\n  tw$set(state = get_rmd_group(old_state, group_number))\n  eval(substitute(code), envir = test_env)\n}\n\nget_rmd_group <- function(state, group_number) {\n  student_code <- state$get(\"student_code\")\n  solution_code <- state$get(\"solution_code\")\n\n  group_state <- MarkdownState$new(state)\n  group_state <- parse_docs(group_state)\n  \n  solution_ds <- group_state$get(\"solution_ds\")\n  student_ds <- group_state$get(\"student_ds\")\n  \n  if (group_number > length(solution_ds)) {\n    stop(sprintf(\"Invalid group_number (%s), while solution contains only %s parts\",\n                 group_number,length(solution_ds)))\n  }\n  \n  student_ds_part <- student_ds[[group_number]]\n  solution_ds_part <- solution_ds[[group_number]]\n  group_state$set(student_ds_part = student_ds_part,\n                  solution_ds_part = solution_ds_part,\n                  student_code = student_ds_part$input,\n                  solution_code = solution_ds_part$input)\n  \n  # set numbers, to be used in default messages of tests\n  if (class(student_ds_part) == \"block\") {\n    group_state$set(chunk_number = group_number - sum(sapply(student_ds[1:group_number],class) == \"inline\"),\n                    student_pd = build_pd(student_ds_part$input),\n                    solution_pd = build_pd(solution_ds_part$input))\n  } else if (class(student_ds_part) == \"inline\") {\n    group_state$set(inline_number = group_number - sum(sapply(student_ds[1:group_number],class) == \"block\"))\n  }\n  return(group_state)\n}\n\n",
  "rstudio-test-text.R": "#' Test inline text and formatting (Markdown)\n#'\n#' Test inline text and its formatting for R Markdown exercises.\n#' This test can only be called inside a test_rmd_group() call!\n#'\n#' @param text  Text to match (can be a regular expression!)\n#' @param format  the format of the text that the text should be in (\"any\", \"italics\", \"bold\", \"code\", \"inline_code\", \"brackets\", \"parentheses\", \"list\"). \n#' If none of the above, the format string is appended to text in front and in the back and used as a regexp.\n#' @param freq How often the text should appear with this formatting\n#' @param not_called_msg feedback message if the text was not there\n#' @param incorrect_msg  feedback message if the text was not properly formatted\n#'\n#' @keywords internal\ntest_text <- function(text,\n                      format = \"any\",\n                      freq = 1,\n                      not_called_msg = NULL,\n                      incorrect_msg = NULL) {\n  state <- ex()\n  inline_number <- state$get(\"inline_number\")\n  student_inline <- state$get(\"student_ds_part\")\n  solution_inline <- state$get(\"solution_ds_part\")\n  \n  # First, check if both student and solution chunk are 'inline' class\n  if(class(solution_inline) != \"inline\") {\n    stop(\"The specified rmd group is not of 'inline' class.\")\n  }\n  check_that(is_equal(class(student_inline), \"inline\"), \n             feedback = \"The student rmd group is not inline!\")\n        \n  # Set up default messages\n  # message if text was not found\n  if(is.null(not_called_msg)) {\n    not_called_msg = sprintf(\"Inline group %i of your submission should contain the text \\\"%s\\\".\", \n                             inline_number, text)\n  }\n  \n  # message if the properties or not found or set incorrectly\n  if(is.null(incorrect_msg)) {\n    incorrect_msg = sprintf(\"In inline group %i of your submission, make sure to correctly format the text \\\"%s\\\".\",\n                            inline_number, text)\n  }\n  \n  # first, check if text is found in student_inline\n  hits <- gregexpr(pattern = text, student_inline$input)[[1]]\n  check_that(is_false(hits[1] == -1), feedback = not_called_msg)\n  check_that(is_gte(length(hits), freq), feedback = not_called_msg)\n  \n  if(hits[1] == -1 || length(hits) < freq) {\n    return(FALSE)\n  }\n\n  patt <- text;\n  for(i in seq_along(format)) {\n    if(format[i] == \"any\") return(TRUE)\n    else if(format[i] == \"italics\") patt <- paste0(\"((\\\\*\",patt,\"\\\\*)|(_\",patt,\"_))\")\n    else if(format[i] == \"bold\") patt <- paste0(\"((\\\\*{2}\",patt,\"\\\\*{2})|(_{2}\",patt,\"_{2}))\")\n    else if(format[i] == \"code\") patt <- paste0(\"`\",patt,\"`\")\n    else if(format[i] == \"inline_code\") patt <- paste0(\"`r\\\\s*\",patt,\"`\")\n    else if(format[i] == \"brackets\") patt <- paste0(\"\\\\[\",patt,\"\\\\]\")\n    else if(format[i] == \"parentheses\") patt <- paste0(\"\\\\(\",patt,\"\\\\)\")\n    else if(format[i] == \"list\") patt <- paste0(\"[-\\\\*]\\\\s*\",patt)\n    else patt <- paste0(format[i],patt,format[i])\n  }\n\n  hits = gregexpr(pattern = patt, student_inline$input)[[1]]\n  check_that(is_false(hits[1] == -1), feedback = incorrect_msg)\n  check_that(is_gte(length(hits), freq), feedback = not_called_msg)\n}\n",
  "rstudio-test-yaml-header.R": "#' Check yaml header (Markdown)\n#'\n#' Check whether the student specified the correct options in the yaml header (for \n#' R Markdown exercises). This test should be called outside an test_rmd_group call.\n#'\n#' @param options  Set of options. Embedded options have to be specified using the dot notation.\n#' @param check_equality whether or not to actually check the value assigned to the option (default TRUE)\n#' @param not_called_msg feedback message if option was not specified (optional but recommended)\n#' @param incorrect_msg  feedback message if option was incorrectly set (optional but recommended)\n#' @keywords internal\ntest_yaml_header <- function(options = NULL,\n                             check_equality = TRUE,\n                             not_called_msg = NULL,\n                             incorrect_msg = NULL) {\n  fail_if_v2_only()\n  state <- ex()\n  chunk_number <- state$get(\"chunk_number\")\n  student_code <- state$get(\"student_code\")\n  solution_code <- state$get(\"solution_code\")\n\n  yaml_solution <- try(unlist(rmarkdown:::parse_yaml_front_matter(strsplit(solution_code, split = \"\\n\")[[1]])), silent = TRUE)\n  if(inherits(yaml_solution, \"try-error\")) {\n    stop(\"Something wrong with yaml header of solution code!\")\n  }\n  \n  yaml_student <- try(unlist(rmarkdown:::parse_yaml_front_matter(strsplit(student_code, split = \"\\n\")[[1]])), silent = TRUE)\n  check_that(is_false(inherits(yaml_student, \"try-error\")), \n             feedback = \"Make sure the YAML header contains no errors. Beware of erroneous indentation.\")\n  \n  if(is.null(options)) {\n    options <- names(yaml_solution)\n    if(length(options) == 0) {\n      return(TRUE)\n    }\n  } \n  \n  # Set up default messages\n  # message if specified function was not called\n  if(is.null(not_called_msg)) {\n    not_called_msg <- sprintf(\"The YAML header of your submission should contain the option%s %s.\", \n                             if(length(options) == 1) \"\" else \"s\", collapse_props(options))\n  }\n   \n  # message if the properties are not found or set incorrectly\n  if(is.null(incorrect_msg)) {\n    incorrect_msg = sprintf(\"In your YAML header, correctly define the option%s %s.\",\n                            if(length(options) == 1) \"\" else \"s\", collapse_props(options))\n  }\n  \n  # select from sol_options and stud_props the ones to check on\n  sol_options_select = yaml_solution[options]\n  stud_options_select = yaml_student[options]\n  if(any(is.na(names(sol_options_select)))) {\n    stop(sprintf(\"You want to test on yaml options that are not in the solution's yaml header\", chunk_number))\n  }\n  \n  no_nas = any(is.na(names(stud_options_select)))\n  # check if all options available\n  check_that(is_false(no_nas), feedback = not_called_msg)\n  \n  if(!no_nas && check_equality) {\n    check_that(is_equal(sol_options_select, stud_options_select), feedback = incorrect_msg)\n  }\n}\n",
  "state.R": "#' testwhat states.\n#'\n#' Root State has no parent state.\n#' ChildState does have state.\n#' Both inherit from the prototypical State class\n#'\n#' @name state\n\n#' @rdname state\n#' @importFrom R6 R6Class\n#' @export\nState <- R6::R6Class(\"State\",\n                     public = list(\n                       set = function(...) {\n                         els <- list(...)\n                         for (i in seq_along(els)) {\n                           tryCatch(assign(names(els)[i], els[[i]], envir = private),\n                                    error = function(e) {\n                                      stop(sprintf(\"Cannot set '%s'; the name is invalid.\", names(els[i])))\n                                    })\n                         }\n                       },\n                       verify_root = function(fun = deparse(sys.call(-1)[[1]])) {\n                         stop(sprintf(\"`%s()` should only be called from the root state, `ex()`.\", fun))\n                       },\n                       assert_is = function(cls, parent, fun=deparse(sys.call(-1)[[1]])) {\n                         if (!any(class(self) %in% cls)) {\n                           stop(sprintf(\"`%s()` can only be called on `%s()`.\", fun, parent))\n                         }\n                       },\n                       assert_is_not = function(cls, parent, fun=deparse(sys.call(-1)[[1]])) {\n                         if (any(class(self) %in% cls)) {\n                           stop(sprintf(\"`%s()` should not be called on `%s()`.\", fun, parent))\n                         }\n                       }\n                     ),\n                     private = list(\n                       pec = NULL,\n                       student_code = NULL,\n                       student_pd = NULL,\n                       student_env = NULL,\n                       solution_code = NULL,\n                       solution_pd = NULL,\n                       solution_env = NULL,\n                       output_list = NULL,\n                       test_env = NULL,\n                       force_diagnose = FALSE\n                     )\n)\n\n#' @export\nprint.State <- function(x, ...) {\n  cat(paste0(\"<\", class(x)[1], \">\\n\"))\n}\n\n#' @rdname state\n#' @export\nRootState <- R6::R6Class(\"RootState\", inherit = State,\n                         public = list(\n                           initialize = function(...) {\n                             self$set(...)\n                           },\n                           get = function(name) {\n                             return(private[[name]])\n                           },\n                           verify_root = function(...) {\n                             return(TRUE)\n                           }\n                         )\n)\n\n#' @rdname state\n#' @export\nChildState <- R6::R6Class(\"ChildState\", inherit = State,\n                          public = list(\n                            initialize = function(state) {\n                              private$parent = state\n                              # copy details from parent\n                              self$details = private$parent$details\n                            },\n                            get = function(name) {\n                              el <- private[[name]]\n                              if (is.null(el)) {\n                                el <- private$parent$get(name)\n                              }\n                              return(el)\n                            },\n                            add_details = function(...) {\n                              self$details <- c(self$details, list(list(...)))\n                            },\n                            set_details = function(...) {\n                              det <- list(...)\n                              n <- length(self$details)\n                              self$details[[n]][names(det)] <- det\n                            },\n                            details = list()\n                          ),\n                          private = list(\n                            parent = NULL\n                          )\n)\n\n\nCallState <- R6::R6Class(\"CallState\", inherit = ChildState, private = list(student_call = NULL, solution_call = NULL))\nFunctionState <- R6::R6Class(\"FunctionState\", inherit = CallState)\nOperationState <- R6::R6Class(\"OperationState\", inherit = CallState)\n\nCallResultState <- R6::R6Class(\"CallResultState\", inherit = CallState, private = list(student_call_result = NULL,\n                                                                                      solution_call_result = NULL))\nFunctionResultState <- R6::R6Class(\"FunctionResultState\", inherit = CallResultState)\nOperationResultState <- R6::R6Class(\"OperationResultState\", inherit = CallResultState)\n\nArgumentState <- R6::R6Class(\"ArgumentState\", inherit = ChildState, private = list(student_arg = NULL, solution_arg = NULL))\n\nObjectState <- R6::R6Class(\"ObjectState\", inherit = ChildState, private = list(name = NULL, student_object = NULL, solution_object = NULL))\nObjectColumnState <- R6::R6Class(\"ObjectColumnState\", inherit = ObjectState)\nObjectElementState <- R6::R6Class(\"ObjectElementState\", inherit = ObjectState)\n\nFunDefState <- R6::R6Class(\"FunDefState\", inherit = ChildState, private = list(name = NULL, student_object = NULL, solution_object = NULL))\nFunDefArgsState <- R6::R6Class(\"FunDefArgsState\", inherit = FunDefState)\nExprState <- R6::R6Class(\"ExprState\", inherit = ChildState, private = list(expr = NULL))\n\nExprEvalState <- R6::R6Class(\"ExprState\", inherit = ChildState, private = list(student_object = NULL, solution_object = NULL))\nExprResultState <- R6::R6Class(\"ExprResultState\", inherit = ExprEvalState)\nExprOutputState <- R6::R6Class(\"ExprOutputState\", inherit = ExprEvalState)\nExprErrorState <- R6::R6Class(\"ExprErrorState\", inherit = ExprEvalState)\n\nControlState <- R6::R6Class(\"ControlState\", inherit = ChildState, private = list(student_struct = NULL, solution_struct = NULL))\n\nSubState <- R6::R6Class(\"SubState\", inherit = ChildState)\nProxySubState <- R6::R6Class(\"ProxySubState\", inherit = SubState,\n                             public = list(\n                               verify_root = function(fun = deparse(sys.call(-1)[[1]])) {\n                                 private$parent$verify_root(fun)\n                               },\n                               assert_is = function(cls, parent, fun=deparse(sys.call(-1)[[1]])) {\n                                 private$parent$assert_is(cls, parent, fun)\n                               },\n                               assert_is_not = function(cls, parent, fun=deparse(sys.call(-1)[[1]])) {\n                                 private$parent$assert_is_not(cls, parent, fun)\n                               }\n                             ))\n\nRegexState <- R6::R6Class(\"RegexState\", inherit = ChildState)\nFileState <- R6::R6Class(\"FileState\", inherit = ChildState)\nErrorState <- R6::R6Class(\"ErrorState\", inherit = ChildState)\n\nMarkdownState <- R6::R6Class(\"MarkdownState\", inherit = ChildState,\n                             private = list(student_ds = NULL,\n                                            solution_ds = NULL,\n                                            student_ds_part = NULL,\n                                            solution_ds_part = NULL,\n                                            inline_number = NULL,\n                                            chunk_number = NULL))\n\nMarkdownHeaderState <- R6::R6Class(\"MarkdownHeaderState\", inherit = ChildState,\n                                   private = list(student_title = NULL,\n                                                  solution_title = NULL))\n\nMarkdownChunkState <- R6::R6Class(\"MarkdownChunkState\", inherit = ChildState,\n                                  private = list(student_options = NULL,\n                                                 solution_options = NULL))\n\nMarkdownYamlState <- R6::R6Class(\"MarkdownYamlState\", inherit = ChildState,\n                                 private = list(student_yaml = NULL,\n                                                solution_yaml = NULL))\n\nMarkdownOptionState <- R6::R6Class(\"MarkdownOptionState\", inherit = ChildState,\n                                   private = list(student_option = NULL,\n                                                  solution_option = NULL))\nMarkdownChunkOptionState <- R6::R6Class(\"MarkdownChunkOptionState\", inherit = MarkdownOptionState)\nMarkdownYamlOptionState <- R6::R6Class(\"MarkdownYamlOptionState\", inherit = MarkdownOptionState)\n\n#' Get the main state\n#'\n#' \\code{ex()} should be the start of every SCT chain\n#'\n#' @export\nex <- function() {\n  return(tw$get(\"state\"))\n}\n\ndecorate_state <- function(state, stud, sol, el = NULL) {\n  if (is.null(el)) {\n    state$set(student_pd = stud$pd,\n              solution_pd = sol$pd,\n              student_code = stud$code,\n              solution_code = sol$code)\n  } else {\n    state$set(student_pd = stud[[el]]$pd,\n              solution_pd = sol[[el]]$pd,\n              student_code = stud[[el]]$code,\n              solution_code = sol[[el]]$code)\n  }\n}\n\n#' Functions to override solution code (and parse data) and variables in the solution environment.\n#' \n#' Produces a new state with a custom solution code. Mostly useful inside\n#' \\code{check_or}, if you want to test for different cases.\n#' \n#' @param state the state to create a substate from\n#' @param code the solution code to put into the state\n#' @param ... named environment variables to add to or override in the solution environment\n#' \n#' @name override\n\n#' @rdname override\n#' @export\noverride_solution <- function(state, code = NULL, ...) {\n  sub_state <- ProxySubState$new(state)\n  if (!is.null(code)) {\n    sub_state$set(solution_code = code, solution_pd = build_pd(code, silent=FALSE))\n  }\n  env = list(...)\n  if (!is.null(env)) {\n    sub_state$set(solution_env = new.env(parent = globalenv()))\n    for (el in ls(envir = state$get(\"solution_env\"))) {\n      assign(el, get(el, envir = state$get(\"solution_env\")), envir = sub_state$get(\"solution_env\"))\n    }\n    for (i in seq_along(env)) {\n      name <- names(env)[i]\n      val <- env[[i]]\n      assign(name, val, envir = sub_state$get(\"solution_env\"))\n    }\n  }\n  return(sub_state)\n}\n\n#' @rdname override\n#' @export\noverride_solution_code <- function(state, code) {\n  override_solution(state, code = code)\n}\n\n#' @rdname override\n#' @export\noverride_solution_env <- function(state, ...) {\n  override_solution(state, code = NULL, ...)\n}\n\n#' Disable highlighting for any future checks in the chain\n#'\n#' If the function is used right after \\code{ex()}, highlighting is disabled for\n#' the rest of the chain\n#'\n#' If the function used 'deep in a chain', the system will fall back on\n#' highlights that were collected earlier in the state.\n#'\n#' @param state the state to create a substate from\n#'\n#' @export\ndisable_highlighting <- function(state) {\n  sub_state <- ProxySubState$new(state)\n  sub_state$add_details(highlighting_disabled = TRUE)\n  return(sub_state)\n}\n\nassert_state <- function(x, fun = deparse(sys.call(-1)[[1]])) {\n  if (!isTRUE(inherits(x, \"State\"))) {\n    stop(sprintf(\"The first argument to `%s()` should be a state object. Maybe you forgot a dot?\", fun))\n  }\n}\n",
  "success-msg.R": "#' Define the success message\n#' \n#' If all tests in an SCT pass, the student is presented with a \n#' congratulatory message. You can specify this message with\n#' /code{success_msg()}. It does not matter where in the SCT\n#' you specify this message, but at the end makes most sense.\n#' \n#' For multiple choice exercises, the success message is specified\n#' inside \\code{\\link{check_mc}}, so an additional call of \\code{success_msg}\n#' is not necessary.\n#' \n#' @param msg The success message as a character string.\n#' @param praise Whether or not to prepend a message of praise from the \\code{praise} package.\n#' \n#' @export\n#' @importFrom praise praise\nsuccess_msg <- function(msg, praise = FALSE) {\n  if (isTRUE(praise)) {\n    msg <- paste(praise::praise(), msg)\n  }\n  tw$set(success_msg = capitalize(trim(msg)))\n}\n",
  "test_an_object.R": "# Deprecated\n\ntest_an_object <- function(name, \n                           undefined_msg = NULL,\n                           eq_condition = \"equivalent\") {\n  fail_if_v2_only()\n  \n  # Get needed elements from tw\n  student_env <- ex()$get(\"student_env\")\n  solution_env <- ex()$get(\"solution_env\")\n  \n  if (is.null(undefined_msg)) {\n    # Avoid returning this message, always set undefined_msg\n    undefined_msg <- \"There is some object missing in your code.\"\n  }\n  \n  check_defined(name, solution_env)\n  solution <- get(name, envir = solution_env, inherits = FALSE)\n  \n  valid_values <- list()\n  length(valid_values) <- length(ls(student_env))\n  \n  counter <- 1\n  for (student_var in ls(student_env)) {\n    student_value <- get(student_var, envir = student_env, inherits = FALSE)\n    if (identical(class(student_value), class(solution))) {\n      valid_values[[counter]] <- student_value\n      counter <- counter + 1\n    }\n  }\n  \n  if (counter > 1) {\n    correct <- vapply(valid_values[1:counter-1], function(x) { is_equal(x, solution, eq_condition) }, logical(1))\n  } else {\n    correct <- FALSE\n  }\n  \n  check_that(is_true(any(correct)), feedback = undefined_msg)\n}",
  "test-exercise.R": "#' Run all tests for an exercise\n#'\n#' Run all tests for an exercise and report the results (including feedback).\n#' This function is run by R Backend and should not be used by course creators.\n#'\n#' @param sct Submission correctness tests as a character string.\n#' @param ex_type Type of the exercise\n#' @param pec pre-exercise-code\n#' @param student_code character string representing the student code\n#' @param solution_code character string representing the solution code\n#' @param student_env environment containing the objects defined by the student.\n#' @param solution_env environment containing the objects defined by solution code\n#' @param output_list the output structure that is generated by RBackend\n#' @param allow_errors whether or not errors are allowed by RBackend (FALSE by default)\n#' @param force_diagnose whether diagnose tests have to pass even if the checks pass (FALSE by default)\n#' @param seed random seed that is used for SCTs that run expressions (42 by default).\n#'\n#' @return A list with components \\code{passed} that indicates whether all\n#' tests were sucessful, and \\code{feedback} that contains a feedback message.\n#'\n#' @export\ntest_exercise <- function(sct, \n                          ex_type, \n                          pec,\n                          student_code,\n                          solution_code,\n                          student_env,\n                          solution_env,\n                          output_list,\n                          allow_errors = FALSE,\n                          force_diagnose = FALSE,\n                          seed = 42) {\n  # backwards compatibility with older versions of RBackend\n  if (missing(student_env)) {\n    student_env <- globalenv()\n  }\n  \n  # First check if parsing worked out\n  if (any(sapply(output_list, `[[`, \"type\") == \"parse-error\")) {\n    report <- tryCatch(do_parse(student_code),\n                       error = function(e) {\n                         list(message = parse_fallback_msg)\n                       })\n    return(c(list(correct = FALSE), report))\n  } else {\n    # Store everything that's needed locally (initialize does a full reset)\n    tw$clear()\n    tw$set(success_msg = sample(c(\"Good Job!\", \"Well done!\", \"Great work!\"), 1))\n    state <- RootState$new(pec = pec,\n                           student_code = student_code,\n                           student_pd = build_pd(student_code),\n                           student_env = student_env,\n                           solution_code = solution_code,\n                           solution_pd = build_pd(solution_code),\n                           solution_env = solution_env,\n                           output_list = output_list,\n                           test_env = new.env(parent = environment()),\n                           force_diagnose = force_diagnose)\n    tw$set(state = state,\n           stack = TRUE,\n           seed = seed)\n    on.exit(tw$clear())\n    \n    # Execute sct with the DataCamp reporter such that it collects test results\n    res <- run_until_fail(parse(text = sct))\n\n    # If the SCT passed, check whether there is an error as the last step\n    if (isTRUE(res$correct) && !allow_errors) {\n      res <- run_until_fail(ex() %>% check_error())\n    }\n\n    return(post_process(res, ex_type))\n  }\n}\n\n#' Run SCT until it fails\n#'\n#' @param code the SCT script to run as an expression\n#'\n#' @export\nrun_until_fail <- function(code) {\n  tryCatch({\n    # Run the SCT\n    eval(code, envir = tw$get(\"state\")$get(\"test_env\"))\n    # If it got here, the SCT passed\n    return(list(correct = TRUE, message = tw$get(\"success_msg\")))\n  }, sct_failure = function(e) {\n    return(list(correct = FALSE,\n                message = e$message,\n                feedback = attr(e, \"feedback\")))\n  })\n}\n\n\npost_process <- function(res, ex_type) {\n  # convert to HTML\n  res$message <- to_html(res$message)\n  \n  # Only add line info if:\n  # - message is incorrect, and\n  # - exercise is not markdown / rcpp (post-processing of code chunks gives strange things)\n  if (!res$correct && !(ex_type %in% c(\"MarkdownExercise\", \"RCppExercise\"))) {\n    line_info <- get_line_info(res$feedback)\n    if (!is.null(line_info)) {\n      res <- c(res, line_info)\n    }\n  }\n  res$feedback <- NULL\n  return(res)\n}",
  "utils-control.R": "#' @importFrom utils getParseText\nextract_control <- function(pd, keyword, elnames) {\n  if(any(pd$token == keyword)) {\n    # Intersection of parent of ids with the correct keyword WITH\n    # ids that are top-level (whose parent is not in pd) OR\n    # ids of children of top-level parents that have curly brackets\n    parents <- pd$parent[pd$token == keyword]\n    top_level_ids <- pd$id[!(pd$parent %in% pd$id)]\n    top_level_ids_with_curly_brackets <- pd$id[grepl(\"^\\\\s*\\\\{.*?\\\\}\\\\s*$\", pd$text) & pd$id %in% top_level_ids]\n    children_of_curly_brackets <- pd$id[pd$parent %in% top_level_ids_with_curly_brackets]\n    ids <- base::intersect(parents, c(top_level_ids, children_of_curly_brackets))\n                     \n    chop_up_pd <- function(id, elnames) {\n      expr_ids <- pd$id[pd$parent == id & pd$token %in% c(\"expr\", \"forcond\")]\n      sub_codes <- lapply(expr_ids, getParseText, parseData = pd)\n      sub_pds <- lapply(expr_ids, get_sub_pd, pd = pd)\n      out <- mapply(function(code, pd) list(code = code, pd = pd), sub_codes, sub_pds, SIMPLIFY = FALSE)\n      names(out) <- elnames[1:length(out)]\n      out\n    }\n    \n    lapply(ids, chop_up_pd, elnames = elnames)\n  } else {\n    return(list())\n  }\n}\n\nextract_if <- function(pd) {\n  extract_control(pd, keyword = \"IF\", elnames = c(\"cond_part\", \"if_part\", \"else_part\"))\n}\n\nextract_for <- function(pd) {\n  extract_control(pd, keyword = \"FOR\", elnames = c(\"cond_part\", \"expr_part\"))\n}\n\nextract_while <- function(pd) {\n  extract_control(pd, keyword = \"WHILE\", elnames = c(\"cond_part\", \"expr_part\"))\n}\n\n\n",
  "utils-function.R": "# Find all calls to a given function within a piece of code\n#' @importFrom utils getParseText\nfind_function_calls <- function(pd, name, env) {\n  \n  # summarize vs summarise hack\n  if (name == \"summarise\") pd$text <- gsub(\"summarize\", \"summarise\", pd$text)\n  if (name == \"summarize\") pd$text <- gsub(\"summarise\", \"summarize\", pd$text)\n  \n  # Retrieve all function calls from parse information\n  fun_ids <- pd$parent[pd$text == name & pd$token == \"SYMBOL_FUNCTION_CALL\"]\n  \n  lapply(fun_ids, get_call_data, pd = pd, env = env)\n}\n\nget_call_data <- function(fun_id, pd, env) {\n  expr_id <- pd$parent[pd$id == fun_id] \n  \n  # if parent expression contains %>% on left hand side ...\n  siblings <- pd$id[pd$parent == pd$parent[pd$id == expr_id]]\n  if (\"%>%\" %in% pd$text[pd$id %in% siblings] && pd$id[pd$text == \"%>%\" & pd$id %in% siblings] < expr_id) {\n    # ... go one level up, normalize call, and return string\n    expr_id <- pd$parent[pd$id == expr_id]\n    expr_string <- deparse(unpipe(as.call(parse(text = getParseText(pd, expr_id)))[[1]]))\n  } else {\n    expr_string <- getParseText(pd, expr_id)  \n  }\n  expr <- parse(text = expr_string)\n  original_call <- as.call(expr)[[1]]\n  standard_call <- standardize_call(original_call, expr_string, env)\n  function_pd <- get_sub_pd(pd = pd, expr_id)\n  arg_pds <- get_args(function_pd, standard_call)\n  list(call = standard_call, pd = function_pd, args = arg_pds)\n}\n\n# Find all operators in the parse data\n#' @importFrom utils getParseText\nfind_operators <- function(pd, name, env) {\n  parent_ids <- pd$parent[pd$text == name]\n  lapply(parent_ids, function(id) {\n    call <- getParseText(pd, id)\n    pd <- pd[pd$id == id, ]\n    list(call = parse(text = call), pd = pd)\n  })\n}\n\n\nclean <- function(x) {\n  x <- gsub(\"\\\\s\", \"\", x)\n  gsub(\"'\", \"\\\"\", x)\n}\n\nget_args <- function(pd, standard_call) {\n  n <- length(standard_call)\n  if(n == 1) {\n    return(list())\n  }\n  \n  params <- standard_call[-1]\n  args <- lapply(params, function(param) {\n    id <- pd$id[clean(deparse(param)) == clean(pd$text) & pd$token == \"expr\"]\n    list(expr = param, pd = get_sub_pd(pd, id))\n  })\n\n  # Some arguments are not named because passed via ...\n  # Group these arguments in a list\n  m <- length(args)\n  if (is.null(names(args))) {\n    # All are unnamed\n    args <- list(\"...\" = args)\n  } else {\n    hits <- which(names(args) == \"\")\n    if (length(hits) > 0) {\n      # Some arguments not named\n      args[[\"...\"]] <- args[hits]\n      args[hits] <- NULL\n    }\n  }\n  return(args)\n}\n\n\n# Expand argument names of a function call (borrowed from pryr standardise_call)\nstandardize_call <- function(call, call_string, env) {\n  stopifnot(is.call(call))\n  \n  name <- as.character(call[[1]])\n  \n  if (name[[1]] == \"::\") {\n    f <- getExportedValue(name[[2]], name[[3]])\n  } else if (name[[1]] == \":::\") {\n    f <- get(name[[3]], envir = asNamespace(name[[2]]), inherits = FALSE)\n  } else {\n    f <- get(name, env)\n  }\n  \n  a <- args(f)\n  \n  e <- try(match.call(a, call), silent = TRUE)\n  \n  e <- find_S3_call(matched_call = e, call = call, env = env)\n  \n  if (inherits(e, \"try-error\")) {\n    check_that(failure(), \n              sprintf(\"There is something wrong in the following function call **%s**: _%s_\", \n                      call_string,\n                      attr(e,\"condition\")$message))\n  } else {\n    return(e)\n  }\n}\n\n#' @importFrom utils getAnywhere methods\nfind_S3_call <- function(matched_call, call, env) {\n  if (inherits(matched_call, \"try-error\")) {\n    return(matched_call)\n  }\n  call_method <- as.character(matched_call[[1]])\n  met <- try(suppressWarnings(methods(call_method)), silent = TRUE)\n  if (inherits(met, \"try-error\")) {\n    return(matched_call)\n  } else if (length(met) == 0) {\n    return(matched_call)\n  } else if (length(matched_call) < 2) {\n    return(matched_call)\n  } else {\n    call_class <- try(class(eval(matched_call[[2]], env)), silent = TRUE)\n    if (inherits(call_class, \"try-error\")) {\n      return(matched_call)\n    }\n    call_dispatched <- paste(call_method, call_class, sep = \".\")\n    find_call <- rep(FALSE, length(met))\n    for (one_call in call_dispatched) {\n      find_call <- met == one_call\n      if (any(find_call)) {\n        call_dispatched <- one_call\n        break\n      }\n    }\n    if (!any(find_call)) {\n      call_dispatched <- paste(call_method, \"default\", sep = \".\")\n      cal_class <- \"default\"\n      find_call <- met == call_dispatched\n      if (!any(find_call)) {\n        # At this point, we are almost certain the call is a primitive.\n        # Just ignore.\n        return(matched_call)\n      }\n    }\n    find_call <- which(find_call)\n    vis <- attr(met, \"info\")$visible[find_call]\n    if (vis) {\n      f <- args(get(call_dispatched, env))\n    } else {\n      f <- args(getAnywhere(call_dispatched)[1])\n    }\n    return(try(match.call(f, call), silent = TRUE))\n  }\n}\n\n# Convert an expression that uses the pipe operator to a regular embedded expression.\nunpipe <- function(expr) {\n  cnv <- function(x) {\n    lhs <- x[[2]]\n    rhs <- x[[3]]\n    \n    if (any(all.names(rhs) == \"%>%\")) rhs <- decomp(rhs)\n    if (any(all.names(lhs) == \"%>%\")) lhs <- decomp(lhs)\n    \n    # main\n    is_dot <- vapply(rhs, identical, logical(1L), as.name(\".\"))\n    if(any(is_dot)) {\n      rhs[is_dot] <- as.expression(lhs)\n      rhs\t\n    } else if (is.symbol(rhs) || rhs[[1]] == \"function\" || rhs[[1]] == \"(\") {\t\n      as.call(c(rhs, lhs))\t\n    } else if (is.call(rhs)) {\t\n      as.call(c(rhs[[1]], lhs, lapply(rhs[-1], decomp)))\t\n    } else {\t\n      stop(\"missing condition error\")\t\n    }\n  }\n  \n  decomp <- function(x) {\n    if (length(x) == 1) x\n    else if (length(x) == 3 && x[[1]] == \"%>%\") cnv(x)\n    else if (is.pairlist(x)) as.pairlist(lapply(x, decomp))\n    else as.call(lapply(x, decomp))\n  }\n  decomp(expr)\n}\n",
  "utils-learnr.R": "#' A checker function to use with learnr\n#'\n#' For exercise checking, learnr tutorials require a function that learnr can\n#' use in the background to run the code in each \"-check\" chunk and to format\n#' the results into a format that learnr can display. The function must accept a\n#' specific set of inputs and return a specific type of output. Users are not\n#' intended to use the function themselves, but to pass it to the\n#' \\code{exercise.checker} knitr chunk option within the setup chunk of the\n#' tutorial.\n#'\n#' Similar to grader's \\code{grade_learnr()}, testwhat provides\n#' \\code{testwhat_learnr()} for this purpose. To enable exercise checking in\n#' your learnr tutorial, set \\code{tutorial_options(exercise.checker =\n#' testwhat_learnr)} in the setup chunk of your tutorial.\n#'\n#' @param label Label for exercise chunk\n#' @param solution_code R code submitted by the user\n#' @param user_code \tCode provided within the \"-solution\" chunk for the\n#'   exercise.\n#' @param check_code \tCode provided within the \"-check\" chunk for the exercise.\n#' @param envir_result \tThe R environment after the execution of the chunk.\n#' @param evaluate_result The return value from the \\code{evaluate::evaluate}\n#'   function.\n#' @param ... Unused (include for compatibility with parameters to be added in\n#'   the future)\n#'\n#' @return An R list which contains several fields indicating the result of the\n#'   check.\n#' @export\ntestwhat_learnr <- function(label = NULL,\n                            solution_code = NULL,\n                            user_code = NULL,\n                            check_code = NULL,\n                            envir_result = NULL,\n                            evaluate_result = NULL,\n                            ...) {\n  \n  ######### START COPY FROM grade_learnr ##################\n  # Sometimes no user code is provided, but\n  # that means there is nothing to check. Also,\n  # you do not want to parse NULL\n  if (is.null(user_code)) {\n    return(list(\n      message = \"I didn't receive your code. Did you write any?\",\n      correct = FALSE,\n      type = \"error\",\n      location = \"append\"\n    ))\n  }\n  \n  # Sometimes no solution is provided, but that\n  # means there is nothing to check against. Also,\n  # you do not want to parse NULL\n  if (is.null(solution_code)) {\n    return(list(\n      message = \"No solution is provided for this exercise.\",\n      correct = TRUE,\n      type = \"info\",\n      location = \"append\"\n    ))\n  }\n  ######### END COPY FROM grade_learnr ##################\n  \n  setup_state(sol_code = solution_code,\n              stu_code = user_code,\n              sol_env = NULL,\n              stu_env = envir_result,\n              stu_result = evaluate_result)\n  \n  res <- run_until_fail(parse(text = check_code))\n  return(list(message = res$message,\n              correct = res$correct,\n              location = \"append\",\n              type = if(res$correct) \"success\" else \"error\"))\n}\n",
  "utils-pd.R": "#' Build ParseData from string representing code\n#'\n#' @param code character string representing code\n#' @param silent if TRUE, parsing errors are caugt and NULL is returned.\n#' @importFrom utils getParseData\n#' @export\nbuild_pd <- function(code, silent=TRUE) {\n  tryCatch(getParseData(parse(text = code, keep.source = TRUE), includeText = TRUE),\n           error = function(e) {\n             if (silent) {\n               return(NULL)\n             } else {\n               stop(e)\n             }\n           })\n}\n\nget_children <- function(pd, ids) {\n  all_childs <- c()\n  childs <- function(index){\n    kids <- pd$id[ pd$parent %in% index ]\n    if( length(kids) ){\n      all_childs <<- c(all_childs, kids )\n      childs( kids )\n    }\n  }\n  sapply(ids, childs)\n  return(all_childs)\n}\n\nget_sub_pd <- function(pd, ids) {\n  children <- get_children(pd, ids)\n  pd[pd$id %in% c(children, ids), ]\n}\n\nextract_assignments <- function(pd, name) {\n  symbols <- pd[pd$token == \"SYMBOL\" & pd$text == name, ]\n  assigns <- pd[pd$token %in% c(\"LEFT_ASSIGN\", \"RIGHT_ASSIGN\", \"EQ_ASSIGN\"), ]\n  \n  if(nrow(assigns) == 0) return(NULL)\n  \n  sub_pds <- list()\n  for(i in 1:nrow(assigns)) {\n    assign <- assigns[i, ]\n    valid_ids <- get_valid_ids(pd, assign, symbols)\n    if(is.null(valid_ids)) next\n    sub_pd <- get_sub_pd(pd, ids = valid_ids)\n    sub_pds <- c(sub_pds, list(sub_pd))\n  }\n  \n  return(sub_pds)\n}\n\nget_valid_ids <- function(pd, assign, symbols) {\n  if(assign$token == \"EQ_ASSIGN\") {\n    siblings <- pd$id[pd$parent == assign$parent]\n    close_siblings <- siblings[which(siblings == assign$id) + c(-1, 1)]\n    symbol_children <- intersect(union(get_children(pd, close_siblings), close_siblings), symbols$id)\n  } else {\n    symbol_children <- intersect(get_children(pd, assign$parent), symbols$id)  \n  }\n  assign_row <- which(pd$id == assign$id)\n  children_rows <- which(pd$id %in% symbol_children)\n  if(assign$token == \"LEFT_ASSIGN\") {\n    if(any(children_rows < assign_row)) {\n      return(assign$parent)\n    } else {\n      return(NULL)\n    }\n  } else if (assign$token == \"RIGHT_ASSIGN\") {\n    if(any(children_rows > assign_row)) {\n      return(assign$parent)\n    } else {\n      return(NULL)\n    }\n  } else if (assign$token == \"EQ_ASSIGN\") {\n    if(any(children_rows < assign_row)) {\n      return(c(close_siblings, assign$id)) \n    } else {\n      return(NULL)  \n    }\n  } else {\n    stop(\"token not supported\")\n  }\n}\n\n\nextract_object_assignment <- function(pd, name) {\n  if (is.null(pd)) {\n    return(NA)\n  }\n  sub_pds <- extract_assignments(pd, name)\n  if(length(sub_pds) == 1) {\n    return(sub_pds[[1]])\n  } else {\n    return(NA)\n  }\n}\n\n#' @importFrom utils tail getParseText\nextract_function_definition <- function(pd, name) {\n  # body of the function is the last brother of the function keyword\n  sub_pds <- extract_assignments(pd, name)\n  if(length(sub_pds) == 1) {\n    pd <- sub_pds[[1]]\n    function_parents <- pd$parent[pd$token == \"FUNCTION\"]\n    if (length(function_parents) == 0) {\n      return(NULL)\n    }\n    fundefs <- lapply(function_parents, function(function_parent) {\n      last_brother <- tail(pd$id[pd$parent == function_parent], 1)\n      code <- getParseText(pd, last_brother)\n      sub_pd <- get_sub_pd(pd, last_brother)\n      return(list(code = code, pd = sub_pd))\n    })\n    # only the first parent (if there are embbedded definitions)\n    return(fundefs[[1]])\n  } else {\n    return(NULL)\n  }\n  \n}",
  "utils-rmd.R": "build_doc_structure <- function(text) {\n  \n  # Fix markdown format\n  old.format <- knitr::opts_knit$get()\n  knitr::opts_knit$set(out.format = \"markdown\")\n  \n  # Fix pattern business\n  apat <- knitr::all_patterns\n  opat <- knitr::knit_patterns$get()\n  on.exit({\n    knitr::knit_patterns$restore(opat)\n    knitr:::chunk_counter(reset = TRUE)\n    knitr:::knit_code$restore(list())\n    knitr::opts_knit$set(old.format)\n  })\n  knitr::pat_md()\n  \n  # split the file\n  content = knitr:::split_file(lines = knitr:::split_lines(text)) \n  code_chunks <- knitr:::knit_code$get()\n  \n  for(i in seq_along(content)) {\n    if(class(content[[i]]) == \"block\") {\n      label <- content[[i]]$params$label\n      content[[i]]$input <- paste(code_chunks[[label]],collapse = \"\\n\")\n    }\n  }  \n  \n  # remove the inline blocks that contain nothing or only spaces:\n  content[sapply(content, function(part) {\n    all(grepl(pattern = \"^\\\\s*$\", x = part$input.src)) && class(part) == \"inline\"\n  })] <- NULL\n  \n  return(content)\n}\n\nparse_docs <- function(state) {\n  student_code <- state$get(\"student_code\")\n  solution_code <- state$get(\"solution_code\")\n  \n  student_ds <- build_doc_structure(student_code) #list(list(input = \"\"))\n  solution_ds <- build_doc_structure(solution_code) #list(list(input = \"\"))\n  \n  n_student <- length(student_ds)\n  n_solution <- length(solution_ds)\n  n_inline_student <- sum(sapply(student_ds, class) == \"inline\")\n  n_inline_solution <- sum(sapply(solution_ds, class) == \"inline\")\n  n_block_student <- sum(sapply(student_ds, class) == \"block\")\n  n_block_solution <- sum(sapply(solution_ds, class) == \"block\")\n  \n  check_that(is_equal(n_student, n_solution),\n            feedback = sprintf(\"Make sure the structure of your document is OK. The solution expects %i inline (text) blocks and %i code chunks.\", n_inline_solution, n_block_solution))\n  \n  check_that(is_equal(n_inline_student, n_inline_solution), \n            feedback = sprintf(\"Make sure you have the correct amount of inline (text) blocks in your R markdown document. The solution expects %i.\",n_inline_solution))\n  \n  check_that(is_equal(n_block_student, n_block_solution),\n            feedback = sprintf(\"Make sure you have the correct amount of code blocks in your R markdown document. The solution expects %i.\", n_block_solution))\n  \n  check_that(is_true(all.equal(sapply(student_ds, class), sapply(solution_ds, class))),\n            feedback = sprintf(\"Make sure the overall code structure of your document is OK. The soltion expects the following setup: %s.\", \n                               collapse_props(sapply(solution_ds, class), conn = \", \")))\n  \n  if(n_student != n_solution) return(FALSE)\n  if(n_inline_student != n_inline_solution) return(FALSE) \n  if(n_block_student != n_block_solution) return(FALSE)\n  if(!isTRUE(all.equal(sapply(student_ds, class), sapply(solution_ds, class)))) return(FALSE)\n  \n  state$set(student_ds = student_ds)\n  state$set(solution_ds = solution_ds)\n  return(state)\n}",
  "utils-state.R": "#' Set up state for local experimentation.\n#'\n#' It runs both the solution and the student submission, and populates the state\n#' with parse data, output, etc. After running this function, the state is\n#' available thorugh \\code{\\link{ex}}, from which you can start your SCT chains.\n#' In a way, this function is a very light weight version of DataCamp's R Backend.\n#' \n#' @param sol_code Solution script as a string. If it is not specified, the\n#'   student code will be used.\n#' @param stu_code Student submission as a string. If it is not specified, the\n#'   solution code will be used.\n#' @param sol_env Solution environment. If this is specified, the solution code is not rerun.\n#' @param stu_env Student environment. If this is specified, the student code is not rerun.\n#' @param stu_result Result of calling \\code{\\link{evaluate}} on the student code. If this is\n#'   is specified, this overrides the output generated by running \\code{stu_code}.\n#' @param pec Pre-exercise-code as a string\n#' @param ex_type Type of exercise as a string. Defaults to NormalExercise.\n#' @param force_diagnose whether diagnose tests have to pass even if the checks pass (FALSE by default)\n#' @return The exercise state, from which you can start chaining.\n#' @note This function is only supposed to be used locally when experimenting.\n#'   It should never be used in the eventual SCT script of an exercise.\n#' @examples\n#' \\dontrun{\n#' setup_state(\n#'  sol_code = \"a <- 1\",\n#'  stu_code = \"a <- 2\"\n#' )\n#'\n#' ex() %>% check_object('a') %>% check_equal()\n#' }\n#' \n#' @importFrom evaluate evaluate\n#' @export\nsetup_state <- function(sol_code = \"\",\n                        stu_code = \"\",\n                        sol_env = NULL,\n                        stu_env = NULL,\n                        stu_result = NULL,\n                        pec = character(),\n                        ex_type = \"NormalExercise\",\n                        force_diagnose = FALSE) {\n  \n  if (ex_type == \"MarkdownExercise\") {\n    capture_code <- function(lst) {\n      withr::with_tempfile(\"file\", pattern = \"doc\", fileext = \".Rmd\", {\n        write(lst[names(lst)[grepl(\".rmd|.Rmd\", names(lst))]], file = file)\n        res <- knitr::purl(file, documentation = 0, quiet = TRUE)\n        r_code <- paste(readLines(res), collapse = \"\\n\")\n        unlink(res)\n        return(r_code)\n      })\n    }\n    \n    sol_code_to_run <- capture_code(sol_code)\n    stu_code_to_run <- capture_code(stu_code)\n  } else if (ex_type == \"FileExercise\") {\n    sol_code_to_run <- \"\"\n    stu_code_to_run <- \"\"\n  } else if (ex_type == \"RCppExercise\") {\n    populate_tmpfile <- function(code) {\n      file <- tempfile(fileext = \".cpp\")\n      write(code, file)\n      return(file)\n    }\n    sol_file <- populate_tmpfile(sol_code)\n    stu_file <- populate_tmpfile(stu_code)\n    sol_code_to_run <- sprintf(\"sourceCpp('%s', env = tw$get('sol_env'))\", sol_file)\n    stu_code_to_run <- sprintf(\"sourceCpp('%s', env = tw$get('stu_env'))\", stu_file)\n    on.exit(unlink(sol_file))\n    on.exit(unlink(stu_file))\n  } else {\n    sol_code_to_run <- sol_code\n    stu_code_to_run <- stu_code\n  }\n  \n  # Parts of r-backend\n  convert <- function(item, ...) UseMethod(\"convert\")\n  \n  convert.default <- function(item, ...) {\n    list(type = \"output\", payload = gsub(\"\\n+$\", \"\", item))\n  }\n  \n  convert.source <- function(item, ...) {\n    list(type = \"code\", payload = gsub(\"\\n+$\", \"\", item$src))  \n  }\n  \n  convert.message <- function(item, ...) {\n    list(type = \"r-message\", payload = gsub(\"\\n+$\", \"\", item$message))  \n  }\n  \n  convert.warning <- function(item, ...) {\n    list(type = \"r-warning\", payload = paste0(\"Warning message: \", item$message))\n  }\n  \n  convert.error <- function(item, ...) {\n    list(type = \"r-error\", payload = paste0(\"Error: \", item$message))  \n  }\n  \n  if (is.null(sol_env)) {\n    sol_env <- new_env()\n    tw$set(sol_env = sol_env)\n    withr::with_seed(123, {\n      evaluate::evaluate(pec, envir = sol_env, stop_on_error = 2)\n      evaluate::evaluate(sol_code_to_run, envir = sol_env, stop_on_error = 2)\n    })\n  }\n  \n  if (is.null(stu_env)) {\n    stu_env <- new_env()\n    tw$set(stu_env = stu_env)\n    withr::with_seed(123, {\n      evaluate::evaluate(pec, envir = stu_env, stop_on_error = 2)\n      output <- evaluate::evaluate(stu_code_to_run, envir = stu_env)  \n    })\n    formatted_output <- sapply(output, function(x) list(convert(x)))\n  }\n  \n  if (!is.null(stu_result)) {\n    formatted_output <- sapply(stu_result, function(x) list(convert(x)))\n  }\n  \n  tw$clear()\n  tw$set(success_msg = \"Great work!\")\n  \n  state <- RootState$new(\n    pec = pec,\n    student_code = stu_code,\n    student_pd = build_pd(stu_code),\n    student_env = stu_env,\n    solution_code = sol_code,\n    solution_pd = build_pd(sol_code),\n    solution_env = sol_env,\n    output_list = formatted_output,\n    test_env = new.env(parent = environment()),\n    force_diagnose = force_diagnose\n  )\n  \n  # testwhat will access the reporter and state from the tw object\n  tw$set(state = state, stack = TRUE, seed = 42)\n  return(invisible(tw$get(\"state\")))\n}\n\nnew_env <- function() {\n  new.env(parent = globalenv())\n}\n",
  "utils.R": "#' Get the number of hits for a series of regexes\n#'\n#' @param regex vector of regular expressions against which to match\n#' @param x character vector where matches are sought\n#' @param fixed logical. If \\code{TRUE}, \\code{regex} are strings to be matched as is.\n#'\n#' @export\nget_num_hits <- function(regex, x, fixed) {\n  if (length(regex) == 0 || (length(regex) == 1 && nchar(regex) == 0)) {\n    return(0)\n  } else {\n    counts <- sapply(regex, function(patt) {\n      if (!fixed) {\n        patt = paste0('(?s)', patt)\n      }\n      res <- gregexpr(patt, text = x, perl = !fixed, fixed = fixed)[[1]]\n      if (any(res == -1)) {\n        return(0L)\n      } else {\n        return(length(res))\n      }\n    }, USE.NAMES = FALSE)\n    if (length(counts) == 0) {\n      return(0)\n    } else {\n      return(sum(counts))\n    }\n  }\n}\n\nremove_comments <- function(code) {\n  lines <- strsplit(code, \"\\\\n\")[[1]]\n  return(paste0(lines[!grepl(\"^#\", lines)], collapse = \"\\n\"))\n}\n\ncheck_defined <- function(name, sol_env) {\n  if (!exists(name, sol_env, inherits = FALSE)) {\n    stop(paste(name, \"is not defined in your solution environment.\",\n               \"Specify the name of an object that is actually defined in the solution code\"))\n  }\n}\n\ncheck_sufficient <- function(calls, index, name) {\n  if (index > length(calls)) {\n    stop(sprintf(\"Fix either the index argument or the solution code; currently, there aren't %s calls of %s available in the solution.\", index, name))\n  }\n}\n\nv2_only <- function() {\n  env_var <- \"TESTWHAT_V2_ONLY\"\n  Sys.getenv(env_var) != \"\" && Sys.getenv(env_var) == \"1\"\n}\n\nfail_if_v2_only <- function(errmsg = sprintf(\"%s() can no longer be used in SCTs. Use its check equivalent instead.\", deparse(sys.call(-1)[[1]]))) {\n  if (v2_only()) {\n    stop(errmsg)\n  } else {\n    return(invisible(NULL))\n  }\n}\n\nfailure <- function() {\n  FALSE\n}\n\nget_solution_code <- function() { ex()$get(\"solution_code\") }\n\n#' @importFrom magrittr %>%\n#' @export\nmagrittr::`%>%`\n\nassert_is_string <- function(x, sct_name) {\n  if (!is.character(x))\n    stop(x, paste0(sys.call(1)[1], \" requires a string, but received the class\", typeof(x), '.'))\n}\n\ntw_accessors <- function() {\n  tw_data <- list()\n\n  get = function(name) {\n    if(missing(name)) {\n      tw_data\n    } else {\n      tw_data[[name]]\n    }\n  }\n\n  set = function(...) {\n    tw_data <<- merge(list(...))\n    invisible(NULL)\n  }\n\n  clear = function() {\n    tw_data <<- list()\n    invisible(NULL)\n  }\n\n  initialize = function(data) {\n    tw_data <<- data\n    invisible(NULL)\n  }\n\n  merge = function(values) merge_list(tw_data, values)\n  list(get = get, set = set, clear = clear, initialize = initialize)\n}\n\nmerge_list <- function(x, y) {\n  x[names(y)] = y\n  x\n}\n\n#' tw singleton object to access data across SCT chains.\n#'\n#' @export\ntw <- tw_accessors()\n\n"
};
